        'intros' => [
            'custom_fields' => 'Φτιάξτε τις επιπλέον λεπτομέρειες που χρειάζεται ένα είδος αιτήματος - για παράδειγμα ημερομηνία έναρξης και όνομα χρήστη σε μια νέα πρόσληψη - και επιλέξτε σε ποιους τύπους αιτημάτων υπάρχει το καθένα. Κάθε πεδίο αποφασίζει μόνο του αν πρέπει να συμπληρωθεί κατά την καταχώριση του αιτήματος, κατά το κλείσιμο ή και στα δύο, και αν ο αιτών ερωτάται γι\' αυτό στην πύλη.',
            'checklists' => 'Μια λίστα ελέγχου μπορεί να σημειώνει βήματα ως υποχρεωτικά. Εδώ αποφασίζεται τι συμβαίνει αν κάποιος κλείσει ένα αίτημα πριν τσεκαριστούν αυτά τα βήματα.',
            'mandatory_fields' => 'Επιλέξτε ποια πεδία αιτήματος πρέπει να συμπληρωθούν πριν κλείσει ένα αίτημα και τι συμβαίνει όταν κάποιος κλείνει ένα με κάποιο από αυτά κενό. Ο κανόνας ισχύει παντού όπου μπορεί να κλείσει ένα αίτημα: στην οθόνη του αιτήματος, στις μαζικές ενέργειες, στο REST API και στις ροές εργασιών.',
            'departments' => 'Τα τμήματα ομαδοποιούν και δρομολογούν τα αιτήματα στο σωστό τμήμα του οργανισμού σας — δημιουργήστε αυτά που χρησιμοποιεί το service desk σας για να κατηγοριοποιεί και να αναθέτει εργασίες.',
            'teams' => 'Οι ομάδες καθορίζουν σε ποια τμήματα έχουν πρόσβαση οι τεχνικοί. Αναθέστε τμήματα στις ομάδες και μετά αναθέστε τεχνικούς στις ομάδες για να ελέγξετε την πρόσβασή τους.',
            'ticket_types' => 'Οι τύποι αιτημάτων ταξινομούν το είδος ενός αιτήματος (π.χ. Συμβάν, Αίτημα εξυπηρέτησης) — ορίστε τους τύπους που μπορούν να θέτουν οι τεχνικοί σε ένα αίτημα.',
            'ticket_origins' => 'Οι προελεύσεις αιτημάτων καταγράφουν πώς έφτασε ένα αίτημα (π.χ. Email, Τηλέφωνο, Πύλη) — ορίστε τις προελεύσεις από τις οποίες μπορούν να επιλέγουν οι τεχνικοί.',
            'mailboxes' => 'Τα γραμματοκιβώτια συνδέουν το FreeITSM με λογαριασμούς email, ώστε τα εισερχόμενα μηνύματα να γίνονται αιτήματα και οι απαντήσεις να φεύγουν προς τα έξω — προσθέστε και πιστοποιήστε αυτά που παρακολουθεί το service desk σας.',
            'privacy' => 'Ένα αίτημα δεν περιέχει μόνο τη συνομιλία σας με το άτομο που το άνοιξε. Η προώθηση σε έναν προμηθευτή ή η κοινοποίηση σε έναν συνάδελφο βάζει αυτό το μήνυμα στο ίδιο αίτημα — και η απάντησή τους καταλήγει εκεί. Εδώ αποφασίζεται πόσα από αυτά βλέπει ο αιτών στην πύλη αυτοεξυπηρέτησης.',
            'indexing' => 'Το κείμενο μέσα στα συνημμένα διαβάζεται ώστε να μπορεί να αναζητηθεί. Τα αρχεία Word, Excel, PowerPoint και απλού κειμένου τα διαβάζει το ίδιο το FreeITSM τη στιγμή που φτάνουν. Τα PDF, τα παλαιότερα αρχεία Office και τα σαρωμένα έγγραφα χρειάζονται μια ξεχωριστή υπηρεσία ανάγνωσης εγγράφων — ρυθμίστε την στο <strong>Σύστημα &rarr; Ενσωματώσεις &rarr; Apache Tika</strong> — και επειδή αυτά παίρνουν πολύ περισσότερο χρόνο, διαβάζονται στο παρασκήνιο. Αυτοί οι δύο διακόπτες αποφασίζουν πότε γίνεται αυτή η εργασία παρασκηνίου.',
            'merge_behaviour' => 'Όταν δύο αιτήματα αποδεικνύονται το ίδιο πράγμα, ένας τεχνικός μπορεί να τα συγχωνεύσει. Αυτές οι ρυθμίσεις αποφασίζουν τι κάνει αυτό στους αριθμούς αναφοράς που κρατούν οι αιτούντες σας και τι γίνεται με τις συνομιλίες. Ισχύουν για όλους — μια συγχώνευση αλλάζει ό,τι βλέπει ο πελάτης, επομένως δύο τεχνικοί στο ίδιο γραμματοκιβώτιο δεν πρέπει να μπορούν να διαφωνούν σχετικά με αυτό.',
            'reply_templates' => 'Έτοιμες απαντήσεις που οι τεχνικοί σας μπορούν να εισαγάγουν σε μια απάντηση αντί να τις πληκτρολογούν ξανά. Αυτά είναι τα κοινά που βλέπει όλη η ομάδα — τα προσωπικά πρότυπα ενός τεχνικού αποθηκεύονται από το παράθυρο απάντησης και δεν εμφανίζονται εδώ.',
            'rota_shifts' => 'Οι βάρδιες είναι τα πρότυπα εργασίας (π.χ. Πρωινή, Απογευματινή, Εφημερία) που ανατίθενται στους τεχνικούς στο πρόγραμμα βαρδιών προσωπικού — ορίστε τες εδώ πριν φτιάξετε το πρόγραμμα βαρδιών.',
            'analysts' => 'Οι τεχνικοί είναι το προσωπικό που συνδέεται και εργάζεται στα αιτήματα — προσθέστε τους, επαναφέρετε κωδικούς και αναθέστε τους σε ομάδες για να ελέγξετε την πρόσβασή τους.',
            'general' => 'Οι γενικές ρυθμίσεις ελέγχουν πώς συμπεριφέρονται τα αιτήματα - επανάνοιγμα, αναβολή και πόσο διάστημα εμφανίζονται τα μηνύματα και οι συνομιλίες.',
            'statuses' => 'Οι καταστάσεις ροής στις οποίες μπορεί να βρίσκεται ένα αίτημα. Οι καταστάσεις που σημαίνονται ως <em>Κλειστό</em> θεωρούνται τελικές — χρησιμοποιούνται από τις αναφορές, τους μετρητές του watchtower και την αυτόματη ρύθμιση ημερομηνίας κλεισίματος κατά την ανάθεση. Ακριβώς μία κατάσταση είναι η προεπιλογή για τα νέα αιτήματα.',
            'priorities' => 'Οι ζώνες προτεραιότητας που εμφανίζονται στα αιτήματα. Ακριβώς μία προτεραιότητα είναι η προεπιλογή για τα νέα αιτήματα.',
            'rota_locations' => 'Πού εργάζεται κάθε τεχνικός μια συγκεκριμένη ημέρα — χρησιμοποιείται από το πρόγραμμα βαρδιών προσωπικού και εμφανίζεται ως έγχρωμο σήμα σε κάθε καταχώριση. Ακριβώς μία τοποθεσία είναι η προεπιλογή για τις νέες καταχωρίσεις προγράμματος.',
            'email_templates' => 'Αυτοματοποιημένες απαντήσεις email που ενεργοποιούνται από συμβάντα αιτημάτων. Χρησιμοποιείται μόνο το πρώτο ενεργό πρότυπο ανά συμβάν.',
