            'base_url_help' => 'Η διεύθυνση που χρησιμοποιούν οι πάροχοι για να φτάσουν σε αυτή την εγκατάσταση. Ορίστε την και τα webhook URL παρακάτω γίνονται έτοιμα για αντιγραφή και επικόλληση. Αφήστε το κενό για να χρησιμοποιηθεί η διεύθυνση από την οποία περιηγείστε. Δοκιμάζετε τοπικά; Εκτελέστε <code>ngrok http 80</code> και επικολλήστε τη διεύθυνση <code>https://…ngrok-free.dev</code> που εμφανίζει.',
