            'targets_intro' => 'Χρόνοι απόκρισης και επίλυσης για κάθε προτεραιότητα αιτήματος. Οι χρόνοι δίνονται σε λεπτά (60 = 1 ώρα, 240 = 4 ώρες, 1440 = 1 ημέρα). Το ημερολόγιο καθορίζει σε ποιες εργάσιμες ώρες μετράει το ρολόι. Αφήστε το κενό για να παραλειφθεί ο συγκεκριμένος στόχος.',
