            'col_save' => 'Αποθήκευση',
            'calendars_heading' => 'Ημερολόγια εργασίας',
            'calendars_intro' => 'Ορίστε ωράρια εργασίας, ζώνες ώρας και λίστες αργιών. Τα ημερολόγια χρησιμοποιούνται από τους στόχους SLA (παραπάνω) και από μεμονωμένες προτεραιότητες. Ένα ημερολόγιο είναι το προεπιλεγμένο για τις νέες προτεραιότητες.',
            'col_name' => 'Όνομα',
            'col_timezone' => 'Ζώνη ώρας',
            'col_hours' => 'Ώρες',
            'col_holidays' => 'Αργίες',
            'col_default' => 'Προεπιλογή',
            'col_actions' => 'Ενέργειες',
            'notifs_heading' => 'Ειδοποιήσεις παράβασης',
            'notifs_info' => '<strong style="display:block;margin-bottom:6px;font-size:14px;">Πώς λειτουργούν οι κανόνες ειδοποίησης</strong>Κάθε κανόνας έχει τέσσερα μέρη: ένα <strong>πεδίο εφαρμογής</strong>, ένα <strong>έναυσμα</strong>, έναν <strong>στόχο</strong> και μια λίστα <strong>παραληπτών</strong>.<br><br>Το <strong>πεδίο εφαρμογής</strong> μπορεί να είναι είτε <em>Προεπιλογή</em> (ο κανόνας ισχύει για τα αιτήματα κάθε τμήματος) είτε ένα <em>συγκεκριμένο τμήμα</em> (ο κανόνας ισχύει μόνο για τα αιτήματα αυτού του τμήματος).<br>Όταν αξιολογείται ένα αίτημα, το σύστημα αναζητά πρώτα κανόνα που ταιριάζει με το τμήμα του &mdash; αν υπάρχει, κερδίζει αυτός ο κανόνας και η προεπιλογή αγνοείται. Αν δεν υπάρχει κανόνας για το συγκεκριμένο τμήμα, χρησιμοποιείται ο προεπιλεγμένος. Έτσι μπορείτε να ορίσετε λογικές προεπιλογές που καλύπτουν όλα τα τμήματα και έπειτα να κάνετε εξαιρέσεις όπου μια ομάδα έχει διαφορετικές ανάγκες κλιμάκωσης.<br><br>Το <strong>έναυσμα</strong> είναι είτε <em>Προειδοποίηση</em> (το αίτημα ξεπέρασε το όριο προειδοποίησης &mdash; πλησιάζει πιθανή παράβαση) είτε <em>Παράβαση</em> (το αίτημα ξεπέρασε πλέον τον στόχο SLA του &mdash; πραγματική παράβαση). Το καθένα είναι ξεχωριστός κανόνας, ώστε να ειδοποιείτε διαφορετικά άτομα για προειδοποιήσεις και για παραβάσεις.<br><br>Ο <strong>στόχος</strong> είναι ποιο ρολόι SLA παρακολουθείται &mdash; <em>Απόκριση</em>, <em>Επίλυση</em> ή <em>Και τα δύο</em>.<br><br>Οι <strong>παραλήπτες</strong> μπορεί να είναι οποιοσδήποτε συνδυασμός από: τον τρέχοντα ανατεθειμένο τεχνικό του αιτήματος, κάθε τεχνικό στις ομάδες του τμήματος του αιτήματος, έναν συγκεκριμένο τεχνικό ή/και μια λίστα διευθύνσεων email ελεύθερης μορφής (χρήσιμο για κοινά γραμματοκιβώτια ή γέφυρες email προς Slack/Teams).<br><br><strong style="color:var(--warning-text, #92400e);">Χωρίς κανόνες = χωρίς email.</strong> Ακόμη και αν ένα αίτημα παραβιάσει το SLA, δεν θα σταλεί τίποτα μέχρι να προσθέσετε τουλάχιστον έναν κανόνα (ξεκινήστε με ένα ζεύγος Προειδοποίηση + Παράβαση με πεδίο Προεπιλογή, ώστε να καλύπτονται όλα).',
            'notifs_dedup' => 'Κάθε αίτημα στέλνει το πολύ ένα email ανά στόχο και ανά έναυσμα &mdash; ο εργάτης cron παρακολουθεί τι έχει ήδη σταλεί ώστε να μη λαμβάνετε διπλότυπα.',
            'col_scope' => 'Πεδίο εφαρμογής',
            'col_trigger' => 'Έναυσμα',
            'col_target' => 'Στόχος',
            'col_recipients' => 'Παραλήπτες',
            'col_active' => 'Ενεργό',
            'notifs_cron_note' => 'Ο εργάτης cron που στέλνει αυτά τα email βρίσκεται στο <code>cron/sla_breach_check.php</code>. Δείτε το <code>docs/sla-cron-setup.md</code> για τη ρύθμιση του Windows Task Scheduler και του cron σε Linux.',
            'cron_heading' => 'Δραστηριότητα cron',
            'cron_refresh' => 'Ανανέωση',
            'cron_intro' => 'Οι τελευταίες <span id="slaCronRunsLimit">20</span> εκτελέσεις του cron ελέγχου παραβάσεων (CLI και HTTP). Περιλαμβάνονται και τα απορριφθέντα αιτήματα (όριο ρυθμού, αποτυχία ταυτοποίησης), ώστε η ίδια πηγή αλήθειας να εξυπηρετεί τους ελέγχους ορίου ρυθμού και τους ελέγχους ασφάλειας. Διαγράφονται αυτόματα μετά από <strong><span id="slaCronRetentionDays">30</span> ημέρες</strong>· το ελάχιστο διάστημα μεταξύ επιτυχημένων εκτελέσεων είναι <strong><span id="slaCronMinInterval">30</span> δ</strong> (και τα δύο ρυθμίζονται στο <code>system_settings</code>).',
