            'existing_note' => '<strong>Τίποτα από όσα έχουν ήδη αριθμηθεί δεν αλλάζει.</strong> Τα υπάρχοντα αιτήματα κρατούν τον κωδικό που έχουν και κάθε κωδικός που έχει εκδώσει ποτέ το FreeITSM συνεχίζει να λειτουργεί &mdash; ακόμη και στις απαντήσεις σε παλιά email. Αν θέλετε να αριθμηθούν εκ νέου και τα υπάρχοντα αιτήματα, υπάρχει σχετικό εργαλείο παρακάτω. <strong>Δεν θα σας τελειώσουν τα ψηφία:</strong> το πλάτος που επιλέγετε είναι ελάχιστο, οπότε το αίτημα 1.000.001 απλώς παίρνει ένα ψηφίο παραπάνω αντί να προκαλέσει σφάλμα.',
