            'team_folders_all' => 'Όλες τις ομάδες',
            'team_folders_mine' => 'Μόνο τις ομάδες στις οποίες ανήκουν',
            'team_folders_help' => 'Αλλάζει μόνο τη λίστα φακέλων - κανείς δεν χάνει την ορατότητα ενός αιτήματος. Μια ομάδα που διαθέτει αιτήματα που μπορεί να δει ένας τεχνικός εμφανίζεται πάντα, ώστε οι φάκελοι να βγαίνουν στα σύνολα. Οι διαχειριστές βλέπουν πάντα όλες τις ομάδες.',
            'watch_heading' => 'Παρακολούθηση αιτημάτων',
            'watch_help' => 'Για ποια πράγματα ενημερώνονται όσοι παρακολουθούν ένα αίτημα. Ισχύουν επιπλέον και οι δικές ρυθμίσεις ειδοποιήσεων του καθενός.',
            'watch_inactive_label' => 'Όταν απενεργοποιείται κάποιος που παρακολουθεί',
            'watch_inactive_stop' => 'Διακοπή ειδοποιήσεων - διατήρηση των παρακολουθήσεων σε περίπτωση επιστροφής',
            'watch_inactive_remove' => 'Αφαίρεση από κάθε αίτημα που παρακολουθεί',
            'watch_inactive_help' => 'Ένας απενεργοποιημένος αναλυτής δεν ειδοποιείται ποτέ για τίποτα. Η «Διακοπή» κρύβει τις παρακολουθήσεις του και τις επαναφέρει αν ο αναλυτής ενεργοποιηθεί ξανά· η «Αφαίρεση» τις διαγράφει όταν απενεργοποιείται. Η αφαίρεση ισχύει από τη στιγμή της αποθήκευσης.',
            'watch_event_ticket_reply_received' => 'Ο αιτών απαντά',
            'watch_event_ticket_note_added' => 'Προστίθεται σημείωση',
            'watch_event_ticket_status_changed' => 'Αλλάζει η κατάσταση',
            'watch_event_ticket_priority_changed' => 'Αλλάζει η προτεραιότητα',
            'watch_event_ticket_assigned' => 'Το αίτημα ανατίθεται εκ νέου',
            'watch_event_sla_warning' => 'Πλησιάζει τον στόχο SLA του',
            'watch_event_sla_breached' => 'Παραβιάζει τον στόχο SLA του',
            'ai_heading' => 'Βοηθήματα ανάγνωσης AI',
            'ai_desc' => 'Προαιρετικά, και απενεργοποιημένα μέχρι να τα ενεργοποιήσετε: σε αντίθεση με όλα τα άλλα σε αυτή τη σελίδα, χρησιμοποιούν τον δικό σας πάροχο AI και κοστίζουν χρήματα ανά χρήση. Ο πάροχος, το μοντέλο και το κλειδί API ρυθμίζονται μία φορά στην καρτέλα «Καθαρισμός απάντησης». Ό,τι γράφει ένα AI δεν αντικαθιστά ποτέ το αίτημα — η συζήτηση μένει ακριβώς όπως είναι, ολόκληρη.',
            'ai_summary_label' => 'Διατήρηση σύντομης περίληψης AI στην κορυφή κάθε αιτήματος',
            'ai_summary_help' => 'Λίγες γραμμές που λένε πού βρίσκεται το αίτημα, γράφονται κατόπιν αιτήματος και διατηρούνται ενημερωμένες. Εμφανίζουν πάντα πότε γράφτηκαν, πόσα διάβασαν και πόσο έχει προχωρήσει η συζήτηση από τότε. Κάθε έκδοση διατηρείται, ώστε μια χειρότερη περίληψη να μην καταστρέφει ποτέ μια καλύτερη.',
            'ai_auto_label' => 'Αυτόματη ανανέωση μετά από τόσα νέα μηνύματα',
            'ai_auto_help' => 'Το 0 σημαίνει ποτέ — τότε το κουμπί Ανανέωση είναι ο μόνος τρόπος και δεν χρεώνεται ποτέ τίποτα χωρίς να το ζητήσει κάποιος. Η ανανέωση γίνεται μόνο όταν ένας τεχνικός ανοίγει το αίτημα, οπότε μια πολυάσχολη ουρά που κανείς δεν διαβάζει δεν κοστίζει τίποτα.',
            'ai_max_label' => 'Μηνύματα προς ανάγνωση',
            'ai_max_help' => 'Πόσο πίσω διαβάζει μια περίληψη. Ένα μεγαλύτερο αίτημα διαβάζεται από το πιο πρόσφατο άκρο του και η περίληψη το αναφέρει, αντί να περιγράφει μια αρχή που δεν είδε ποτέ.',
            'ai_notes_label' => 'Να διαβάζει τις εσωτερικές σημειώσεις',
            'ai_notes_help' => 'Οι εσωτερικές σημειώσεις συχνά περιέχουν ό,τι δοκιμάστηκε πραγματικά. Είναι έτσι κι αλλιώς μόνο για το προσωπικό — η περίληψη δεν εμφανίζεται ποτέ στον αιτούντα — αλλά απενεργοποιήστε το αν οι σημειώσεις στο γραφείο σας περιέχουν πράγματα που δεν πρέπει να φύγουν από αυτό.',
            'ai_read_label' => 'Προσφορά της επιλογής «Διάβασέ το» σε ένα αίτημα',
            'ai_confidential_label' => 'Εμπιστευτικά αιτήματα και AI',
            'ai_confidential_block' => 'Να μην αποστέλλονται ποτέ στο AI (συνιστάται)',
            'ai_confidential_allow' => 'Αντιμετώπιση όπως κάθε άλλου αιτήματος',
            'ai_confidential_help' => 'Καλύπτει κάθε λειτουργία AI που διαβάζει ένα αίτημα: την περίληψη, το «Διάβασέ το», τον καθαρισμό απάντησης, το «Ρώτα το AI», τις περιλήψεις συγχώνευσης, τα κείμενα γνωσιακής βάσης, τις περιλήψεις καναλιών, την ανάλυση προβλημάτων και το bot του War Room. Ένα εμπιστευτικό αίτημα είτε δεν αποστέλλεται είτε - όταν διαβάζονται πολλά αιτήματα ταυτόχρονα - παραλείπεται ή εμφανίζεται μόνο με τον αριθμό του.',
            'ai_read_help' => 'Ένα κουμπί που διαβάζει ολόκληρο το αίτημα και σας ενημερώνει: τι συνέβη, τι παραμένει άλυτο και τι θα έκανε στη συνέχεια. Ζητείται και διαβάζεται μία φορά, δεν αποθηκεύεται πουθενά.',
            'reopen_help' => 'Ισχύει όπου κι αν επιστρέψει ένας αιτών — η πύλη αυτοεξυπηρέτησης, μια απάντηση στο email ειδοποίησής σας, το WhatsApp ή το web chat. Το αίτημα επιστρέφει στην πρώτη ανοιχτή κατάστασή σας. Επηρεάζονται μόνο τα αιτήματα σε κατάσταση που έχει επισημανθεί ως κλειστή (ορίστε ποιες είναι στις Καταστάσεις).',
        ],
        'privacy' => [
            'third_party_label' => 'Μηνύματα που στέλνονται σε κάποιον άλλον εκτός από τον αιτούντα',
            'opt_hide' => 'Απόκρυψη από τον αιτούντα',
            'opt_hide_help' => 'Το μήνυμα και τα συνημμένα του δεν εμφανίζονται καθόλου στην πύλη του αιτούντος. Συνιστάται: οι περισσότεροι θεωρούν ότι η προώθηση ενός αιτήματος σε προμηθευτή είναι ιδιωτική.',
            'opt_no_attachments' => 'Εμφάνιση του μηνύματος, αλλά όχι των συνημμένων του',
            'opt_no_attachments_help' => 'Ο αιτών βλέπει ότι επικοινωνήσατε με κάποιον άλλον και τι γράφτηκε, αλλά δεν μπορεί να κατεβάσει κανένα συνημμένο αρχείο.',
            'opt_show' => 'Εμφάνιση όλων',
            'opt_show_help' => 'Ο αιτών βλέπει ολόκληρο το αίτημα ακριβώς όπως οι τεχνικοί σας, συμπεριλαμβανομένων των προωθήσεων και των απαντήσεων τρίτων. Αυτή ήταν η συμπεριφορά πριν υπάρξει αυτή η ρύθμιση.',
            'always_visible_note' => '<strong>Πάντα ορατά στον αιτούντα:</strong> τα δικά του μηνύματα και κάθε απάντηση που απευθύνεται σε αυτόν. <strong>Ποτέ ορατές:</strong> οι εσωτερικές σημειώσεις — αυτές κρύβονται από την πύλη ανεξάρτητα από αυτή τη ρύθμιση. Τα μηνύματα στο WhatsApp και στο web chat εμφανίζονται πάντα, επειδή αυτές οι συζητήσεις είναι εξ ορισμού ανάμεσα στον αιτούντα και το γραφείο σας.',
            'timezone' => 'Ζώνη ώρας',
            'timezone_help' => 'Χρησιμοποιείται για την εμφάνιση ημερομηνιών και ωρών σε όλο το σύστημα.',
