        'reply_cleanup' => [
            'intro1' => 'Όταν ένας τεχνικός πληκτρολογεί μια πρόχειρη απάντηση στο παράθυρο σύνταξης του αιτήματος, το κουμπί <strong>✨ Καθαρισμός</strong> την ξαναγράφει ως σωστά διαμορφωμένο email — προσθέτοντας χαιρετισμό «Αγαπητέ/ή [όνομα],», διορθώνοντας τη γραμματική, εφαρμόζοντας τον τόνο που επιλέγετε παρακάτω και κλείνοντας με «Με εκτίμηση,». <strong>Δεν</strong> θα επινοήσει τεχνικές λεπτομέρειες ούτε θα φουσκώσει το περιεχόμενο.',
            'intro2' => 'Αυτή η λειτουργία χρησιμοποιεί το δικό της κλειδί API της Anthropic (ξεχωριστό από το AI του RFP και το AI της Γνωσιακής βάσης), ώστε η χρήση της να εμφανίζεται ως ξεχωριστή γραμμή στον πίνακα χρεώσεων της Anthropic.',
            'tone' => 'Τόνος',
            'tone_friendly' => 'Φιλικός (προεπιλογή)',
            'tone_formal' => 'Επίσημος',
            'tone_brief' => 'Σύντομος',
            'tone_help' => 'Εφαρμόζεται σε κάθε καθαρισμό, εκτός αν αλλάξει εδώ.',
            'custom_label' => 'Προσαρμοσμένες οδηγίες <span style="color: #999; font-weight: normal;">(προαιρετικό)</span>',
            'custom_placeholder' => 'π.χ. Να κλείνεις πάντα με «Ευχαριστώ πολύ,»&#10;Να αναφέρεσαι στην εταιρεία ως «BillCorp»&#10;Να χρησιμοποιείς παντού επίσημη γλώσσα',
            'custom_help' => 'Προστίθεται στο μήνυμα συστήματος που εμφανίζεται στα δεξιά. Χρησιμοποιήστε το για προσαρμογές ειδικές για τον οργανισμό (παραλλαγές κλεισίματος, όνομα εταιρείας, προτιμήσεις γλώσσας). Οι αυστηροί κανόνες ασφαλείας και η μορφή εξόδου θα εξακολουθούν να υπερισχύουν.',
            'prompt_summary' => 'Προβολή μηνύματος συστήματος (μόνο για ανάγνωση)',
            'prompt_panel_intro' => 'Αυτό είναι το πλήρες μήνυμα συστήματος που αποστέλλεται στο Claude σε κάθε καθαρισμό. Το όνομα στον χαιρετισμό αλλάζει ανά αίτημα· ο τόνος αντανακλά την επιλογή σας στα αριστερά. Οι προσαρμοσμένες οδηγίες σας (αν υπάρχουν) προστίθενται στο τέλος κατά την εκτέλεση — δεν εμφανίζονται εδώ, επεξεργαστείτε τες στο πεδίο κειμένου στα αριστερά.',
