        'csat_tab' => [
            'intro1' => 'Όταν κλείνει ένα αίτημα, στείλτε στον αιτούντα ένα σύντομο email έρευνας που ζητά να βαθμολογήσει την εμπειρία από 1 έως 5. Οι απαντήσεις καταγράφονται στον τεχνικό που έκλεισε το αίτημα, ώστε να μπορείτε να δείτε τάσεις CSAT ανά τεχνικό, και εμφανίζονται ως γραφικό στοιχείο στον πίνακα ελέγχου.',
            'intro2' => 'Το email έρευνας ρυθμίζεται στα <a href="#" onclick="event.preventDefault();switchTab(\'email-templates\');">Πρότυπα email</a> &mdash; δημιουργήστε ένα πρότυπο με συμβάν <strong>Έρευνα CSAT</strong> και βάλτε το <code>[csat_link]</code> στο σώμα για να εισαχθεί η διεύθυνση βαθμολόγησης μίας χρήσης.',
            'mode_off' => 'Ανενεργό',
            'mode_off_help' => 'Δεν στέλνονται email έρευνας.',
            'mode_auto' => 'Αυτόματα στο κλείσιμο',
            'mode_auto_help' => 'Η έρευνα στέλνεται αυτόματα όταν ένα αίτημα περνά σε οποιαδήποτε κλειστή κατάσταση.',
            'mode_manual' => 'Μόνο χειροκίνητα',
            'mode_manual_help' => 'Οι τεχνικοί πατούν <em>Σχόλια</em> από τη γραμμή εργαλείων του αιτήματος όταν θέλουν να ρωτήσουν.',
            'delay_help' => 'Αναμονή τόσων λεπτών μετά το κλείσιμο πριν από την αποστολή. <code>0</code> = άμεσα. Χρήσιμο αν θέλετε ο χρήστης να επιβεβαιώσει ότι η διόρθωση άντεξε πριν του ζητηθεί βαθμολογία. Ένα αίτημα που ανοίγει ξανά πριν από τότε δεν λαμβάνει έρευνα· αν κλείσει ξανά, η αναμονή ξεκινά από την αρχή.',
            'reminder' => 'Αποστολή μίας υπενθύμισης αν δεν απαντηθεί η έρευνα',
            'reminder_hours' => 'Υπενθύμιση μετά από (ώρες)',
            'reminder_help' => 'Το πολύ μία υπενθύμιση, με email, με τον ίδιο σύνδεσμο - έτσι λειτουργεί όποιο από τα δύο email και κρατείται μόνο μία βαθμολογία. Δεν αποστέλλεται αν το αίτημα έχει ανοίξει ξανά. Χρησιμοποιεί το πρότυπο email <strong>Υπενθύμιση CSAT</strong> αν υπάρχει, αλλιώς ξανά το πρότυπο της έρευνας. Η ενεργοποίηση δεν υπενθυμίζει τίποτα για παλιές έρευνες: μόνο για εκείνες που η υπενθύμισή τους λήγει από τώρα και στο εξής.',
            'one_per_ticket' => 'Μία έρευνα ανά αίτημα',
            'one_per_ticket_help' => 'Αν είναι ενεργό, ένα αίτημα που ανοίγει ξανά και κλείνει λαμβάνει νέα έρευνα μόνο όταν την ενεργοποιήσει χειροκίνητα ένας τεχνικός &mdash; αποτρέπει τον κατακλυσμό ενός ασταθούς αιτήματος με έρευνες.',
            'in_channel' => 'Ερώτηση πελατών συνομιλίας μέσα στη συνομιλία τους',
            'in_channel_help' => 'Ένας πελάτης που έγραψε από WhatsApp, Telegram, Slack, Teams ή Mattermost ρωτιέται σε αυτή τη συνομιλία &mdash; με κουμπιά όπου τα διαθέτει η εφαρμογή, με «απαντήστε από 1 έως 5» όπου δεν τα διαθέτει &mdash; αντί για email. Στο WhatsApp μόνο όσο είναι ανοιχτό το παράθυρο των 24 ωρών· αλλιώς, και αν αποτύχει ένα μήνυμα συνομιλίας, χρησιμοποιείται η έρευνα με email.',
