    'help' => [
        'case' => [
            'nav' => 'Αναφορές υποθέσεων',
            'heading' => 'Αναφορές υποθέσεων',
            'intro' => 'Όταν ένας ελεγκτής ή ένας επιθεωρητής ρωτά πώς χειρίστηκε μια υπόθεση, η <strong>Εξαγωγή</strong> συγκεντρώνει το αίτημα, τη συνομιλία του και τις εργασίες που έγιναν σε ένα εκτυπώσιμο έγγραφο - ώστε κανείς να μην χρειάζεται να τα αντιγράφει με το χέρι.',
            'step1' => '<strong>Ανοίξτε το αίτημα</strong> και επιλέξτε <strong>Εξαγωγή</strong> στη γραμμή εργαλείων του (κάτω από το <strong>Περισσότερα</strong> όταν το παράθυρο ανάγνωσης είναι στενό). Η αναφορά ανοίγει σε νέα καρτέλα. Για μια εργασία χωρίς αίτημα, χρησιμοποιήστε το κουμπί εγγράφου στο πάνω μέρος του παραθύρου της εργασίας.',
            'step2' => '<strong>Επιλέξτε τι θα περιλαμβάνεται</strong> στον πίνακα αριστερά. Η αναφορά ξανασχεδιάζεται καθώς επιλέγετε και τίποτα δεν καταγράφεται όσο κάνετε τις επιλογές σας.',
            'step3' => '<strong>Επιλέξτε τη διάταξη</strong>: εξώφυλλο, σελίδα περιεχομένων, κάθε ενότητα σε νέα σελίδα και κεφαλίδα με αριθμούς σελίδων.',
            'step4' => '<strong>Εκτυπώστε</strong> και μετά επιλέξτε <em>Αποθήκευση ως PDF</em> στο παράθυρο εκτύπωσης. Απενεργοποιήστε τις <em>Κεφαλίδες και υποσέλιδα</em> του ίδιου του προγράμματος περιήγησης - η αναφορά εκτυπώνει τις δικές της.',
            'contents' => '<strong>Τι περιλαμβάνεται:</strong> μια επισκόπηση του αιτήματος (με τα προσαρμοσμένα πεδία, τα συσχετισμένα πάγια, τα στοιχεία διαμόρφωσης και τα σχετικά αιτήματα)· κάθε μήνυμα, με το παλαιότερο πρώτο· οι σημειώσεις· οι λίστες ελέγχου του αιτήματος· κάθε συσχετισμένη εργασία με τις υποεργασίες της, τα αποτελέσματα των λιστών ελέγχου και τις σημειώσεις εξαιρέσεων, τις απαντήσεις φορμών, τις διαδικασίες που ακολουθήθηκαν, τις ενέργειες παρακολούθησης και τα σχόλια· το ιστορικό του αιτήματος και κάθε εργασίας· και ένα ευρετήριο των εγγράφων και των συνημμένων email, με το ψηφιακό αποτύπωμα που κατέγραψε το FreeITSM για κάθε έγγραφο.',
            'layout' => '<strong>Διάταξη:</strong> η σελίδα περιεχομένων απαριθμεί κάθε ενότητα και εργασία, και κάθε καταχώριση είναι σύνδεσμος στο αποθηκευμένο PDF. Η κεφαλίδα και οι αριθμοί σελίδων (<em>Σελίδα 3 από 12</em>) απαιτούν πρόσφατο Chrome ή Edge· άλλα προγράμματα περιήγησης εκτυπώνουν την αναφορά χωρίς αυτά.',
            'who' => '<strong>Ποιος βλέπει τι:</strong> η αναφορά δείχνει μόνο όσα θα μπορούσατε να δείτε στην οθόνη. Οι εργασίες, τα πάγια, τα στοιχεία διαμόρφωσης, τα σχετικά αιτήματα, τα έγγραφα και οι απαντήσεις φορμών ελέγχονται ο καθένας με τον δικό του κανόνα, και ό,τι δεν επιτρέπεται να δείτε <em>μετριέται</em> - ποτέ δεν κατονομάζεται - ώστε ο αναγνώστης να ξέρει ότι κάτι παραλείφθηκε. <strong>Οι εσωτερικές σημειώσεις παραλείπονται εκτός αν τις επιλέξετε</strong>, επειδή μια αναφορά συνήθως φεύγει από την ομάδα.',
            'recorded' => '<strong>Τι καταγράφεται:</strong> η εκτύπωση γράφει μια γραμμή <em>Αναφορά υπόθεσης</em> στο ίχνος ελέγχου του αιτήματος, με το ποιος την εκτύπωσε και ποιες ενότητες κάλυπτε. Η προεπισκόπηση και η αλλαγή των επιλογών δεν καταγράφουν τίποτα.',
            'note' => 'Μια αναφορά υπόθεσης είναι αντίγραφο της εγγραφής, όχι σύνοψη: τίποτα δεν αναδιατυπώνεται ή συνοψίζεται, οι εικόνες μέσα στα email δεν αναπαράγονται, τα αρχεία απαριθμούνται αντί να περιλαμβάνονται, και εμφανίζεται μόνο το ιστορικό που κατέγραψε πραγματικά το FreeITSM. Μια ενότητα που δεν μπορεί να διαβαστεί το δηλώνει με κόκκινο αντί να φαίνεται κενή.',
        ],
        'workspace' => [
            'nav' => 'Χώρος εργασίας και πίνακας αιτημάτων',
            'heading' => 'Ο χώρος εργασίας και ο πίνακας αιτημάτων',
            'intro' => 'Δύο ακόμη τρόποι να δουλεύετε τα αιτήματα, και οι δύο προαιρετικοί. Ο <strong>χώρος εργασίας</strong> διαμορφώνει ένα αίτημα για δουλειά και όχι για ανάγνωση. Ο <strong>πίνακας αιτημάτων</strong> εμφανίζει τη λίστα των αιτημάτων ως πίνακα που μπορείτε να φιλτράρετε, να ταξινομήσετε και να αποθηκεύσετε.',
            'ws_title' => 'Ο χώρος εργασίας',
            'ws_what' => 'Στον χώρο εργασίας οι ιδιότητες του αιτήματος βρίσκονται σε στήλη αριστερά, και η <strong>Συνομιλία</strong>, η <strong>Εργασία</strong> (λίστες ελέγχου και συσχετισμένες εργασίες), οι <strong>Συσχετίσεις</strong>, ο <strong>Χρόνος και SLA</strong> και το <strong>Ιστορικό</strong> είναι καρτέλες δίπλα τους. Η γραμμή εργαλείων και όλα τα στοιχεία ελέγχου είναι ίδια με του παραθύρου ανάγνωσης - αλλάζει μόνο η θέση τους. Η <strong>λίστα ελέγχου</strong> ενός αιτήματος απαριθμεί κάθε βήμα με το πλαίσιο ελέγχου του στην καρτέλα Εργασία· το <strong>Σύμπτυξη</strong> δείχνει μόνο το επόμενο βήμα (το θυμάται το πρόγραμμα περιήγησής σας) και το <strong>Αποσπάστε</strong> το ανοίγει ακόμη σε δικό του παράθυρο.',
            'ws_admin' => '<strong>Ένας διαχειριστής το ενεργοποιεί</strong> στο <strong>Αιτήματα &rarr; Ρυθμίσεις &rarr; Γενικά &rarr; Χώρος εργασίας αιτημάτων</strong>: <em>Ανενεργός</em> (η προεπιλογή), <em>Μόνο αιτήματα που έγιναν χώρος εργασίας</em> ή <em>Κάθε αίτημα</em>.',
            'ws_make' => '<strong>Μετατροπή ενός αιτήματος σε χώρο εργασίας:</strong> στη μεσαία ρύθμιση, ανοίξτε το αίτημα και επιλέξτε <strong>Περισσότερα &rarr; Δημιουργία χώρου εργασίας</strong> (και <strong>Πίσω στο παράθυρο ανάγνωσης</strong> για να το αναιρέσετε). Ανήκει στο αίτημα, οπότε όλοι όσοι το δουλεύουν το βλέπουν με τον ίδιο τρόπο, και καταγράφεται στο ιστορικό του αιτήματος.',
            'ws_own' => '<strong>Η δική σας επιλογή:</strong> όταν είναι ενεργός, το <strong>Χρήση του χώρου εργασίας</strong> στο μενού φίλτρων της λίστας, ή στο <strong>Σύστημα &rarr; Προτιμήσεις</strong>, τον απενεργοποιεί μόνο για εσάς. Ένα αίτημα που έγινε χώρος εργασίας εμφανίζει τότε ένα μικρό σήμα <em>Χώρος εργασίας</em>, ώστε να ξέρετε ότι ένας συνάδελφος το δουλεύει με αυτόν τον τρόπο.',
            'ws_checklist' => '<strong>Οι λίστες ελέγχου του αιτήματος απαριθμούν κάθε βήμα:</strong> στην καρτέλα <strong>Εργασία</strong> μια λίστα ελέγχου δείχνει όλα τα βήματά της με τα πλαίσια ελέγχου τους. Το <strong>Σύμπτυξη</strong> τη μειώνει μόνο στο επόμενο βήμα, όπως την εμφανίζει το παράθυρο ανάγνωσης, και το <strong>Ανάπτυξη</strong> επαναφέρει τα υπόλοιπα - το πρόγραμμα περιήγησής σας θυμάται ποια επιλογή κάνατε. Το <strong>Αποσπάστε</strong> ανοίγει ακόμη ολόκληρη τη λίστα ελέγχου σε παράθυρο.',
            'ws_tasks' => '<strong>Οι συσχετισμένες εργασίες ανοίγουν επιτόπου:</strong> κάντε κλικ σε μια εργασία στην καρτέλα <strong>Εργασία</strong> και ο δικός της επεξεργαστής ανοίγει εκεί - μαζί με λίστες ελέγχου, φόρμες, διαδικασίες, υποεργασίες, σχόλια και έγγραφα. Το <strong>Άνοιγμα χωριστά</strong> την ανοίγει σε δικό της παράθυρο όπως πριν· το ίδιο κάνει και το Ctrl-κλικ. Χρειάζεστε πρόσβαση στις Εργασίες για να την επεξεργαστείτε.',
            'ws_safe' => '<strong>Τίποτα μισογραμμένο δεν χάνεται:</strong> αν μετακινηθείτε σε άλλο αίτημα, ή απενεργοποιήσετε τον χώρο εργασίας, ενώ υπάρχει μη αποθηκευμένη απάντηση, σημείωση ή αλλαγή εργασίας, σας ρωτά πρώτα και περιμένει να ολοκληρωθεί ό,τι αποθηκεύεται ακόμη.',
            'tb_title' => 'Ο πίνακας αιτημάτων',
            'tb_what' => 'Επιλέξτε <strong>Πίνακας</strong> αντί για <strong>Μηνύματα</strong> στη γραμμή ενεργειών στο πάνω μέρος των Αιτημάτων (ή στο <strong>Σύστημα &rarr; Προτιμήσεις</strong>). Ο φάκελος όπου βρίσκεστε γίνεται το φίλτρο του πίνακα· επιλέξτε στήλες, φιλτράρετέ τες και ταξινομήστε τες, κάντε αναζήτηση και προχωρήστε στη λίστα ανά 25, 50 ή 100 αιτήματα. Η <strong>Αποθήκευση προβολής</strong> κρατά μια διάταξη για εσάς, την ομάδα σας ή όλους.',
            'tb_same' => 'Το κλικ, το Ctrl- και Shift-κλικ, το δεξί κλικ, η μεταφορά σε φάκελο και οι μαζικές ενέργειες λειτουργούν όπως στη λίστα μηνυμάτων, και ο πίνακας δεν δείχνει ποτέ αίτημα που δεν θα έδειχνε η λίστα.',
            'tb_export' => '<strong>Εξαγωγή CSV:</strong> το κουμπί CSV εξάγει <em>κάθε</em> αίτημα που ταιριάζει, όχι μόνο τη σελίδα, με τις στήλες που εμφανίζετε. Ποιος μπορεί να το χρησιμοποιήσει ορίζεται στο <strong>Αιτήματα &rarr; Ρυθμίσεις &rarr; Γενικά &rarr; Ποιος μπορεί να εξάγει τη λίστα αιτημάτων</strong>: μόνο οι διαχειριστές (η προεπιλογή), όποιος έχει πρόσβαση στα Αιτήματα ή κανείς. Το κουμπί δεν εμφανίζεται σε όποιον δεν επιτρέπεται να το χρησιμοποιήσει.',
        ],
        'page_title' => 'Service Desk - Οδηγός Αιτημάτων',
        'sidebar_title' => 'Οδηγός',
        'hero_title' => 'Οδηγός της ενότητας Αιτήματα',
        'hero_sub' => 'Καταγράψτε, παρακολουθήστε και επιλύστε αιτήματα υποστήριξης IT από ένα ενιαίο εισερχόμενο με φακέλους &mdash; φτιαγμένο για ομάδες service desk.',
        'nav' => [
            'overview' => 'Επισκόπηση',
            'inbox' => 'Τα εισερχόμενα',
            'working_with_tickets' => 'Εργασία με αιτήματα',
            'working_faster' => 'Ταχύτερη εργασία',
            'comments_attachments' => 'Σχόλια &amp; συνημμένα',
            'ai_tools' => 'Εργαλεία AI',
            'csat' => 'Έρευνες CSAT',
            'user_management' => 'Διαχείριση χρηστών',
            'dashboard' => 'Πίνακας ελέγχου',
            'calendar_rota' => 'Ημερολόγιο &amp; πρόγραμμα βαρδιών',
            'settings' => 'Ρυθμίσεις',
            'tips' => 'Γρήγορες συμβουλές',
            'companies' => 'Εταιρείες',
        ],
        'overview' => [
            'heading' => 'Επισκόπηση',
            'intro' => 'Η ενότητα Αιτήματα είναι ο πυρήνας του service desk IT σας. Προσφέρει μια οικεία διεπαφή τύπου προγράμματος email για τη διαχείριση αιτημάτων υποστήριξης, συμβάντων και εργασιών εξυπηρέτησης. Τα αιτήματα φτάνουν από τους τελικούς χρήστες με email ή χειροκίνητη δημιουργία, και οι τεχνικοί τα δουλεύουν με φακέλους, προτεραιότητες και χρονόμετρα SLA &mdash; ό,τι χρειάζεστε για γρήγορη υποστήριξη IT.',
            'card_inbox_title' => 'Εισερχόμενα',
            'card_inbox_body' => 'Ένα εισερχόμενο με φακέλους, σαν πρόγραμμα email. Περιηγηθείτε στους φακέλους Τα αιτήματά μου, Χωρίς ανάθεση, Όλα τα ανοιχτά και Κλειστά. Κάντε κλικ σε οποιοδήποτε αίτημα για να ανοίξει ένα παράθυρο ανάγνωσης με πλήρεις λεπτομέρειες, ιστορικό και ενέργειες.',
            'card_dashboard_title' => 'Πίνακας ελέγχου',
            'card_dashboard_body' => 'Φτιάξτε έναν εξατομικευμένο πίνακα ελέγχου με προσαρμόσιμα γραφικά στοιχεία Chart.js. Οπτικοποιήστε τον όγκο αιτημάτων, τους χρόνους απόκρισης, την ανάλυση ανά κατηγορία και τον φόρτο των τεχνικών με ραβδογράμματα, πίτες, ντόνατ και γραμμικά διαγράμματα.',
            'card_calendar_title' => 'Ημερολόγιο',
            'card_calendar_body' => 'Δείτε τα αιτήματα σε πλέγμα ημερολογίου με βάση τις ημερομηνίες δημιουργίας, προθεσμίας ή επίλυσης. Εντοπίστε γρήγορα τα καθυστερημένα και προγραμματίστε την εβδομάδα σας βλέποντας το σύνολο των αιτημάτων με μια ματιά.',
            'card_rota_title' => 'Πρόγραμμα βαρδιών',
            'card_rota_body' => 'Προγραμματίστε τις βάρδιες των τεχνικών και τις εφημερίες. Δείτε ποιος είναι διαθέσιμος ανά πάσα στιγμή, σχεδιάστε την κάλυψη για Σαββατοκύριακα και αργίες και φροντίστε να μην μένει κανένα αίτημα χωρίς φροντίδα.',
        ],
        'inbox' => [
            'heading' => 'Τα εισερχόμενα',
            'intro' => 'Τα εισερχόμενα είναι ο βασικός χώρος εργασίας των τεχνικών. Χρησιμοποιούν διάταξη τριών παραθύρων &mdash; φάκελοι αριστερά, λίστα αιτημάτων στη μέση και παράθυρο ανάγνωσης δεξιά &mdash; ώστε να κάνετε διαλογή και να απαντάτε χωρίς να φύγετε ποτέ από τη σελίδα.',
            'p_live' => '<strong>Ενημερώνονται μόνα τους.</strong> Κάθε λεπτό τα εισερχόμενα ελέγχουν τα γραμματοκιβώτιά σας και αναζητούν ό,τι νέο υπάρχει στα αιτήματα που μπορείτε να δείτε &mdash; ένα email που συλλέχθηκε στο παρασκήνιο, ένα μήνυμα WhatsApp, Telegram, Slack, Teams ή Mattermost, η απάντηση ενός συναδέλφου &mdash; και όταν έχει φτάσει κάτι, η λίστα και οι μετρητές των φακέλων ανανεώνονται μόνοι τους, όπως ακριβώς με το κουμπί ανανέωσης. Το αίτημα που διαβάζετε και η απάντηση που πληκτρολογείτε μένουν ανέγγιχτα.',
            'p_folders' => 'Ο πίνακας φακέλων οργανώνει τα αιτήματα σε λογικές ομάδες. Κάθε φάκελος δείχνει έναν μετρητή μη αναγνωσμένων, ώστε να εντοπίζετε αμέσως τη νέα δουλειά:',
            'field_my' => '<strong>Τα αιτήματά μου</strong> &mdash; αιτήματα που σας έχουν ανατεθεί. Είναι η προσωπική σας ουρά και το καλύτερο σημείο για να ξεκινάτε κάθε μέρα.',
            'field_unassigned' => '<strong>Χωρίς ανάθεση</strong> &mdash; αιτήματα που έχουν φτάσει αλλά δεν έχουν ακόμη τεχνικό. Διαλέξτε από εδώ για να αναλάβετε.',
            'field_all_open' => '<strong>Όλα τα ανοιχτά</strong> &mdash; κάθε αίτημα που δεν έχει κλείσει ακόμη, ανεξάρτητα από το ποιος το έχει. Χρήσιμο για προϊσταμένους και υπεύθυνους ομάδων που παρακολουθούν τον συνολικό όγκο.',
            'field_closed' => '<strong>Κλειστά</strong> &mdash; επιλυμένα αιτήματα. Κάντε αναζήτηση εδώ όταν χρειάζεστε μια παλιά λύση ή θέλετε να ανοίξετε ξανά ένα ζήτημα.',
            'field_dept' => '<strong>Φάκελοι τμημάτων</strong> &mdash; αιτήματα ομαδοποιημένα ανά τμήμα (π.χ. IT, HR, Οικονομικά). Τα τμήματα ορίζονται στις Ρυθμίσεις και εμφανίζονται αυτόματα ως υποφάκελοι.',
            'switch_heading' => '<strong>Εναλλαγή μεταξύ ομαδοποίησης ανά Τμήμα και ανά Τεχνικό</strong>',
            'switch_body' => 'Ένας μικρός διακόπτης δύο κουμπιών στο πάνω μέρος του πίνακα φακέλων εναλλάσσει δύο προβολές των ίδιων δεδομένων. Η ομαδοποίηση ανά <strong>Τμήμα</strong> (προεπιλογή) απαριθμεί τα αιτήματα κάτω από κάθε τμήμα με υποφακέλους καταστάσεων· η ομαδοποίηση ανά <strong>Τεχνικό</strong> την αναστρέφει, ώστε κάθε φάκελος ανώτερου επιπέδου να αντιπροσωπεύει την προσωπική ουρά ενός τεχνικού με υποφακέλους καταστάσεων. Ο φάκελος <strong>Χωρίς ανάθεση</strong> προσαρμόζεται σε κάθε προβολή &mdash; στην προβολή Τμήματος δείχνει αιτήματα χωρίς τμήμα· στην προβολή Τεχνικού δείχνει αιτήματα χωρίς υπεύθυνο &mdash; ώστε να βλέπετε πάντα τι περιμένει να αναληφθεί. Όταν η εγκατάστασή σας έχει ομάδες, μια τρίτη επιλογή, η <strong>Ομάδα</strong>, απαριθμεί την ουρά στην οποία έχει περάσει κάθε αίτημα. Η επιλογή σας αποθηκεύεται ανά τεχνικό, ώστε κάθε μέλος της ομάδας να διατηρεί την προβολή που προτιμά από συνεδρία σε συνεδρία. Σε εγκατάσταση με πολλές εταιρείες, οι φάκελοι Τεχνικών απαριθμούν μόνο άτομα που μπορούν να εργαστούν στην εταιρεία που βλέπετε, και οι λίστες <strong>Ανάθεση</strong> προσφέρουν μόνο άτομα που μπορούν να εργαστούν στην εταιρεία του συγκεκριμένου αιτήματος. Το <strong>Αιτήματα &rarr; Ρυθμίσεις &rarr; Γενικά &rarr; Φάκελοι ομάδων</strong> μπορεί να περιορίσει τους φακέλους Ομάδων στις ομάδες στις οποίες ανήκει κάθε τεχνικός· αλλάζει μόνο τη λίστα φακέλων, ποτέ το ποια αιτήματα μπορεί να ανοίξει κάποιος.',
            'p_actions' => 'Πάνω από τη λίστα αιτημάτων έχετε τέσσερα κουμπιά ενεργειών: <strong>Νέο</strong> για δημιουργία αιτήματος, <strong>Αναζήτηση</strong> για εύρεση αιτημάτων με λέξη-κλειδί, αναφορά ή αιτούντα, <strong>Φίλτρο</strong> για να περιορίσετε ό,τι βλέπετε, και <strong>Ανανέωση</strong> για επαναφόρτωση του τρέχοντος φακέλου.',
            'filter_body' => 'Το κουμπί <strong>Φίλτρο</strong> (το χωνί) περιορίζει μαζί τους φακέλους και τη λίστα, όπως κι αν είναι ομαδοποιημένα. Το <strong>Δικά μου</strong> δείχνει μόνο αιτήματα που σας έχουν ανατεθεί, και το <strong>Απόκρυψη κλειστών</strong> παραλείπει κάθε αίτημα με κατάσταση που έχει σημανθεί ως κλειστή. Όσο ένα φίλτρο είναι ενεργό, το χωνί φέρει μια τελεία και δίπλα στον τίτλο της λίστας εμφανίζεται μια ετικέτα, ώστε να ξέρετε πάντα ότι δεν βλέπετε τα πάντα. Όταν οι φάκελοι είναι ομαδοποιημένοι ανά <strong>Τεχνικό</strong>, ο δικός σας φάκελος βρίσκεται στην κορυφή ως <strong>Τα αιτήματά μου</strong>. Η αναζήτηση έχει τον δικό της διακόπτη <strong>Συμπερίληψη κλειστών αιτημάτων</strong>, ενεργό από προεπιλογή, επειδή η αναζήτηση είναι συνήθως ψάξιμο για ένα παλιό αίτημα. Και οι δύο επιλογές αποθηκεύονται μόνο για εσάς.',
            'row_name' => 'Κάθε γραμμή δείχνει την αναφορά του αιτήματος και μετά ένα όνομα. Από προεπιλογή είναι <strong>το άτομο που υπέβαλε το αίτημα</strong>, και παραμένει το ίδιο σε όλη τη ζωή του αιτήματος. Αν προτιμάτε να βλέπετε όποιον έστειλε το πιο πρόσφατο μήνυμα &mdash; που γίνεται το δικό σας γραμματοκιβώτιο μόλις απαντήσετε &mdash; αλλάξτε το <strong>Όνομα δίπλα στον αριθμό αιτήματος</strong> στο <strong>Ρυθμίσεις &rarr; Εμφάνιση γραμμών</strong>, όπου μπορείτε επίσης να κρύψετε το όνομα και να αφήσετε μόνο την αναφορά. Αυτή η καρτέλα είναι δική σας ρύθμιση: δεν αλλάζει τίποτα για κανέναν άλλον.',
            'tip' => 'Κάντε κλικ σε οποιοδήποτε αίτημα της λίστας για να φορτωθεί στο παράθυρο ανάγνωσης. Από εκεί μπορείτε να ενημερώσετε πεδία, να προσθέσετε σχόλια, να απαντήσετε με email ή να επισυνάψετε αρχεία &mdash; όλα χωρίς να φύγετε από τα εισερχόμενα.',
        ],
        'live' => [
            'heading' => 'Ζωντανές ενημερώσεις',
            'body' => 'Το FreeITSM κρατά την οθόνη σας σε συγχρονισμό με όλους τους άλλους. Όταν ένας συνάδελφος αλλάζει ένα αίτημα - την κατάστασή του, την προτεραιότητα, τον υπεύθυνο ή την ομάδα, μια απάντηση, μια σημείωση - η λίστα αιτημάτων σας και το αίτημα που έχετε ανοιχτό ενημερώνονται μέσα σε περίπου 15 δευτερόλεπτα, χωρίς να πατήσετε ανανέωση. Ο πίνακας εργασιών, μια ανοιχτή εργασία και το κουδούνι λειτουργούν με τον ίδιο τρόπο.',
            'what' => 'Ελέγχει μόνο όσο η καρτέλα είναι μπροστά σας, και ενημερώνεται τη στιγμή που επιστρέφετε σε αυτήν. Μια αλλαγή που κάνετε σε μια καρτέλα εμφανίζεται αμέσως στις άλλες σας καρτέλες.',
            'safe' => 'Δεν πετά ποτέ ό,τι κάνετε εκείνη τη στιγμή. Όσο γράφετε μια απάντηση ή μια σημείωση, πληκτρολογείτε σε ένα πεδίο ή έχετε ανοιχτό ένα μενού, τα νέα μηνύματα εμφανίζονται κανονικά στη συνομιλία, και τα υπόλοιπα περιμένουν πίσω από ένα μικρό μήνυμα <strong>Μόλις ενημερώθηκε από κάποιον άλλο &middot; Ανανέωση</strong>.',
            'setting' => 'Το <strong>Προτιμήσεις &rarr; Ζωντανές ενημερώσεις</strong> επιλέγει κάθε 15 δευτερόλεπτα (η προεπιλογή), 30 δευτερόλεπτα, κάθε λεπτό ή απενεργοποίηση.',
        ],
        'watch' => [
            'heading' => 'Παρακολούθηση ενός αιτήματος',
            'body' => 'Ακολουθήστε ένα αίτημα χωρίς να το έχετε - ένας υπεύθυνος ομάδας που παρακολουθεί ένα μείζον συμβάν, ή ο τεχνικός που το παρέδωσε σε άλλον. Όσοι παρακολουθούν ενημερώνονται για το αίτημα σαν να ήταν δικό τους, μέσω των δικών τους ρυθμίσεων ειδοποιήσεων.',
            'how' => '<strong>Παρακολούθηση</strong> στη γραμμή εργαλείων του αιτήματος, ή δεξί κλικ πάνω του στη λίστα και επιλογή <strong>Παρακολούθηση</strong>. Κάντε δεξί κλικ σε μια επιλογή για να τα παρακολουθήσετε όλα. Τα ίδια σημεία δείχνουν <strong>Διακοπή παρακολούθησης</strong>.',
            'others' => 'Το κουμπί <strong>Παρακολούθηση</strong> δείχνει ποιος παρακολουθεί. Με δικαίωμα εγγραφής στα Αιτήματα μπορείτε να <strong>προσθέσετε έναν συνάδελφο</strong> ή να αφαιρέσετε κάποιον· ο καθένας μπορεί να αφαιρέσει τον εαυτό του.',
            'what' => 'Το <strong>Αιτήματα &rarr; Ρυθμίσεις &rarr; Γενικά &rarr; Παρακολούθηση αιτημάτων</strong> επιλέγει για τι ενημερώνονται όσοι παρακολουθούν - απαντήσεις, σημειώσεις, κατάσταση, προτεραιότητα, εκ νέου ανάθεση, προειδοποιήσεις και παραβιάσεις SLA - όλα, εκτός αν ένας διαχειριστής αποεπιλέξει κάποια. Μια εκ νέου ανάθεση φτάνει σε όποιον παρακολουθεί ως «εκ νέου ανάθεση», ποτέ ως «ανατέθηκε σε εσάς», και έχει δικό της διακόπτη στις προτιμήσεις κάθε ατόμου.',
            'leaver' => 'Ένας απενεργοποιημένος τεχνικός δεν ενημερώνεται ποτέ για αίτημα που παρακολουθεί. Το <strong>Αιτήματα &rarr; Ρυθμίσεις &rarr; Γενικά &rarr; Όταν απενεργοποιείται κάποιος που παρακολουθεί</strong> ορίζει τι γίνεται με τις παρακολουθήσεις του: η <strong>Διακοπή ειδοποιήσεων</strong> (η προεπιλογή) τις κρύβει και τις επαναφέρει αν ο τεχνικός ενεργοποιηθεί ξανά· η <strong>Αφαίρεση</strong> αφαιρεί τον τεχνικό από κάθε αίτημα που παρακολουθεί τη στιγμή που απενεργοποιείται.',
            'note' => 'Μόνο όσοι μπορούν να δουν ένα αίτημα μπορούν να το παρακολουθήσουν, και αν πάψουν να μπορούν να το δουν, παύουν να ενημερώνονται γι\' αυτό. Κανείς δεν ειδοποιείται για τη δική του αλλαγή. Η συγχώνευση μεταφέρει όσους παρακολουθούν στο αίτημα που απομένει.',
        ],
        'forms_on_ticket' => [
            'heading' => 'Φόρμες σε ένα αίτημα',
            'body' => 'Επισυνάψτε μια φόρμα από την ενότητα Φόρμες σε ένα αίτημα και συμπληρώστε την εκεί - ένα αίτημα για νέο υπάλληλο που χρειάζεται τη φόρμα εξοπλισμού του, ή ένα συμβάν ασφαλείας που χρειάζεται την αναφορά του. Οι απαντήσεις φυλάσσονται μαζί με το αίτημα.',
            'switch' => 'Το <strong>Αιτήματα &rarr; Ρυθμίσεις &rarr; Λίστες ελέγχου &rarr; Φόρμες σε αιτήματα</strong> το ενεργοποιεί (είναι ανενεργό μέχρι να το κάνετε, και πρέπει να είναι ενεργή και η ενότητα Φόρμες). Ένα κουμπί <strong>Φόρμες</strong> εμφανίζεται τότε στη γραμμή εργαλείων κάθε αιτήματος, με τον αριθμό όσων έχουν υποβληθεί. Σε έναν χώρο εργασίας οι φόρμες εμφανίζονται επίσης στην καρτέλα <strong>Εργασία</strong>. Κάντε δεξί κλικ σε ένα αίτημα, ή σε μια επιλογή, και επιλέξτε <strong>Προσθήκη φόρμας</strong> για να προσθέσετε μία χωρίς να το ανοίξετε.',
            'how' => 'Το <strong>Φόρμες</strong> ανοίγει τη λίστα: η <strong>Προσθήκη</strong> επιλέγει μια φόρμα (πάντα την πιο πρόσφατη έκδοσή της), η <strong>Συμπλήρωση</strong> την ανοίγει σε παράθυρο, η <strong>Αποθήκευση πρόχειρου</strong> κρατά ημιτελείς απαντήσεις που οι συνάδελφοι μπορούν να συνεχίσουν, και η <strong>Διόρθωση</strong> αντικαθιστά μια υποβολή κρατώντας την παλιά στις Φόρμες.',
            'required' => 'Κάθε φόρμα είναι <strong>Υποχρεωτική - εμποδίζει το κλείσιμο</strong>, <strong>Υποχρεωτική - προειδοποιεί στο κλείσιμο</strong> ή <strong>Προαιρετική</strong>. Μια φόρμα που εμποδίζει πρέπει να υποβληθεί πριν το αίτημα φτάσει σε κατάσταση κλειστού· μια φόρμα που προειδοποιεί ρωτά και καταγράφει ποιος το έκλεισε παρ\' όλα αυτά.',
            'note' => 'Η συμπλήρωση μιας φόρμας απαιτεί δικαίωμα εγγραφής στις Φόρμες. Η ανάγνωση των απαντήσεων απαιτεί πρόσβαση στις Φόρμες ή το δικαίωμα <strong>Ανάγνωση των απαντήσεων φορμών σε αιτήματα που μπορείτε να δείτε</strong> (ρύθμιση ρόλου)· οι υπόλοιποι βλέπουν ποιος την υπέβαλε και πότε, αλλά όχι τι είπε. Μια υποβολή στην οποία βασίζεται ένα αίτημα δεν μπορεί να διαγραφεί από τις Φόρμες. Οι απαντήσεις εμφανίζονται στην αναφορά υπόθεσης του αιτήματος και στο REST API.',
        ],
        'faster' => [
            'heading' => 'Ταχύτερη εργασία',
            'intro' => 'Τέσσερα πράγματα που κάνουν ένα φορτωμένο πρωινό διαχειρίσιμο: αποθηκευμένες απαντήσεις, ενέργειες σε πολλά αιτήματα ταυτόχρονα, και τοποθέτηση των συνομιλιών εκεί που ανήκουν.',
            'templates_heading' => 'Έτοιμες απαντήσεις',
            'templates_body' => 'Στέλνετε διαρκώς τις ίδιες λίγες απαντήσεις. Γράψτε μία φορά, και μετά κάντε κλικ στα <strong>Πρότυπα</strong> κάτω αριστερά στο παράθυρο απάντησης για να την εισαγάγετε στον δρομέα σας &mdash; προστίθεται σε όσα έχετε ήδη πληκτρολογήσει αντί να τα αντικαθιστά. Τα πρότυπα είναι εμπλουτισμένο κείμενο και υποστηρίζουν τα ίδια placeholders <code>[merge_code]</code> με τα αυτοματοποιημένα email, ώστε το <code>[requester_first_name]</code> να γίνεται το πραγματικό όνομα καθώς το εισάγετε.',
            'templates_team' => '<strong>Πρότυπα ομάδας</strong> &mdash; κοινά για όλους, ορίζονται στο Ρυθμίσεις &rarr; Πρότυπα απαντήσεων.',
            'templates_mine' => '<strong>Δικά σας</strong> &mdash; αποθηκεύστε ένα πρόχειρο με την επιλογή <em>Αποθήκευση πρόχειρου ως προτύπου</em>. Ιδιωτικό για εσάς, και δεν χρειάζεται δικαίωμα.',
            'templates_tip' => 'Ονομάστε ένα πρότυπο με βάση την περίσταση («Εκτυπωτής εκτός σύνδεσης &mdash; πρώτα βήματα»), όχι με βάση τη διατύπωσή του. Είναι αυτό που θα ψάχνετε στις 9 το πρωί.',
            'select_heading' => 'Επιλογή πολλών αιτημάτων',
            'select_body' => 'Η λίστα αιτημάτων λειτουργεί όπως το Outlook ή η Εξερεύνηση αρχείων. Χωρίς πλαίσια ελέγχου.',
            'key_click' => 'Κλικ',
            'key_click_d' => 'επιλέγει ένα και το ανοίγει',
            'key_ctrl' => 'Ctrl+κλικ',
            'key_ctrl_d' => 'προσθέτει ή αφαιρεί ένα, αφήνοντας τα υπόλοιπα ως έχουν',
            'key_shift' => 'Shift+κλικ',
            'key_shift_d' => 'επιλέγει ένα ολόκληρο μπλοκ από το σημείο του τελευταίου κλικ',
            'key_kb' => 'Πληκτρολόγιο',
            'key_kb_d' => 'βέλη για μετακίνηση, Shift+βέλη για επέκταση, Ctrl+βέλη και Space για επιλογή διάσπαρτων αιτημάτων, Ctrl+A για όλα, Escape για καθαρισμό',
            'select_actions' => 'Με πολλά επιλεγμένα, <strong>κάντε δεξί κλικ σε οποιοδήποτε από αυτά</strong> για να ορίσετε κατάσταση, προτεραιότητα, τμήμα, τύπο ή τεχνικό για όλα μαζί &mdash; ή σύρετε ολόκληρο το σύνολο σε έναν φάκελο. Το τι δείχνει η οθόνη όσο είναι επιλεγμένα πολλά είναι δική σας επιλογή, στο μενού λογαριασμού στις Προτιμήσεις.',
            'select_tip' => 'Το δεξί κλικ σε ένα αίτημα που <em>δεν</em> ανήκει στην επιλογή σας καθαρίζει την επιλογή και στοχεύει μόνο αυτό. Αυτό είναι σκόπιμο &mdash; δεν μπορείτε ποτέ να ενεργήσετε σε ένα σύνολο που νομίζατε ότι είχατε αφήσει πίσω.',
            'merge_heading' => 'Συγχώνευση διπλότυπων',
            'merge_body' => 'Δύο άτομα ανέφεραν την ίδια διακοπή; Επιλέξτε τα αιτήματα, δεξί κλικ, <strong>Συγχώνευση</strong>. Οι συνομιλίες ενώνονται, και αν έχετε ρυθμίσει πάροχο AI το FreeITSM γράφει μια σύντομη ενημέρωση για το τι ζήτησε ο καθένας και τι έχει ήδη γίνει, ώστε όποιος το αναλάβει να μη χρειάζεται να διαβάσει τέσσερις συζητήσεις.',
            'merge_tip' => 'Τίποτα δεν διαγράφεται ποτέ. Το αίτημα που συγχωνεύθηκε κρατά την αναφορά του, παραμένει διαθέσιμο στην αναζήτηση, δείχνει πού πήγε &mdash; και ένας πελάτης που απαντά σε παλιό email γι\' αυτό φτάνει και πάλι σε εσάς.',
            'split_heading' => 'Διαχωρισμός ενός αιτήματος',
            'split_body' => 'Η αντίστροφη δουλειά. Όταν κάποιος θέτει ένα δεύτερο, άσχετο θέμα στη μέση μιας συνομιλίας, κάντε κλικ στο <strong>Διαχωρισμός</strong> σε εκείνο το μήνυμα (ή δεξί κλικ στην κεφαλίδα του μηνύματος). Μεταφέρεται σε νέο αίτημα, παίρνοντας προαιρετικά μαζί του κάθε νεότερο μήνυμα, και το αρχικό κρατά έναν δείκτη που δείχνει πού πήγαν.',
            'split_tip' => 'Δώστε στο νέο αίτημα κανονικό θέμα. Από προεπιλογή παίρνει το θέμα του μηνύματος που μεταφέρθηκε, το οποίο συνήθως είναι ένα «RE:» για το <em>παλιό</em> πρόβλημα.',
            'undo_heading' => 'Αλλάξατε γνώμη',
            'undo_body' => 'Και τα δύο μπορούν να αναιρεθούν από το πλαίσιο ειδοποίησης στο αίτημα. Η αναίρεση ενός <strong>διαχωρισμού</strong> απορρίπτεται όταν κάποιος έχει απαντήσει στο νέο αίτημα, έχει προσθέσει σημείωση ή έχει καταγράψει χρόνο &mdash; σας λένε ακριβώς τι εμποδίζει. Η αναίρεση μιας <strong>συγχώνευσης</strong> επιστρέφει στο αίτημα τα μηνύματα, τις σημειώσεις και τον χρόνο που είχε καταγραφεί και το ανοίγει ξανά ακριβώς όπως ήταν, αλλά οι απαντήσεις που γράφτηκαν στο άλλο αίτημα μετά τη συγχώνευση μένουν εκεί.',
        ],
        'working' => [
            'heading' => 'Εργασία με αιτήματα',
            'intro' => 'Κάθε αίτημα υποστήριξης ακολουθεί έναν κύκλο ζωής: δημιουργείται, διαλογίζεται, επεξεργάζεται και τελικά επιλύεται. Η ενότητα Αιτήματα σας δίνει τα εργαλεία για να διαχειρίζεστε κάθε στάδιο αποτελεσματικά, από την αρχική καταχώριση μέχρι το κλείσιμο.',
            'creating_heading' => '<strong>Δημιουργία νέου αιτήματος</strong>',
            'step1' => '<strong>Πατήστε Νέο</strong> &mdash; ανοίξτε το παράθυρο νέου αιτήματος από τη γραμμή εργαλείων των εισερχομένων. Εισαγάγετε το όνομα και τη διεύθυνση email του αιτούντος, ώστε να λαμβάνει ενημερώσεις.',
            'step2' => '<strong>Ορίστε το θέμα</strong> &mdash; γράψτε μια σαφή, σύντομη περίληψη του προβλήματος. Εμφανίζεται στη λίστα αιτημάτων και σε όποια ειδοποίηση email σταλεί στον τελικό χρήστη.',
            'step3' => '<strong>Επιλέξτε τμήμα, τύπο και προτεραιότητα</strong> &mdash; επιλέξτε το κατάλληλο τμήμα, τον τύπο αιτήματος (π.χ. Συμβάν, Αίτημα εξυπηρέτησης) και το επίπεδο προτεραιότητας. Αυτά τα πεδία καθορίζουν τους χρονομετρητές SLA και τους κανόνες δρομολόγησης.',
            'step4' => '<strong>Προσθέστε την περιγραφή</strong> &mdash; δώστε όλες τις λεπτομέρειες του προβλήματος με τον επεξεργαστή εμπλουτισμένου κειμένου. Συμπεριλάβετε τα βήματα αναπαραγωγής, τα μηνύματα σφάλματος και κάθε σχετικό στοιχείο που θα χρειαστεί ο τεχνικός που θα το επιλύσει.',
            'step5' => '<strong>Αποθήκευση</strong> &mdash; το αίτημα δημιουργείται με μοναδικό αριθμό αναφοράς και εμφανίζεται στον κατάλληλο φάκελο. Το ρολόι SLA ξεκινά αμέσως, με βάση την προτεραιότητα.',
            'editing_heading' => '<strong>Επεξεργασία και διαχείριση αιτημάτων</strong>',
            'editing_body' => 'Μόλις υπάρξει ένα αίτημα, μπορείτε να ενημερώσετε οποιοδήποτε πεδίο από το παράθυρο ανάγνωσης. Βασικά πεδία είναι τα εξής:',
            'card_status_title' => 'Κατάσταση',
            'card_status_body' => 'Παρακολουθήστε τον κύκλο ζωής του αιτήματος: Νέο, Ανοιχτό, Σε εξέλιξη, Σε αναμονή, Επιλύθηκε, Έκλεισε',
            'card_priority_title' => 'Προτεραιότητα',
            'card_priority_body' => 'Ορίστε το επείγον και την επίπτωση: Κρίσιμη, Υψηλή, Μεσαία, Χαμηλή. Κάθε επίπεδο έχει τον δικό του στόχο SLA',
            'card_category_title' => 'Κατηγορία',
            'card_category_body' => 'Ταξινομήστε τον τύπο του προβλήματος: Υλικό, Λογισμικό, Δίκτυο, Πρόσβαση, Γενικά. Χρήσιμο για τις αναφορές',
            'card_analyst_title' => 'Τεχνικός που έχει αναλάβει',
            'card_analyst_body' => 'Το άτομο που είναι υπεύθυνο για την επίλυση του αιτήματος. Οι αναθέσεις καταγράφονται στο ιστορικό δραστηριότητας',
            'card_enduser_title' => 'Τελικός χρήστης',
            'card_enduser_body' => 'Το άτομο που υπέβαλε το αίτημα. Αναζητήστε με όνομα ή email για να συσχετίσετε μια υπάρχουσα εγγραφή χρήστη',
            'card_dept_title' => 'Τμήμα',
            'card_dept_body' => 'Δρομολογήστε τα αιτήματα στη σωστή ομάδα. Τα τμήματα καθορίζουν την ομαδοποίηση φακέλων και τα φίλτρα του πίνακα ελέγχου',
            'flow_new' => 'Νέο',
            'flow_in_progress' => 'Σε εξέλιξη',
            'flow_resolved' => 'Επιλύθηκε',
            'flow_closed' => 'Έκλεισε',
            'triage_heading' => '<strong>Διαλογή με μεταφορά και απόθεση</strong>',
            'triage_body' => 'Δεν χρειάζεται να ανοίξετε ένα αίτημα για να το διαλογίσετε. Σύρετε οποιαδήποτε γραμμή της λίστας αιτημάτων πάνω σε έναν φάκελο για να ενημερώσετε πεδία με μία κίνηση:',
            'triage_dept' => '<strong>Προβολή τμημάτων</strong> &mdash; αποθέστε σε φάκελο τμήματος για να το αναθέσετε εκ νέου, αποθέστε σε υποφάκελο κατάστασης κάτω από ένα τμήμα για να ενημερωθούν και τα δύο μαζί, αποθέστε στο <strong>Χωρίς ανάθεση</strong> για να καθαριστεί το τμήμα.',
            'triage_analyst' => '<strong>Προβολή τεχνικών</strong> &mdash; αποθέστε στον φάκελο ενός τεχνικού για να τον ορίσετε υπεύθυνο (ορίζονται και τα δύο, <code>assigned_analyst_id</code> και <code>owner_id</code>, ώστε το πεδίο Υπεύθυνος στο παράθυρο ανάγνωσης να παραμένει συγχρονισμένο), αποθέστε σε υποφάκελο κατάστασης για να ενημερωθούν και τα δύο, αποθέστε στο <strong>Χωρίς ανάθεση</strong> για να καθαριστεί ο ανατεθειμένος.',
            'triage_spring' => '<strong>Φάκελοι που ανοίγουν μόνοι τους</strong> &mdash; κρατήστε τον δείκτη πάνω από έναν συμπτυγμένο φάκελο κατά τη μεταφορά και αναπτύσσεται αυτόματα (όπως στο Outlook), ώστε να φτάνετε σε οποιαδήποτε εμφωλευμένη κατάσταση χωρίς να αποθέσετε πρώτα.',
            'fullscreen_heading' => '<strong>Προβολή πλήρους οθόνης</strong>',
            'fullscreen_body' => 'Όταν χρειάζεστε συγκέντρωση σε ένα μόνο αίτημα &mdash; μια μεγάλη συζήτηση, μια σύνθετη αλλαγή, τη σύνταξη μιας λεπτομερούς απάντησης &mdash; περάστε σε προβολή πλήρους οθόνης. Η λίστα φακέλων και η λίστα αιτημάτων εξαφανίζονται, η συζήτηση καταλαμβάνει όλο το διαθέσιμο πλάτος και οι ιδιότητες (Τμήμα, Τύπος, Κατάσταση, Προέλευση, First Time Fix, IT Training, Υπεύθυνος) μετακινούνται σε κατακόρυφη πλευρική στήλη στα δεξιά.',
            'fullscreen_max' => '<strong>Εικονίδιο μεγιστοποίησης</strong> &mdash; μικρό εικονίδιο στο δεξί άκρο της γραμμής θέματος του αιτήματος. Πατήστε το για πλήρη οθόνη, και πατήστε το ξανά για να επιστρέψετε στη διάταξη τριών παραθύρων.',
            'fullscreen_dbl' => '<strong>Διπλό κλικ σε γραμμή ή πάτημα Enter</strong> &mdash; κάντε διπλό κλικ σε οποιοδήποτε αίτημα της λίστας για να το ανοίξετε κατευθείαν σε πλήρη οθόνη, με τη χειρονομία «άνοιξε αυτό πραγματικά» που ξέρετε από το Outlook. Το <strong>Enter</strong> ανοίγει το αίτημα στη διάταξη που επιλέξατε τελευταία - σε πλήρη οθόνη, αν έτσι δουλεύετε - και το Enter σε αίτημα που φαίνεται ήδη το κάνει πλήρη οθόνη. Όσο ο πίνακας εμφανίζεται μόνος του, τα βέλη μετακινούν μόνο την επισήμανση - ένα κλικ ή το Enter ανοίγει το αίτημα, και μόλις ανοίξει ένα, τα βέλη δείχνουν κάθε αίτημα καθώς μετακινείστε.',
            'fullscreen_sticks' => '<strong>Παραμένει ενεργή μεταξύ επιλογών</strong> &mdash; μόλις μπείτε σε πλήρη οθόνη, η μετάβαση στο επόμενο αίτημα σας κρατά εκεί. Μια νέα φόρτωση της σελίδας (F5) χωρίς επιλεγμένο αίτημα επιστρέφει στην προεπιλεγμένη διάταξη τριών στηλών, ώστε να μη βρεθείτε παγιδευμένοι με κρυμμένη τη λίστα φακέλων.',
            'fullscreen_back' => '<strong>Πίσω</strong> &mdash; η γραμμή πάνω από το αίτημα δείχνει την αναφορά του και ένα κουμπί <strong>Πίσω</strong>, που σας επιστρέφει κατευθείαν στη λίστα ακριβώς όπως την αφήσατε, με το πληκτρολόγιο ξανά στη λίστα - έτσι τα βέλη μετακινούν ανάμεσα στα αιτήματα και το Enter ανοίγει αμέσως το επόμενο. Το <strong>Escape</strong> κάνει το ίδιο, αφού κλείσει κάθε παράθυρο ή μενού που είναι ανοιχτό πάνω από το αίτημα. Κανένα από τα δύο δεν απενεργοποιεί την πλήρη οθόνη: το επόμενο αίτημα ανοίγει πάλι σε πλήρη οθόνη (το εικονίδιο σμίκρυνσης είναι ο διακόπτης), και αν επιστρέψετε στο αίτημα που αφήσατε, μια απάντηση που είχατε αρχίσει είναι ακόμη εκεί.',
            'fullscreen_keys' => '<strong>Τα πλήκτρα κυλίουν το αίτημα</strong> &mdash; σε πλήρη οθόνη τα πλήκτρα βέλους, τα Page Up / Page Down και το Space κυλίουν τη συζήτηση, όχι την κρυμμένη λίστα αιτημάτων. Σε παράθυρο εικόνας ή PDF κυλίουν αυτό το παράθυρο. Στην κανονική προβολή τριών παραθύρων, κάντε κλικ μέσα στο αίτημα και τα πλήκτρα το κυλίουν κι εκεί· κάντε κλικ στη λίστα για να επιστρέψετε στη μετακίνηση ανάμεσα στα αιτήματα.',
            'viewer_heading' => '<strong>Οι εικόνες και τα PDF ανοίγουν πάνω από το αίτημα</strong>',
            'viewer_body' => 'Κάντε κλικ σε μια εικόνα ή ένα PDF που είναι συνημμένο σε σημείωση, ή σε ένα από τη λίστα <strong>Συνημμένα</strong> του αιτήματος (στη μικρογραφία ή στη γραμμή του), και ανοίγει σε παράθυρο πάνω από το αίτημα &mdash; με την ίδια προβολή που έχει η ενότητα Αρχεία. Το αίτημα μένει ακριβώς εκεί που ήταν από κάτω.',
            'viewer_window' => '<strong>Μετακίνηση και αλλαγή μεγέθους</strong> &mdash; σύρετε τη γραμμή τίτλου για να μετακινήσετε το παράθυρο και οποιαδήποτε άκρη ή γωνία για να αλλάξετε το μέγεθος· κάντε διπλό κλικ στη γραμμή τίτλου, ή σύρετέ την στο πάνω μέρος της οθόνης, για να γεμίσει την οθόνη. Η εικόνα ή το PDF προσαρμόζεται καθώς αλλάζει το μέγεθος του παραθύρου, μέχρι να κάνετε εσείς μεγέθυνση ή σμίκρυνση &mdash; το <strong>Προσαρμογή</strong> το επαναφέρει. Μπορείτε να ανοίξετε πολλά και στέκονται δίπλα-δίπλα.',
            'viewer_close' => '<strong>Κλείσιμο</strong> &mdash; το &times; στη γραμμή τίτλου, ή το <strong>Escape</strong> (που κλείνει το παράθυρο μπροστά). Το <strong>Λήψη</strong> αποθηκεύει το αρχείο. Στο κινητό το αρχείο ανοίγει σε πλήρη οθόνη με κουμπί Πίσω.',
            'viewer_other' => '<strong>Άλλα αρχεία</strong> &mdash; τα έγγραφα Word, τα υπολογιστικά φύλλα και όλα τα υπόλοιπα συνεχίζουν να γίνονται λήψη ή να ανοίγουν σε νέα καρτέλα, όπως πριν. Για να ανοίξετε την εικόνα ή το PDF μιας σημείωσης σε νέα καρτέλα, κάντε Ctrl-κλικ πάνω της.',
            'paste_heading' => '<strong>Επικόλληση στιγμιότυπου οθόνης σε σημείωση</strong>',
            'paste_body' => 'Αντιγράψτε ένα στιγμιότυπο οθόνης, κάντε κλικ στο πλαίσιο <strong>Προσθήκη σημείωσης</strong> και πατήστε <strong>Ctrl+V</strong>. Η εικόνα μπαίνει εκεί που βρίσκεται ο δρομέας, με το κείμενό σας πριν και μετά από αυτήν, και μένει στη θέση της αφού αποθηκευτεί η σημείωση. Κάντε κλικ πάνω της για να την ανοίξετε στην προβολή. Το <strong>Backspace</strong> την αφαιρεί πριν αποθηκεύσετε.',
            'paste_shared' => '<strong>Οι κοινόχρηστες σημειώσεις μοιράζονται και τις εικόνες τους</strong> &mdash; ο αιτών τις βλέπει στην πύλη, στη θέση τους. Σε εσωτερική σημείωση είναι εξίσου ιδιωτικές με τη σημείωση.',
            'paste_save' => '<strong>Τίποτα δεν διατηρείται μέχρι να πατήσετε Αποθήκευση</strong> &mdash; κλείστε το πλαίσιο και οι εικόνες φεύγουν μαζί του. Αν μια εικόνα απορριφθεί, δεν αποθηκεύεται ούτε η σημείωση, εμφανίζεται ο λόγος και το κείμενό σας παραμένει στο πλαίσιο.',
            'paste_text' => '<strong>Το κείμενο μένει κείμενο</strong> &mdash; η επικόλληση από Word, ιστοσελίδα ή Excel βάζει τις λέξεις χωρίς τη μορφοποίησή τους. Το κουμπί <strong>Επισύναψη</strong> συνεχίζει να λειτουργεί για κάθε άλλο αρχείο.',
            'rightclick_heading' => '<strong>Δεξί κλικ για γρήγορες ενέργειες</strong>',
            'rightclick_body' => 'Κάντε δεξί κλικ σε οποιοδήποτε αίτημα της λίστας για να ανοίξει ένα μενού περιβάλλοντος. Το μενού δείχνει στην κορυφή την αναφορά του αιτήματος, ώστε να ξέρετε σε τι ενεργείτε, και κάθε ενέργεια αφορά το αίτημα στο οποίο κάνατε δεξί κλικ <em>χωρίς</em> να αλλάζει αυτό που είναι ανοιχτό στο παράθυρο ανάγνωσης &mdash; χρήσιμο όταν διαβάζετε το αίτημα Α και πρέπει να διαλογίσετε το αίτημα Β χωρίς να χάσετε τη θέση σας.',
            'rightclick_status' => '<strong>Ορισμός κατάστασης &rarr;</strong> &mdash; αναδυόμενο υπομενού που εμφανίζει κάθε ενεργή κατάσταση με το χρωματικό της δείγμα. Εμφανίζεται ένα τσεκ δίπλα στην τρέχουσα τιμή αν κάνετε δεξί κλικ στο αίτημα που έχετε ανοιχτό. Οι επιλογές ενημερώνουν αμέσως το αίτημα, γράφουν εγγραφή στο ιστορικό ελέγχου, ανανεώνουν τους μετρητές των φακέλων και συγχρονίζουν την αναπτυσσόμενη λίστα Κατάστασης του παραθύρου ανάγνωσης, αν ισχύει.',
            'rightclick_priority' => '<strong>Ορισμός προτεραιότητας &rarr;</strong> &mdash; το ίδιο αναδυόμενο μοτίβο, με πηγή τις ενεργές προτεραιότητες και το χρώμα της καθεμιάς ως δείγμα. Η πρώτη γραμμή είναι η επιλογή <em>(χωρίς προτεραιότητα)</em> για να καθαρίσετε την τιμή (η προτεραιότητα μπορεί να είναι κενή).',
            'rightclick_assign' => '<strong>Ανάθεση σε &rarr;</strong> &mdash; υπομενού που εμφανίζει κάθε φορτωμένο τεχνικό με ένα γκρι αρχικό, και μια γραμμή <em>(χωρίς ανάθεση)</em> στην κορυφή για καθαρισμό. Οι επιλογές ορίζουν και τα δύο, <code>assigned_analyst_id</code> ΚΑΙ <code>owner_id</code>, ώστε το πεδίο Υπεύθυνος στο παράθυρο ανάγνωσης να παραμένει συγχρονισμένο.',
            'rightclick_cmdb' => '<strong>Συσχέτιση αντικειμένου CMDB&hellip;</strong> &mdash; ανοίγει επιλογέα με αναζήτηση καθώς πληκτρολογείτε. Κάντε κλικ σε ένα αποτέλεσμα για να το συσχετίσετε και συνεχίστε να επιλέγετε &mdash; το πεδίο καθαρίζει και ξαναπαίρνει την εστίαση για το επόμενο, και ένα αρχείο «Πρόσφατες συσχετίσεις» μέσα στο παράθυρο δείχνει τη λίστα σας με πράσινα τσεκ επιβεβαίωσης.',
            'rightclick_time' => '<strong>Καταγραφή χρόνου&hellip;</strong> &mdash; ανοίγει παράθυρο με λεπτά + επιλογέα ημερομηνίας και ώρας (προεπιλογή το «τώρα», ώστε να μπορείτε και να καταχωρίσετε αναδρομικά) + προαιρετικό πλαίσιο σημειώσεων.',
            'rightclick_phone' => '<strong>Στο κινητό</strong>, πατήστε παρατεταμένα ένα αίτημα για μισό δευτερόλεπτο ώστε να ανοίξει το ίδιο μενού ως πάνελ πλήρους οθόνης. Μια επιλογή με περισσότερες επιλογές &mdash; Ορισμός κατάστασης, Ορισμός προτεραιότητας, Ανάθεση σε &mdash; γλιστρά προς αυτές, με το <strong>Πίσω</strong> για επιστροφή.',
            'rightclick_tip' => 'Αν το αίτημα στο οποίο ενεργείτε μέσω του μενού περιβάλλοντος είναι το ίδιο με αυτό που είναι ανοιχτό στο παράθυρο ανάγνωσης, η αντίστοιχη ενότητα εκεί (αναπτυσσόμενες λίστες Κατάστασης / Προτεραιότητας, αντικείμενα CMDB, καταχωρίσεις χρόνου) ανανεώνεται αυτόματα όταν κλείσει το παράθυρο, ώστε η διεπαφή να μένει συγχρονισμένη.',
            'time_heading' => '<strong>Καταγραφή χρόνου</strong>',
            'time_body' => 'Ο χρόνος που αφιερώνεται σε ένα αίτημα καταγράφεται σε ειδική ενότητα <strong>Καταχωρίσεις χρόνου</strong> στο παράθυρο ανάγνωσης, ανάμεσα στο πάνελ των συσχετισμένων αντικειμένων CMDB και στο πάνελ Σημειώσεων. Η επικεφαλίδα δείχνει το τρέχον σύνολο (π.χ. «Σύνολο 2h 30m») και κάθε καταχώριση από κάτω δείχνει τον χρόνο, τον τεχνικό, την ημερομηνία και τυχόν σημειώσεις που προσθέσατε.',
            'time_step1' => '<strong>Ενσωματωμένη φόρμα</strong> &mdash; πληκτρολογήστε τα λεπτά στο αριθμητικό πεδίο, μια προαιρετική σύντομη περιγραφή στο πεδίο σημειώσεων και πατήστε <strong>Προσθήκη</strong>. Η νέα καταχώριση εμφανίζεται αμέσως στην κορυφή της λίστας με το όνομά σας και την τρέχουσα χρονική σήμανση.',
            'time_step2' => '<strong>Αναδρομική καταχώριση με δεξί κλικ</strong> &mdash; αν πρέπει να καταγράψετε χρόνο που ξεχάσατε νωρίτερα, κάντε δεξί κλικ στο αίτημα στη λίστα και επιλέξτε <strong>Καταγραφή χρόνου&hellip;</strong>. Το παράθυρο περιλαμβάνει επιλογέα ημερομηνίας και ώρας, ώστε να σημάνετε την καταχώριση με την πραγματική ώρα που έγινε η εργασία.',
            'time_step3' => '<strong>Διαγραφή των δικών σας καταχωρίσεων</strong> &mdash; ένα μικρό κουμπί &times; εμφανίζεται δίπλα στις καταχωρίσεις που κάνατε εσείς. Πατήστε το (και επιβεβαιώστε) για λογική διαγραφή &mdash; η γραμμή μένει στη βάση δεδομένων με <code>is_active = 0</code> για έλεγχο, αλλά εξαφανίζεται από τη λίστα. Δεν μπορείτε να διαγράψετε καταχωρίσεις άλλων τεχνικών.',
            'time_tip1' => 'Οι χρόνοι αποθηκεύονται ως απλά λεπτά (45 λεπτά, 90 λεπτά κ.λπ.) και εμφανίζονται ως <code>45m</code> ή <code>1h 30m</code> στη διεπαφή &mdash; αρκετά αναλυτικοί για σύντομες επιδιορθώσεις, χωρίς το πρόβλημα της στρογγυλοποίησης δεκαδικών ωρών.',
            'time_tip2' => 'Κάθε αλλαγή πεδίου καταγράφεται στο ιστορικό δραστηριότητας του αιτήματος. Μπορείτε πάντα να δείτε ποιος άλλαξε τι και πότε, κάτι ουσιώδες για τη συμμόρφωση σε έλεγχο και για τη παράδοση εργασίας ανάμεσα σε τεχνικούς.',
        ],
        'comments' => [
            'heading' => 'Σχόλια &amp; συνημμένα',
            'intro' => 'Το ιστορικό δραστηριότητας είναι η καρδιά κάθε αιτήματος. Καταγράφει κάθε ενέργεια &mdash; σχόλια, αλλαγές πεδίων, email που στάλθηκαν και αρχεία που επισυνάφθηκαν &mdash; σε ένα χρονολογικό ιστορικό που διηγείται ολόκληρη την ιστορία ενός αιτήματος υποστήριξης.',
            'adding_heading' => '<strong>Προσθήκη σχολίων</strong>',
            'step1' => '<strong>Ανοίξτε το αίτημα</strong> &mdash; κάντε κλικ σε οποιοδήποτε αίτημα των εισερχομένων για να φορτωθεί το παράθυρο ανάγνωσης. Κυλήστε προς τα κάτω για να δείτε ολόκληρο το ιστορικό δραστηριότητας και το πλαίσιο σχολίου στο κάτω μέρος.',
            'step2' => '<strong>Γράψτε τη σημείωσή σας</strong> &mdash; χρησιμοποιήστε το κουμπί Προσθήκη σημείωσης για να ανοίξετε τον επεξεργαστή σχολίων. Οι σημειώσεις είναι εσωτερικές από προεπιλογή και ορατές μόνο στους τεχνικούς του κέντρου εξυπηρέτησης.',
            'step3' => '<strong>Απάντηση ή προώθηση με email</strong> &mdash; χρησιμοποιήστε τις ενέργειες Απάντηση ή Προώθηση για να στείλετε μήνυμα στον τελικό χρήστη ή σε τρίτο. Το email καταγράφεται στο ιστορικό δραστηριότητας μαζί με το περιεχόμενο του εξερχόμενου μηνύματος.',
            'files_heading' => '<strong>Συνημμένα αρχεία</strong>',
            'files_body' => 'Επισυνάψτε στιγμιότυπα οθόνης, αρχεία καταγραφής, έγγραφα ή οποιοδήποτε υποστηρικτικό αρχείο απευθείας σε ένα αίτημα. Μπορείτε να σύρετε αρχεία στη ζώνη απόθεσης συνημμένων ή να τα επιλέξετε από τον περιηγητή αρχείων. Τα συνημμένα αποθηκεύονται στον διακομιστή και συνδέονται με το ιστορικό δραστηριότητας του αιτήματος, ώστε να μη χάνεται τίποτα.',
            'audit_heading' => '<strong>Καταγραφή ελέγχου</strong>',
            'export_heading' => '<strong>Αναφορές υπόθεσης</strong>',
            'export_body' => 'Για μια ανασκόπηση ή έναν ελεγκτή, το <strong>Εξαγωγή</strong> στη γραμμή εργαλείων του αιτήματος μετατρέπει το αίτημα και τις εργασίες του σε μία εκτυπώσιμη αναφορά - δείτε <a href="#case-reports">Αναφορές υπόθεσης</a>.',
            'audit_body' => 'Το ιστορικό δραστηριότητας καταγράφει αυτόματα κάθε ενέργεια χωρίς παρέμβαση του τεχνικού. Όταν η προτεραιότητα αλλάζει από Μεσαία σε Υψηλή, καταγράφονται η παλιά και η νέα τιμή. Όταν ένα αίτημα ανατίθεται εκ νέου, καταγράφονται ο προηγούμενος και ο νέος τεχνικός. Έτσι δημιουργείται ένα πλήρες ιστορικό που δεν παραποιείται, ικανοποιεί τις απαιτήσεις ελέγχου του ITIL και βοηθά τους προϊσταμένους να καταλάβουν πώς αντιμετωπίζονται τα αιτήματα.',
            'tip' => 'Όταν απαντάτε με email, μπορείτε να προσθέσετε παραλήπτες Cc και να επισυνάψετε αρχεία στην ίδια ενέργεια. Ολόκληρη η συνομιλία email ενσωματώνεται στο ιστορικό δραστηριότητας του αιτήματος, κρατώντας όλη την επικοινωνία σε ένα σημείο.',
        ],
        'ai' => [
            'heading' => 'Εργαλεία AI',
            'intro' => 'Δύο λειτουργίες βασισμένες στο Claude βρίσκονται μέσα στη ροή του αιτήματος: το <strong>Καθάρισμα απάντησης</strong> μετατρέπει ένα πρόχειρο σε σωστά διαμορφωμένο email και το <strong>Ρωτήστε το AI</strong> αναζητά στη γνωσιακή βάση με φυσική γλώσσα, χρησιμοποιώντας το πλαίσιο του αιτήματος.',
            'cleanup_heading' => '<strong>Καθάρισμα απάντησης &mdash; κουμπί ✨ στον επεξεργαστή απάντησης</strong>',
            'cleanup_body' => 'Πληκτρολογήστε ένα γρήγορο πρόχειρο σε μια απάντηση (ή απλώς κουκκίδες όπως *«πρέπει να κάνω επανεκκίνηση της υπηρεσίας εκτύπωσης, να τους στείλω στιγμιότυπο»*) και πατήστε το κουμπί <strong>✨ Καθάρισμα</strong>. Το Claude το ξαναγράφει ως σωστά διαμορφωμένο email &mdash; προσθέτει χαιρετισμό <em>Αγαπητέ/ή [όνομα],</em> προς τον αιτούντα, διορθώνει τη γραμματική, εφαρμόζει τον ρυθμισμένο τόνο και κλείνει με <em>Με εκτίμηση,</em>. Η εντολή είναι κλειδωμένη, ώστε ΝΑ ΜΗΝ επινοεί τεχνικές λεπτομέρειες, να μη φτιάχνει δήθεν συγγνώμες και να μη φουσκώνει το περιεχόμενο πέρα από όσα γράψατε.',
            'cleanup_streams' => '<strong>Εμφάνιση σε πραγματικό χρόνο</strong> &mdash; η νέα διατύπωση εμφανίζεται στον επεξεργαστή καθώς την παράγει το Claude (χωρίς αναμονή μπροστά σε ένδειξη φόρτωσης).',
            'cleanup_undo' => '<strong>Σύνδεσμος Αναίρεσης για 30 δευτ.</strong> &mdash; σε περίπτωση που το Claude χαλάσει τη διατύπωση, ένας μικρός σύνδεσμος <em>Αναίρεση</em> εμφανίζεται κάτω από τον επεξεργαστή για 30 δευτερόλεπτα μετά την ολοκλήρωση, επαναφέροντας το αρχικό πρόχειρο.',
            'cleanup_tone' => '<strong>Ανά τόνο</strong> &mdash; τρεις προρυθμίσεις τόνου που ρυθμίζονται στο <strong>Ρυθμίσεις &rarr; Καθάρισμα απάντησης</strong>: <em>Φιλικός</em> (προεπιλογή), <em>Επίσημος</em>, <em>Σύντομος</em>. Διαλέξτε αυτόν που ταιριάζει με το ύφος της ομάδας σας.',
            'cleanup_key' => '<strong>Δικό του κλειδί API</strong> &mdash; ξεχωριστό κλειδί Anthropic από τις λειτουργίες AI των RFP / Γνωσιακής βάσης / Ροών εργασιών, ώστε η χρήση του να εμφανίζεται ως δική του γραμμή στον πίνακα χρεώσεων της Anthropic. Ρυθμίζεται στο <strong>Ρυθμίσεις &rarr; Καθάρισμα απάντησης</strong>.',
            'cleanup_tip' => 'Το Καθάρισμα ταιριάζει περισσότερο σε συνηθισμένες απαντήσεις του τύπου «δοκίμασα αυτό, παρακαλώ δοκιμάστε το Χ». Τα μεγάλα, λεπτά μηνύματα θα θέλετε να τα γράφετε μόνοι σας &mdash; το AI τα πάει εξαιρετικά με τη δομή, αλλά δεν ξέρει το συγκεκριμένο περιβάλλον σας.',
            'ask_heading' => '<strong>Ρωτήστε το AI &mdash; κουμπί 🤖 στη γραμμή εργαλείων του αιτήματος</strong>',
            'ask_body' => 'Πατήστε το κουμπί <strong>Ρωτήστε το AI</strong> (🤖) στη γραμμή εργαλείων του αιτήματος για να ανοίξει ένα πλευρικό πάνελ συνομιλίας που γνωρίζει το θέμα, το κείμενο και το πλαίσιο ανάγνωσης του ανοιχτού αιτήματος. Κάντε του ερωτήσεις όπως *«το έχουμε ξαναδεί αυτό;»* ή *«ποια είναι η συνηθισμένη λύση για αυτό το σφάλμα;»* και αναζητά σημασιολογικά στη βάση <a href="../knowledge/" style="color:#0078d4;">Γνώσης</a> (μέσω Claude + OpenAI embeddings) και απαντά με σχετικά άρθρα, με άμεσους συνδέσμους για να τα ανοίξετε.',
            'ask_context' => '<strong>Με επίγνωση του πλαισίου</strong> &mdash; το πάνελ γνωρίζει ποιο αίτημα βλέπετε, ώστε να κάνετε γενικές ερωτήσεις και να βρίσκει μόνο του το σχετικό πλαίσιο.',
            'ask_linked' => '<strong>Συσχετισμένα άρθρα</strong> &mdash; οι προτάσεις είναι κλικαριστές και ανοίγουν το αντίστοιχο άρθρο της γνωσιακής βάσης σε νέα καρτέλα.',
            'ask_shared' => '<strong>Κοινό με την ενότητα Γνώση</strong> &mdash; το AI χρησιμοποιεί το ίδιο κλειδί και μοντέλο με την αναζήτηση AI της Γνωσιακής βάσης, οπότε αρκεί να το ρυθμίσετε μία φορά για να έχετε και τα δύο. Δείτε τη βοήθεια της ενότητας Γνώση για λεπτομέρειες ρύθμισης.',
        ],
        'csat' => [
            'heading' => 'Έρευνες ικανοποίησης πελατών (CSAT)',
            'intro' => 'Στείλτε με email στον αιτούντα μια έρευνα ικανοποίησης 1&ndash;5 όταν επιλύεται ένα αίτημα, καταγράψτε την απάντηση σε σελίδα προσγείωσης χωρίς σύνδεση και παρακολουθήστε τις τάσεις ανά τεχνικό σε ειδική σελίδα αναλυτικών.',
            'modes_heading' => '<strong>Δύο τρόποι εκκίνησης &mdash; διαλέξτε έναν</strong>',
            'mode_auto' => '<strong>Αυτόματα στο κλείσιμο</strong> &mdash; η έρευνα μπαίνει αυτόματα στην ουρά όταν ένα αίτημα περνά σε οποιαδήποτε κατάσταση κλεισίματος. Ο τεχνικός δεν χρειάζεται να κάνει τίποτα &mdash; η επίλυση ενεργοποιεί την έρευνα. Αν οριστεί <strong>καθυστέρηση</strong>, η έρευνα περιμένει τόσο και αποστέλλεται από τη διεργασία παρασκηνίου <em>Έρευνες ικανοποίησης με καθυστέρηση</em> &mdash; και μόνο αν το αίτημα εξακολουθεί να είναι κλειστό μέχρι τότε. Μια προαιρετική <strong>υπενθύμιση</strong> μπορεί να σταλεί μία φορά σε όποιον δεν έχει απαντήσει μετά από ορισμένο αριθμό ωρών, με τον ίδιο σύνδεσμο.',
            'mode_manual' => '<strong>Μόνο χειροκίνητα</strong> &mdash; ο τεχνικός πατά το κουμπί ⭐ <strong>Σχόλια</strong> στη γραμμή εργαλείων του αιτήματος όταν θέλει να ρωτήσει. Χρήσιμο όταν προτιμάτε να αποφασίζετε αίτημα προς αίτημα αν θα ζητήσετε σχόλια.',
            'switch_note' => 'Δεν χρησιμοποιείτε καθόλου CSAT; Απενεργοποιήστε το στο <strong>Σύστημα &rarr; Ενότητες &rarr; Διαθεσιμότητα &rarr; Λειτουργίες αιτημάτων</strong> και εξαφανίζεται: καμία έρευνα, καμία σελίδα CSAT, κανένα κουμπί αιτήματος σχολίων, και οι παλιοί σύνδεσμοι έρευνας λένε ότι δεν συλλέγονται πλέον σχόλια. Τίποτα δεν διαγράφεται.',
            'mode_off' => '<strong>Ανενεργό</strong> &mdash; δεν στέλνονται έρευνες. Η σελίδα CSAT και τα αποτελέσματα παραμένουν· για να αφαιρέσετε εντελώς το CSAT, απενεργοποιήστε το στο <strong>Σύστημα &rarr; Ενότητες &rarr; Διαθεσιμότητα</strong>.',
            'modes_choose' => 'Επιλέξτε στο <strong>Αιτήματα &rarr; Ρυθμίσεις &rarr; CSAT</strong>. Το χειροκίνητο κουμπί λειτουργεί και στον <em>αυτόματο</em> τρόπο &mdash; οι τεχνικοί μπορούν να ζητήσουν ξανά σχόλια για ένα αίτημα που έχει ήδη λάβει έρευνα, αν χρειαστεί.',
            'template_heading' => '<strong>Το πρότυπο email</strong>',
            'template_body' => 'Το περιεχόμενο του email έρευνας προέρχεται από την υπάρχουσα καρτέλα <strong>Πρότυπα email</strong> &mdash; δημιουργήστε ένα πρότυπο με συμβάν <strong>Έρευνα CSAT</strong> (το νέο συμβάν δίπλα στα <em>Ανάθεση αιτήματος</em> / <em>Κλείσιμο αιτήματος</em>) και εισαγάγετε τον κωδικό συγχώνευσης <code>[csat_link]</code> όπου θέλετε να εμφανίζεται η διεύθυνση βαθμολόγησης. Οι τυπικοί κωδικοί συγχώνευσης (<code>[requester_name]</code>, <code>[ticket_reference]</code>, <code>[analyst_name]</code>) είναι διαθέσιμοι κανονικά.',
            'template_tip' => 'Αν δεν υπάρχει ενεργό πρότυπο CSAT, το κουμπί <em>Σχόλια</em> αρνείται με σαφές σφάλμα και η αυτόματη εκκίνηση παραλείπεται σιωπηλά &mdash; δεν μπορείτε ποτέ να παράγετε νεκρούς συνδέσμους έρευνας.',
            'survey_heading' => '<strong>Η σελίδα της έρευνας</strong>',
            'survey_body' => 'Ο αιτών κάνει κλικ στον σύνδεσμο του email και φτάνει σε σελίδα χωρίς σύνδεση με επιλογέα 1&ndash;5 και προαιρετικό πλαίσιο σχολίου. Δύο οπτικά στυλ ρυθμίζονται στο <strong>Ρυθμίσεις &rarr; CSAT</strong>:',
            'survey_stars' => '<strong>Αστέρια</strong> &mdash; κλασική συμπεριφορά γεμίσματος με το πέρασμα του δείκτη. Αν περάσετε πάνω από το αστέρι #3, γεμίζουν τα #1+#2+#3 με χρυσό. Κάντε κλικ για να κλειδώσει.',
            'survey_emojis' => '<strong>Emoji</strong> &mdash; 5 πρόσωπα 😡 🙁 😐 🙂 😀 ξεκινούν σε κλίμακα του γκρι με 40% αδιαφάνεια· αυτό που περνά ο δείκτης ή επιλέγεται επανέρχεται σε πλήρες χρώμα με μεγέθυνση 1,25&times;. Κάντε κλικ για να κλειδώσει.',
            'survey_store' => 'Και οι δύο τρόποι αποθηκεύουν τον ίδιο αριθμό 1&ndash;5, ώστε οι πίνακες ελέγχου και οι μέσοι όροι να λειτουργούν πανομοιότυπα ανεξάρτητα από το στυλ που χρησιμοποιείται. Ο σύνδεσμος της έρευνας είναι μίας χρήσης &mdash; μόλις υποβάλει ο χρήστης, ο ίδιος σύνδεσμος αρνείται νέα υποβολή.',
            'chat_heading' => '<strong>Ερώτηση στους πελάτες της συνομιλίας μέσα στη συνομιλία τους</strong>',
            'chat_body' => 'Με επιλεγμένο το <strong>Ερώτηση στους πελάτες συνομιλίας μέσα στη συνομιλία τους</strong>, ένας πελάτης που επικοινώνησε μέσω WhatsApp, Telegram, Slack, Microsoft Teams ή Mattermost ερωτάται σε αυτή τη συνομιλία αντί για email &mdash; πέντε κουμπιά σε Telegram, Teams και Mattermost, «απαντήστε με ένα μόνο ψηφίο» στα υπόλοιπα. Η απάντησή του καταλήγει στα ίδια αποτελέσματα με μια έρευνα που στάλθηκε με email.',
            'chat_rules' => 'Το WhatsApp ερωτάται μόνο όσο είναι ανοιχτό το παράθυρο απάντησης των 24 ωρών· εκτός αυτού, ή αν το μήνυμα συνομιλίας δεν μπορεί να σταλεί, χρησιμοποιείται η έρευνα με email. Ένα ψηφίο μετράει ως βαθμολογία μόνο αμέσως μετά την ερώτηση &mdash; στην ίδια συνομιλία, μέσα σε μία εβδομάδα και πριν ο πελάτης γράψει οτιδήποτε άλλο &mdash; ώστε το «3» ως απάντηση σε ερώτηση τεχνικού να μένει μήνυμα. Ανενεργό μετά από αναβάθμιση· ενεργό σε νέα εγκατάσταση.',
            'analytics_heading' => '<strong>Η σελίδα αναλυτικών</strong>',
            'analytics_body' => 'Κάντε κλικ στο κουμπί πλοήγησης ⭐ <strong>CSAT</strong> (ανάμεσα στα Πρόγραμμα βαρδιών και Ρυθμίσεις) για να ανοίξετε τον πίνακα αναλυτικών στο <code>tickets/csat/</code>. Επιλέξιμο παράθυρο: 7 / 30 / 90 / 365 ημέρες.',
            'card_kpi_title' => 'Πλακίδια KPI',
            'card_kpi_body' => 'Μέση βαθμολογία (στα 5), πλήθος απαντήσεων, ποσοστό απόκρισης (απαντήσεις ÷ απεσταλμένες)',
            'card_dist_title' => 'Κατανομή βαθμολογιών',
            'card_dist_body' => 'Ραβδογράφημα βαθμολογιών 1–5 με ακριβή πλήθη και ποσοστά',
            'card_leader_title' => 'Κατάταξη ανά τεχνικό',
            'card_leader_body' => 'Μέση βαθμολογία + πλήθος απαντήσεων ανά τεχνικό, με φθίνουσα σειρά μέσου όρου. Χρησιμοποιήστε το για συζητήσεις ανάπτυξης',
            'card_recent_title' => 'Πρόσφατες απαντήσεις',
            'card_recent_body' => 'Οι βαθμολογίες με τις νεότερες πρώτες, 25 ανά σελίδα, με τα ελεύθερα σχόλιά τους και τον πελάτη που τα άφησε, συσχετισμένες με το αρχικό αίτημα',
            'analytics_filters' => 'Περιορίστε τη σελίδα με τα φίλτρα κάτω από την επικεφαλίδα: ένα εύρος ημερομηνιών <strong>Από / Έως</strong> (αντί για τα κουμπιά ημερών), μια ζώνη <strong>Βαθμολογίας</strong> (Θετική 4-5, Ουδέτερη 3, Αρνητική 1-2), έναν <strong>Τεχνικό</strong> και έναν <strong>Πελάτη</strong>. Ο τεχνικός και ο πελάτης περιορίζουν κάθε στοιχείο της σελίδας· η ζώνη βαθμολογίας περιορίζει μόνο τη λίστα απαντήσεων, ώστε ο μέσος όρος να παραμένει ουσιαστικός. Στο κινητό τα φίλτρα βρίσκονται πίσω από το κουμπί <strong>Φίλτρα</strong> στο κάτω μέρος της οθόνης. Μια φιλτραρισμένη σελίδα μπορεί να αποθηκευτεί στους σελιδοδείκτες.',
            'analytics_company' => 'Κάθε στοιχείο ακολουθεί τον <strong>εναλλάκτη εταιρείας</strong> στην κεφαλίδα: την εταιρεία που έχετε επιλέξει ή κάθε εταιρεία που βλέπετε στο <strong>Όλες οι εταιρείες</strong>.',
            'analytics_tip' => 'Η απόδοση ανά τεχνικό επιβιώνει της εκ νέου ανάθεσης αιτήματος, επειδή το αναγνωριστικό του τεχνικού καταγράφεται στη γραμμή της έρευνας τη στιγμή της αποστολής και δεν αναζητείται ζωντανά. Αν ένα αίτημα περάσει από πολλά χέρια πριν κλείσει, τη βαθμολογία την κατέχει ο τεχνικός που το έκλεισε πραγματικά.',
            'one_heading' => '<strong>Μία έρευνα ανά αίτημα</strong>',
            'one_body' => 'Αν η <em>Μία έρευνα ανά αίτημα</em> είναι ενεργή (προεπιλογή), ένα αίτημα που ξανανοίγει και ξανακλείνει λαμβάνει νέα έρευνα μόνο όταν την ενεργοποιήσει χειροκίνητα ένας τεχνικός &mdash; αποτρέπει το σπάμ ερευνών σε ένα προβληματικό αίτημα που συνεχίζει να κάνει κύκλους. Απενεργοποιήστε την αν θέλετε κάθε κλείσιμο να στέλνει νέα έρευνα.',
        ],
        'users' => [
            'heading' => 'Διαχείριση χρηστών',
            'intro' => 'Το κουμπί <strong>Χρήστες</strong> στη γραμμή πλοήγησης ανοίγει το <code>tickets/users.php</code> &mdash; έναν κατάλογο όλων των τελικών χρηστών (των ατόμων που υποβάλλουν αιτήματα, όχι των τεχνικών) μαζί με το ιστορικό αιτημάτων του καθενός.',
            'p_intro' => 'Οι χρήστες εισάγονται στο σύστημα με τέσσερις αντιδραστικούς τρόπους &mdash; αυτοεγγραφή στην πύλη, εισερχόμενο email από νέο αποστολέα, τον έλεγχο των γραμματοκιβωτίων ή τη μηχανή ροών εργασιών, που δημιουργεί έναν χρήστη από ένα αίτημα που ενεργοποιήθηκε. Αυτό καλύπτει τις περισσότερες περιπτώσεις, αλλά η σελίδα Χρήστες σάς επιτρέπει επίσης να <strong>δημιουργήσετε εκ των προτέρων</strong> έναν χρήστη (π.χ. έναν νέο εργαζόμενο που σύντομα θα χρειαστεί πρόσβαση) και να <strong>επεξεργαστείτε</strong> ή να <strong>διαγράψετε</strong> υπάρχουσες εγγραφές.',
            'add_heading' => '<strong>Προσθήκη χρήστη</strong>',
            'add_body' => 'Το κουμπί <strong>Προσθήκη</strong> στην κεφαλίδα της λίστας χρηστών ανοίγει τον επεξεργαστή ατόμου. Είναι ο ίδιος επεξεργαστής που ανοίγει το <strong>Πάγια &rarr; Χρήστες</strong>, οπότε ένα άτομο προστίθεται και αλλάζει με τον ίδιο τρόπο από όποια οθόνη κι αν βρίσκεστε:',
            'add_email' => '<strong>Email</strong> &mdash; προαιρετικό, επειδή όσοι συνδέονται μέσω καταλόγου μπορεί να μην έχουν γραμματοκιβώτιο· βρίσκονται με το όνομα σύνδεσής τους. Δώστε είτε διεύθυνση email είτε εμφανιζόμενο όνομα. Η διεύθυνση πρέπει να είναι μοναδική και να μην ανήκει σε τεχνικό.',
            'add_names' => '<strong>Εμφανιζόμενο όνομα / προτιμώμενο όνομα</strong> &mdash; προαιρετικό. Το προτιμώμενο όνομα είναι αυτό με το οποίο χαιρετίζεται ο χρήστης στα email (π.χ. <em>«Ed»</em> αντί για <em>«Ed Mozley»</em>).',
            'add_password' => '<strong>Κωδικός πρόσβασης</strong> &mdash; προαιρετικός. Αν τον αφήσετε κενό, δημιουργείται λογαριασμός <em>χωρίς κωδικό</em> &mdash; ακριβώς η ίδια κατάσταση με την οποία ξεκινούν οι χρήστες από εισερχόμενα αιτήματα. Ο χρήστης μπορεί αργότερα να διεκδικήσει τον λογαριασμό μέσω της εγγραφής στην πύλη αυτοεξυπηρέτησης, ορίζοντας τον δικό του κωδικό.',
            'add_details' => '<strong>Θέση εργασίας, τμήμα, γραφείο, τηλέφωνο, κινητό, κωδικός υπαλλήλου και προϊστάμενος</strong> &mdash; όλα προαιρετικά, και όλα περιγράφουν το <em>άτομο</em> και όχι τη σύνδεση. Αξίζει να τα συμπληρώσετε: το <strong>γραφείο</strong> δείχνει σε ποια τοποθεσία βρίσκεται κάποιος πριν τον αναζητήσετε, ο <strong>προϊστάμενος</strong> καταγράφει την ιεραρχική σχέση (πληκτρολογήστε μέρος του ονόματος για να τον βρείτε) και ο <strong>κωδικός υπαλλήλου</strong> είναι το κλειδί αντιστοίχισης όταν συμφιλιώνετε με σύστημα μισθοδοσίας που δεν γνωρίζει διευθύνσεις email. Όταν κάνετε εισαγωγή από κατάλογο, όλα αυτά έρχονται συμπληρωμένα. Ένα βιβλίο διευθύνσεων CardDAV συμπληρώνει τα πάντα εκτός από τον κωδικό υπαλλήλου και τον προϊστάμενο, που μια κάρτα επαφής δεν έχει πού να τα αποθηκεύσει.',
            'managed_heading' => '<strong>Άτομα που τηρούνται αλλού</strong>',
            'source_body' => '<strong>Από πού προέρχεται ένα άτομο</strong> αναγράφεται στις λεπτομέρειές του (<em>Λεπτομέρειες από: Contoso AD - κατάλογος</em>), και το φίλτρο <strong>Πηγή</strong> κάτω από το πλαίσιο αναζήτησης εμφανίζει μόνο τα άτομα ενός καταλόγου ή βιβλίου διευθύνσεων, ή μόνο όσα προστέθηκαν στο FreeITSM, με πλήθος δίπλα σε καθένα. Εμφανίζεται μόλις συσχετιστεί κάποιος με μια πηγή.',
            'add_book_body' => '<strong>Προσθήκη στο βιβλίο διευθύνσεων.</strong> Κάποιος που έστειλε email υπάρχει εδώ, αλλά όχι σε κανένα βιβλίο διευθύνσεων. Αν ένας διαχειριστής έχει ενεργοποιήσει την επιλογή <em>Να επιτρέπεται στους τεχνικούς να προσθέτουν άτομα σε αυτό το βιβλίο διευθύνσεων</em> (Σύστημα &rarr; Έλεγχος ταυτότητας, στο βιβλίο διευθύνσεων), αυτό το άτομο αποκτά ένα κουμπί <strong>Προσθήκη στο βιβλίο διευθύνσεων</strong> δίπλα στην Επεξεργασία. Ζητά πρώτα επιβεβαίωση, δείχνοντας τι θα γραφτεί στην κάρτα, και έπειτα δημιουργεί την επαφή του και τη συσχετίζει &mdash; το ίδιο άτομο, όχι αντίγραφο. Δεν θα προσθέσει κάποιον του οποίου τη διεύθυνση email έχει ήδη το βιβλίο (εκτελέστε αντί γι\' αυτό την εισαγωγή), και φροντίζει ώστε η επόμενη εισαγωγή να παραλάβει τη νέα επαφή, αλλιώς αφαιρεί ξανά την κάρτα.',
            'managed_body' => 'Όταν ένα άτομο έχει εισαχθεί &mdash; από LDAP ή Active Directory, ή από βιβλίο διευθύνσεων CardDAV &mdash; οι λεπτομέρειες που ανήκουν στην πηγή είναι <strong>μόνο για ανάγνωση</strong> και το παράθυρο τις εμφανίζει γκριζαρισμένες. Η πηγή από την οποία προήλθαν είναι η αξιόπιστη αναφορά, και η επόμενη εισαγωγή θα αντικαθιστούσε ό,τι πληκτρολογηθεί εδώ, οπότε η αποθήκευση απορρίπτεται εξαρχής αντί να γίνεται δεκτή και να αναιρείται σιωπηλά μία ώρα αργότερα. <strong>Ποιες</strong> λεπτομέρειες εξαρτάται από την πηγή: ένας κατάλογος κατέχει και τις επτά, ενώ ένα βιβλίο διευθύνσεων κατέχει πέντε &mdash; δεν έχει πού να κρατήσει αριθμό υπαλλήλου ή ιεραρχική σχέση, οπότε αυτά τα δύο παραμένουν δικά σας να τα συμπληρώσετε. Και αν το βιβλίο διευθύνσεων έχει ενεργοποιημένη την <em>εγγραφή αλλαγών πίσω</em>, κανένα δεν είναι κλειδωμένο: ό,τι πληκτρολογείτε στέλνεται στην κάρτα επαφής, οπότε δεν υπάρχει κάτι που να αναιρέσει η επόμενη εισαγωγή. Όλα τα υπόλοιπα στην εγγραφή, συμπεριλαμβανομένων της εταιρείας και του κωδικού πρόσβασης, είναι πάντα επεξεργάσιμα.',
            'edit_heading' => '<strong>Επεξεργασία χρήστη</strong>',
            'edit_body' => 'Επιλέξτε έναν χρήστη από τη λίστα και κάντε κλικ στην <strong>Επεξεργασία</strong> στην κεφαλίδα λεπτομερειών. Ο ίδιος επεξεργαστής, προσυμπληρωμένος. Αν αποθηκεύσετε χωρίς κωδικό, ο υπάρχων κατακερματισμός (hash) μένει ανέγγιχτος· αν δώσετε κωδικό, γίνεται επαναφορά. Αν ο προϊστάμενός του είναι κάποιος από εταιρεία που δεν μπορείτε να δείτε, το πλαίσιο Προϊστάμενος το αναφέρει και ο προϊστάμενος διατηρείται ως έχει, εκτός αν επιλέξετε κάποιον άλλον.',
            'signin_body' => 'Το <strong>Συνδέεται με</strong> δείχνει με ποιον πάροχο ενιαίας σύνδεσης (single sign-on) είναι συσχετισμένο ένα άτομο. Το <strong>Αποσυσχέτιση</strong> δίπλα του, μετά από επιβεβαίωση, αφαιρεί αυτή τη συσχέτιση ώστε η επόμενη σύνδεσή του να ξεκινήσει από την αρχή &mdash; για κάποιον που άλλαξε πάροχο ή συσχετίστηκε με λάθος λογαριασμό. Δεν προσφέρεται για άτομα που διαχειρίζεται συγχρονισμός καταλόγου, ο οποίος απλώς θα τα συσχέτιζε ξανά.',
            'company_body' => 'Η <strong>Εταιρεία</strong> εμφανίζεται όταν έχετε περισσότερες από μία. Για ένα νέο άτομο, αν την αφήσετε κενή, η εταιρεία προκύπτει από τη διεύθυνση email του· για ένα υπάρχον άτομο, κενή σημαίνει καμία εταιρεία και τα αιτήματά του πηγαίνουν σε διαλογή.',
            'managers_heading' => '<strong>Προϊστάμενοι</strong>',
            'managers_body' => 'Ένα άτομο μπορεί να οριστεί <strong>προϊστάμενος</strong> στην πύλη αυτοεξυπηρέτησης: αποκτά μια καρτέλα <strong>Αιτήματα ομάδας</strong> που εμφανίζει τα αιτήματα των ατόμων που προΐσταται. Είναι απενεργοποιημένο μέχρι να το ενεργοποιήσει ένας διαχειριστής στο <strong>Σύστημα &rarr; Προϊστάμενοι</strong>, όπου καθορίζεται επίσης αν οι προϊστάμενοι μπορούν να απαντούν ή να κλείνουν αυτά τα αιτήματα, και τι βλέπουν από ένα εμπιστευτικό (τίποτα, από προεπιλογή).',
            'managers_sources' => 'Κάποιος είναι προϊστάμενος με δύο τρόπους, και τους δύο ταυτόχρονα: είναι ο <strong>Προϊστάμενος</strong> στις εγγραφές άλλων ατόμων (με το χέρι ή από τον κατάλογό σας) και έχουν οριστεί γι\' αυτόν <strong>γραμμές διοίκησης</strong>. Κάντε κλικ στο <strong>Πρόσβαση προϊσταμένου</strong> δίπλα στην Επεξεργασία για να ανοίξετε μια σελίδα πλήρους οθόνης για το άτομο, όπου μπορείτε να του δώσετε όλους, συγκεκριμένα άτομα, ομάδες ατόμων, τμήματα ή ολόκληρη την ιεραρχική του γραμμή, και να <strong>εξαιρέσετε</strong> άτομα &mdash; η εξαίρεση υπερισχύει πάντα, ακόμη και του πεδίου Προϊστάμενος. Η σελίδα δείχνει πόσα άτομα μπορεί να δει και τα απαριθμεί, υπολογισμένα σαν να ήταν ήδη ενεργοποιημένοι οι προϊστάμενοι, ώστε να ελέγξετε πριν την ενεργοποίηση. Κάντε κλικ σε οποιονδήποτε στη λίστα για να δείτε <strong>γιατί</strong> τον βλέπει ο προϊστάμενος και πώς να το σταματήσετε.',
            'managers_rules' => 'Ένας προϊστάμενος βλέπει πάντα μόνο άτομα της δικής του εταιρείας, ποτέ τον εαυτό του, και τίποτα απολύτως όταν αποχωρήσει. Τα τμήματα αντιστοιχίζονται με το όνομα που έχει πληκτρολογηθεί σε κάθε άτομο, οπότε ένα τμήμα που μετονομάστηκε παύει να ταιριάζει &mdash; η σελίδα και το Σύστημα &rarr; Προϊστάμενοι προειδοποιούν για γραμμή τμήματος που δεν ταιριάζει με κανέναν. Από προεπιλογή μόνο οι διαχειριστές μπορούν να αλλάζουν γραμμές διοίκησης· το Σύστημα &rarr; Προϊστάμενοι μπορεί να το ανοίξει σε οποιονδήποτε μπορεί να επεξεργάζεται άτομα.',
            'delete_heading' => '<strong>Διαγραφή χρήστη</strong>',
            'delete_body' => 'Το κουμπί <strong>Διαγραφή</strong> είναι <strong>ασφαλές ως προς τα ξένα κλειδιά (FK-safe)</strong>: αρνείται τη διαγραφή αν ο χρήστης είναι ο αιτών σε οποιαδήποτε αιτήματα ή έχει εγγραφές στο <code>users_assets</code>, επιστρέφοντας ένα σαφές μήνυμα <em>«Δεν είναι δυνατή η διαγραφή: αυτός ο χρήστης είναι ο αιτών σε N αιτήματα. Αναθέστε ξανά ή κλείστε πρώτα αυτά τα αιτήματα.»</em> Το ιστορικό ελέγχου δεν μπορεί ποτέ να χαλάσει σιωπηλά.',
            'tip' => 'Σε όλα τα πεδία του παραθύρου η αυτόματη συμπλήρωση του προγράμματος περιήγησης είναι απενεργοποιημένη (συμπεριλαμβανομένου του <code>autocomplete="new-password"</code> στο πεδίο κωδικού), ώστε να μην προτείνονται τα αποθηκευμένα διαπιστευτήρια του ίδιου του τεχνικού σε μια φόρμα που σκοπό έχει τη δημιουργία της εγγραφής <em>κάποιου άλλου</em>.',
            'groups_heading' => '<strong>Ομάδες χρηστών</strong>',
            'groups_body' => 'Η καρτέλα <strong>Ομάδες χρηστών</strong> δίπλα στα <strong>Άτομα</strong> περιέχει ονομασμένες ομάδες ατόμων &mdash; τεχνικοί και χρήστες της πύλης αυτοεξυπηρέτησης μαζί στην ίδια ομάδα. Μια ομάδα δημιουργείται μία φορά εδώ και μετά χρησιμοποιείται σε όλο το FreeITSM, ώστε να της δώσετε πρόσβαση σε φάκελο της γνωσιακής βάσης ή να της αναθέσετε ένα μάθημα εκπαίδευσης χωρίς να φτιάξετε την ίδια λίστα δύο φορές.',
            'groups_make' => '<strong>Δημιουργήστε μία</strong> με το <strong>Προσθήκη</strong> στην καρτέλα Ομάδες χρηστών: ένα όνομα και μια περιγραφή που αξίζει να συμπληρωθεί, επειδή ο επόμενος πρέπει να μπορεί να καταλάβει σε τι χρησιμεύει η ομάδα.',
            'groups_add' => '<strong>Προσθέστε άτομα</strong> αναζητώντας τα &mdash; βρίσκει τεχνικούς και χρήστες της πύλης μαζί, ώστε να μη χρειάζεται να ξέρετε τι είδους είναι κάποιος.',
            'groups_expiry' => '<strong>Ορίστε ημερομηνία λήξης σε μια συμμετοχή</strong> όταν η πρόσβαση είναι προσωρινή. Τρεις μηχανικοί που βρίσκονται επιτόπου για δύο εβδομάδες μπαίνουν με τελευταία ημέρα και φεύγουν από την ομάδα από μόνοι τους όταν περάσει. Μια ληγμένη συμμετοχή παραμένει στη λίστα, σημειωμένη ως ληγμένη, ώστε να βλέπετε ακόμη ποιος είχε πρόσβαση και μέχρι πότε.',
            'groups_uses' => '<strong>Σε τι χρησιμεύει μια ομάδα:</strong> στη χορήγηση πρόσβασης σε φάκελο της γνωσιακής βάσης και στην ανάθεση εκπαίδευσης LMS σε ένα σύνολο ατόμων ταυτόχρονα. Οι αλλαγές στη συμμετοχή ισχύουν αμέσως &mdash; δεν χρειάζεται να εφαρμόσετε κάτι ξανά αργότερα.',
            'groups_admin' => '<strong>Όποιος έχει την ενότητα Αιτήματα μπορεί να δει τις ομάδες· μόνο ένας διαχειριστής μπορεί να αλλάξει μία.</strong> Η προσθήκη κάποιου σε μια ομάδα μπορεί να του δώσει και πρόσβαση σε περιορισμένο φάκελο της γνωσιακής βάσης, οπότε είναι χορήγηση πρόσβασης και όχι απλή αρχειοθέτηση.',
        ],
        'dash' => [
            'heading' => 'Πίνακας ελέγχου',
            'intro' => 'Ο πίνακας ελέγχου των αιτημάτων παρέχει αναλυτικά στοιχεία με μια ματιά, με προσαρμόσιμα γραφικά στοιχεία Chart.js. Κάθε τεχνικός έχει τη δική του διάταξη πίνακα ελέγχου, ώστε να εστιάζετε στις μετρήσεις που μετράνε για τον ρόλο σας &mdash; είτε πρόκειται για τον προσωπικό φόρτο εργασίας, την απόδοση της ομάδας ή τη συμμόρφωση με τα SLA.',
            'step1' => '<strong>Ανοίξτε τη Βιβλιοθήκη</strong> &mdash; κάντε κλικ στο Επεξεργασία πίνακα ελέγχου για να μπείτε σε λειτουργία επεξεργασίας και περιηγηθείτε στη βιβλιοθήκη γραφικών στοιχείων. Επιλέξτε από έτοιμα γραφικά στοιχεία ή δημιουργήστε δικά σας, επιλέγοντας τύπο γραφήματος και την ιδιότητα δεδομένων προς συγκέντρωση.',
            'step2' => '<strong>Προσθέστε γραφικά στοιχεία</strong> &mdash; κάντε κλικ στο κουμπί + σε οποιοδήποτε γραφικό στοιχείο της βιβλιοθήκης για να το προσθέσετε στον πίνακα ελέγχου σας. Εμφανίζεται αμέσως και αρχίζει να δείχνει ζωντανά δεδομένα από τη βάση των αιτημάτων σας.',
            'step3' => '<strong>Διαμορφώστε</strong> &mdash; κάντε κλικ στο εικονίδιο γραναζιού σε οποιοδήποτε γραφικό στοιχείο για να προσαρμόσετε τον τίτλο του, τον τύπο γραφήματος (ραβδωτό, πίτα, ντόνατ, γραμμή, στοιβαγμένο ραβδωτό, πολλαπλής γραμμής), το φίλτρο εύρους ημερομηνιών, το φίλτρο τμήματος και την ομαδοποίηση χρόνου (ημερήσια, εβδομαδιαία, μηνιαία).',
            'step4' => '<strong>Τακτοποιήστε</strong> &mdash; σύρετε και αποθέστε τα γραφικά στοιχεία για να αλλάξετε τη σειρά τους. Η διάταξή σας αποθηκεύεται ανά τεχνικό και διατηρείται σε όλες τις συνεδρίες.',
            'examples' => 'Συνηθισμένα παραδείγματα γραφικών στοιχείων: <strong>Αιτήματα ανά κατάσταση</strong> (γράφημα ντόνατ με ανοιχτά, επιλυμένα και κλειστά), <strong>Αιτήματα ανά προτεραιότητα</strong> (ραβδωτό γράφημα όγκου ανά βαρύτητα), <strong>Εβδομαδιαίος όγκος</strong> (γράφημα γραμμής που παρακολουθεί τα νέα αιτήματα στον χρόνο) και <strong>Φόρτος εργασίας τεχνικών</strong> (στοιβαγμένο ραβδωτό με τα ενεργά αιτήματα κάθε τεχνικού).',
            'tip' => 'Χρησιμοποιήστε φίλτρα εύρους ημερομηνιών σε μεμονωμένα γραφικά στοιχεία για να συγκρίνετε την τρέχουσα απόδοση με προηγούμενες περιόδους. Για παράδειγμα, μια προβολή «Αυτός ο μήνας έναντι του προηγούμενου» σας βοηθά να εντοπίζετε νωρίς τάσεις στον όγκο των αιτημάτων.',
        ],
        'cal_rota' => [
            'switch_note' => 'Δεν χρησιμοποιείτε το πρόγραμμα εφημεριών; Απενεργοποιήστε το από το <strong>Σύστημα &rarr; Ενότητες &rarr; Διαθεσιμότητα &rarr; Λειτουργίες αιτημάτων</strong> - η σελίδα, οι ρυθμίσεις της και το <em>ποιος εφημερεύει</em> του bot του War Room αφαιρούνται και τίποτα δεν διαγράφεται.',
            'heading' => 'Ημερολόγιο &amp; πρόγραμμα βαρδιών',
            'intro' => 'Δύο εργαλεία χρονοπρογραμματισμού βοηθούν την ομάδα σας να είναι οργανωμένη: ένα ημερολόγιο αιτημάτων που απεικονίζει τον φόρτο εργασίας στον χρόνο και ένα πρόγραμμα βαρδιών προσωπικού για τη διαχείριση βαρδιών και της διαθεσιμότητας εφημερίας.',
            'cal_heading' => '<strong>Προβολή ημερολογίου</strong>',
            'cal_body' => 'Το ημερολόγιο απεικονίζει κάθε αίτημα που έχετε προγραμματίσει &mdash; μέσω του <strong>Προγραμματισμός εργασίας</strong>, που βρίσκεται στο ίδιο το αίτημα και στο μενού δεξιού κλικ των εισερχομένων &mdash; ως έγχρωμο μπλοκ στην προγραμματισμένη ώρα του, σχεδιασμένο στην <strong>πραγματική του διάρκεια</strong> και όχι σε σταθερή ώρα. Τα κόκκινα μπλοκ είναι υψηλής προτεραιότητας (<em>High</em>), τα πράσινα χαμηλής (<em>Low</em>) και τα μπλε οτιδήποτε άλλο. Χρησιμοποιήστε το <em>Σήμερα</em>, τα βέλη <em>&lt;</em> / <em>&gt;</em> και τον διακόπτη <strong>Μήνας / Εβδομάδα / Ημέρα</strong> για να πλοηγηθείτε.',
            'cal_scope' => '<strong>Δικά μου ή Όλων.</strong> Το ημερολόγιο ανοίγει στις δικές σας προγραμματισμένες εργασίες, με διακόπτη <strong>Όλων</strong> δίπλα στα κουμπιά προβολής· η επιλογή σας διατηρείται. Στο Όλων κάθε αίτημα φέρει ένα <strong>χρώμα για όποιον το έχει αναλάβει</strong>, με υπόμνημα που ονομάζει τα άτομα που εμφανίζονται πραγματικά στην οθόνη, και αν περάσετε το ποντίκι πάνω από ένα αίτημα σάς λέει τίνος είναι χωρίς να κοιτάξετε αλλού. Τίποτα δεν κρύβεται από κανέναν &mdash; είναι τα ίδια αιτήματα που ήδη εμφανίζουν τα εισερχόμενα.',
            'cal_edit' => '<strong>Αναδιάταξη εργασιών.</strong> <strong>Σύρετε ένα αίτημα</strong> σε άλλη ημέρα ή ώρα: στην προβολή Μήνα διατηρεί την ώρα του και στις προβολές Εβδομάδας και Ημέρας παίρνει την ώρα στην οποία το αφήνετε, στρογγυλεμένη στο πλησιέστερο τέταρτο της ώρας. Η διάρκειά του δεν αλλάζει ποτέ &mdash; το σύρσιμο λέει <em>ξεκίνα τότε</em>, όχι <em>κάν\' το μεγαλύτερο</em>. Ή <strong>κάντε κλικ σε ένα αίτημα</strong> για να το ανοίξετε, όπου μπορείτε να αλλάξετε την ημερομηνία, την ώρα, τη διάρκεια και τη ρύθμιση ολοήμερου ή να διαγράψετε εντελώς τον προγραμματισμό. Το ημερολόγιο <strong>ανανεώνεται μόνο του κάθε λίγα δευτερόλεπτα</strong>, ώστε ένας συνάδελφος που προγραμματίζει κάτι να εμφανίζεται χωρίς να το φορτώσετε ξανά &mdash; και περιμένει όσο έχετε ανοιχτό ένα αίτημα ή σύρετε.',
            'cal_month' => '<strong>Προβολή μήνα</strong> &mdash; το κλασικό πλέγμα 6 γραμμών με λωρίδα κεφαλίδας ημερών της εβδομάδας· κάθε κελί ημέρας δείχνει έως τρία αιτήματα σε μορφή ετικέτας με την ώρα έναρξής τους, συν έναν σύνδεσμο <em>+N ακόμη</em> που σας μεταφέρει στην προβολή Ημέρας για εκείνη την ημερομηνία. Η σημερινή ημέρα επισημαίνεται.',
            'cal_week' => '<strong>Προβολή εβδομάδας</strong> &mdash; Δευ&ndash;Κυρ στο πάνω μέρος, πάνω από ένα κάθετο χρονοδιάγραμμα 24 ωρών. Τα αιτήματα εμφανίζονται στην προγραμματισμένη διάρκειά τους, οπότε μια εργασία 15 λεπτών και μια ανακατασκευή ενός απογεύματος φαίνονται διαφορετικά. Ένα ολοήμερο αίτημα εμφανίζεται ως λεπτή μπάρα στην κορυφή της ημέρας του αντί να καταλαμβάνει ολόκληρη τη στήλη. Η στήλη της σημερινής ημέρας επισημαίνεται· η κεφαλίδα των ημερών παραμένει στη θέση της ενώ το πλέγμα των ωρών κυλά.',
            'cal_day' => '<strong>Προβολή ημέρας</strong> &mdash; μία ψηλή στήλη για την επιλεγμένη ημέρα με το ίδιο χρονοδιάγραμμα 24 ωρών. Τα αιτήματα εμφανίζονται ως μεγαλύτερα μπλοκ με <code>ticket_number &mdash; subject</code> και ώρα έναρξης· κάντε κλικ σε ένα για να ανοίξετε τις λεπτομέρειές του ή να αλλάξετε πότε πραγματοποιείται.',
            'rota_heading' => '<strong>Πρόγραμμα βαρδιών προσωπικού</strong>',
            'rota_body' => 'Η σελίδα του προγράμματος βαρδιών επιτρέπει στους υπευθύνους ομάδων και στους προϊσταμένους να προγραμματίζουν τις βάρδιες των τεχνικών στη διάρκεια της εβδομάδας. Ορίστε τυπικό ωράριο εργασίας, αναθέστε περιόδους εφημερίας και σημειώστε αργίες ή απουσίες, ώστε η ομάδα να γνωρίζει πάντα ποιος είναι διαθέσιμος.',
            'rota_step1' => '<strong>Δείτε το πλέγμα του προγράμματος</strong> &mdash; το πρόγραμμα εμφανίζει τους τεχνικούς κατά μήκος του ενός άξονα και τις ημέρες κατά μήκος του άλλου, με μπλοκ βαρδιών που δείχνουν την κάλυψη με μια ματιά.',
            'rota_step2' => '<strong>Προσθέστε ή επεξεργαστείτε βάρδιες</strong> &mdash; κάντε κλικ σε ένα κελί για να αναθέσετε τύπο βάρδιας (π.χ. Πρωινή, Απογευματινή, Νυχτερινή, Εφημερία). Οι αλλαγές αποθηκεύονται αμέσως.',
            'rota_step3' => '<strong>Προγραμματίστε εκ των προτέρων</strong> &mdash; μετακινηθείτε μπροστά ανά εβδομάδα για να φτιάξετε το πρόγραμμα νωρίτερα. Έτσι εξασφαλίζεται επαρκής κάλυψη σε γνωστές περιόδους αιχμής, αργίες ή ημέρες εκπαίδευσης.',
            'rota_step4' => '<strong>Συμπληρώστε πολλά κελιά ταυτόχρονα</strong> &mdash; κάντε <strong>δεξί κλικ</strong> σε ένα κελί και επιλέξτε <em>Αντιγραφή</em> για να πάρετε τη βάρδια που περιέχει, και έπειτα δεξί κλικ σε άλλο και <em>Επικόλληση</em>. Για περισσότερα από ένα κελιά, <strong>σύρετε πάνω από ένα μπλοκ</strong> τους (ή κάντε ctrl-κλικ σε κελιά ένα προς ένα) και επικολλήστε σε όλα. Αν περάσετε το ποντίκι πάνω από μια <strong>επικεφαλίδα ημέρας</strong>, φωτίζεται ολόκληρη η ημέρα, και πάνω από το <strong>όνομα ενός τεχνικού</strong> φωτίζεται ολόκληρη η εβδομάδα του &mdash; κάντε δεξί κλικ σε οποιοδήποτε και επικολλήστε σε όλο το σύνολο. Όταν κάποια από τα κελιά έχουν ήδη βάρδια, το μενού προσφέρει και τους δύο τρόπους με απλά λόγια &mdash; <em>Επικόλληση και στα 7</em> και <em>Επικόλληση σε 6 κενά κελιά</em> &mdash; ώστε να επιλέξετε πριν δεσμευτείτε και όχι μετά. Η αντικατάσταση ζητά επιβεβαίωση και λέει πόσες βάρδιες αντικαθιστά· η συμπλήρωση των κενών γίνεται απλώς, αφού δεν χάνεται τίποτα. Τα ίδια μενού μπορούν επίσης να <strong>εκκαθαρίσουν</strong> μια ημέρα, μια εβδομάδα ή μια επιλογή, πάλι αφού σας πουν πόσες βάρδιες αφαιρούνται.',
            'rota_step5' => '<strong>Αντιγράψτε μια ολόκληρη ημέρα ή μια ολόκληρη εβδομάδα για ένα άτομο</strong> &mdash; κάντε δεξί κλικ σε μια <strong>επικεφαλίδα ημέρας</strong> και επιλέξτε <em>Αντιγραφή</em> για να πάρετε κάθε βάρδια εκείνης της ημέρας, ή στο <strong>όνομα ενός τεχνικού</strong> για να πάρετε ολόκληρη την εβδομάδα του. Η επικόλληση σε άλλη ημέρα ή σε άλλον τεχνικό την κάνει να ταυτίζεται: οι βάρδιες που δεν είχε το αντίγραφο διαγράφονται, ώστε να πάρετε την ημέρα που αντιγράψατε και όχι ένα μείγμα των δύο. Μια ημέρα μπορεί να επικολληθεί μόνο σε άλλη ημέρα και ένας τεχνικός μόνο σε άλλον τεχνικό &mdash; μια ημέρα είναι μία βάρδια <em>ανά άτομο</em> και μια εβδομάδα είναι μία βάρδια <em>ανά ημέρα</em>, οπότε δεν υπάρχει λογικός τρόπος να τοποθετηθεί η μία πάνω στην άλλη. Αν το δοκιμάσετε, το μενού το λέει και λέει πού μπορεί να πάει αντί γι\' αυτό.',
            'rota_step6' => '<strong>Αντιγράψτε μια ολόκληρη εβδομάδα</strong> &mdash; τα <strong>Αντιγραφή εβδομάδας</strong> και <strong>Επικόλληση εβδομάδας</strong> πάνω δεξιά παίρνουν κάθε βάρδια της εβδομάδας που βλέπετε και την αφήνουν σε άλλη, που είναι ο γρηγορότερος τρόπος για να φτιάξετε ένα επαναλαμβανόμενο πρόγραμμα. Η επικόλληση <em>αντικαθιστά</em> την εβδομάδα-στόχο, οπότε η επιβεβαίωση σάς λέει πόσες εγγραφές πρόκειται να αφαιρεθούν. Αγγίζει πάντα μόνο τις ημέρες και τα άτομα που εμφανίζει πραγματικά το πλέγμα.',
            'tip' => 'Συνδυάστε το ημερολόγιο και το πρόγραμμα βαρδιών για αποτελεσματικό σχεδιασμό δυναμικότητας. Αν το ημερολόγιο δείχνει αιχμή αιτημάτων κάθε Δευτέρα πρωί, φροντίστε να υπάρχει έξτρα κάλυψη στο πρόγραμμα για εκείνη τη χρονική θέση.',
        ],
        'settings' => [
            'heading' => 'Ρυθμίσεις',
            'intro' => 'Η σελίδα Ρυθμίσεις είναι το σημείο όπου διαμορφώνετε τα δομικά στοιχεία του συστήματος αιτημάτων. Όλες οι τιμές αναζήτησης, οι στόχοι SLA, η ενσωμάτωση email και τα προσαρμοσμένα πεδία διαχειρίζονται εδώ.',
            'sla_callout_title' => 'Διαχείριση SLA &mdash; πλήρης οδηγός',
            'sla_callout_body' => 'Διαθέσιμες επιλογές, επιχειρησιακά ημερολόγια, καταστάσεις παύσης, ειδοποιήσεις παραβίασης, ρύθμιση cron job, καθώς και πρακτικά παραδείγματα για ομάδες με μία ή περισσότερες ζώνες ώρας. Αρκετά εκτενές ώστε να έχει τη δική του σελίδα.',
            'card_dept_title' => 'Τμήματα',
            'card_dept_body' => 'Δημιουργήστε τμήματα όπως IT, HR και Οικονομικά. Κάθε τμήμα γίνεται φάκελος στα εισερχόμενα και φίλτρο στον πίνακα ελέγχου',
            'card_types_title' => 'Τύποι αιτημάτων',
            'card_types_body' => 'Ορίστε τους τύπους αιτημάτων που διαχειρίζεται η ομάδα σας: Συμβάν, Αίτημα εξυπηρέτησης, Πρόβλημα, Αλλαγή. Οι τύποι βοηθούν τους τεχνικούς να ταξινομούν την εργασία',
            'card_type_rules_title' => 'Τύπος για νέα αιτήματα',
            'card_type_rules_body' => 'Στους Τύπους αιτημάτων, δώστε σε κάθε νέο αίτημα έναν τύπο όταν δεν τον επιλέγει κανείς: μια προεπιλογή και κανόνες πριν από αυτήν - ανάλογα με τον τρόπο άφιξης (email, πύλη, web chat, τηλέφωνο, παρακολούθηση...), το γραμματοκιβώτιο, την προέλευση, το τμήμα, λέξεις στο θέμα ή το domain του αιτούντος. Κερδίζει ο πρώτος κανόνας που ταιριάζει· η Δοκιμή δείχνει ποιον τύπο θα έπαιρνε ένα αίτημα',
            'card_priorities_title' => 'Προτεραιότητες',
            'card_priorities_body' => 'Ορίστε επίπεδα προτεραιότητας με ονόματα, χρώματα και σειρά ταξινόμησης. Κάθε προτεραιότητα συσχετίζεται με έναν στόχο SLA για απόκριση και επίλυση',
            'card_statuses_title' => 'Καταστάσεις',
            'card_statuses_body' => 'Προσαρμόστε τα στάδια του κύκλου ζωής του αιτήματος. Οι προεπιλεγμένες καταστάσεις περιλαμβάνουν Νέο, Ανοιχτό, Σε εξέλιξη, Σε αναμονή, Επιλύθηκε και Κλειστό',
            'card_categories_title' => 'Κατηγορίες',
            'card_categories_body' => 'Ομαδοποιήστε τα αιτήματα ανά τεχνικό τομέα: Υλικό, Λογισμικό, Δίκτυο, Πρόσβαση. Οι κατηγορίες τροφοδοτούν τις αναλύσεις των αναφορών',
            'card_sla_title' => 'Στόχοι SLA',
            'card_sla_body' => 'Ορίστε στόχους χρόνου απόκρισης και επίλυσης ανά προτεραιότητα. Τα χρονόμετρα SLA εμφανίζονται στα αιτήματα και ενεργοποιούν τις προειδοποιήσεις παραβίασης',
            'card_email_title' => 'Εισαγωγή email',
            'card_email_body' => 'Συνδέστε ένα γραμματοκιβώτιο (Exchange, Microsoft 365) για να εισάγονται αυτόματα τα email ως νέα αιτήματα. Οι απαντήσεις προστίθενται στα υπάρχοντα αιτήματα',
            'card_custom_title' => 'Προσαρμοσμένα πεδία',
            'card_custom_body' => 'Προσθέστε δικά σας πεδία στα αιτήματα για δεδομένα που χρειάζεται να καταγράφει ο οργανισμός σας και δεν καλύπτονται από το προεπιλεγμένο σύνολο πεδίων',
            'card_templates_title' => 'Πρότυπα email',
            'card_templates_body' => 'Διαμορφώστε τα πρότυπα ειδοποιήσεων που αποστέλλονται στους τελικούς χρήστες όταν δημιουργούνται, ενημερώνονται ή επιλύονται αιτήματα, ή για την έρευνα CSAT. Ενσωματώστε κωδικούς συγχώνευσης όπως [requester_name] και [csat_link]',
            'card_checklists_title' => 'Λίστες ελέγχου',
            'card_checklists_body' => 'Αποφασίστε τι συμβαίνει όταν κάποιος κλείνει ένα αίτημα που έχει ακόμη εκκρεμή υποχρεωτικά βήματα λίστας ελέγχου: <strong>προειδοποίηση</strong> και καταγραφή εσωτερικής σημείωσης με τα βήματα και το άτομο που το έκλεισε, ή <strong>αποκλεισμός</strong> του κλεισίματος μέχρι να ολοκληρωθούν. Εφαρμόζεται παντού όπου μπορεί να κλείσει ένα αίτημα - συμπεριλαμβανομένων των μαζικών ενεργειών, του REST API και της αυτοματοποίησης ροών εργασιών',
            'card_custom_fields_title' => 'Προσαρμοσμένα πεδία',
            'card_custom_fields_body' => 'Ορίστε τις επιπλέον λεπτομέρειες που χρειάζεται ένα είδος αιτήματος - κείμενο, αριθμό, ημερομηνία, ναι / όχι, αναπτυσσόμενη λίστα με δικές σας επιλογές, διεύθυνση ιστού ή email - και συσχετίστε κάθε πεδίο με ορισμένους τύπους αιτημάτων ή με όλους. Κάθε πεδίο επιλέγει αν πρέπει να συμπληρωθεί <strong>όταν καταχωρείται το αίτημα</strong> (η φόρμα Νέο αίτημα, το REST API και, αν ζητηθεί, η πύλη), <strong>πριν κλείσει</strong> (σύμφωνα με τον κανόνα Υποχρεωτικά πεδία), ή και τα δύο, καθώς και αν ο <strong>αιτών ερωτάται</strong> για αυτό στην πύλη - όπου εμφανίζεται επιλογέας τύπου αιτήματος μόλις αυτός αλλάζει τι ζητείται. Οι απαντήσεις εμφανίζονται στον πίνακα ιδιοτήτων του αιτήματος και στο ιστορικό του. Η αλλαγή του τύπου ενός αιτήματος αποκρύπτει τις απαντήσεις που δεν έχει ο νέος τύπος και δεν τις διαγράφει ποτέ. Η ίδια καρτέλα περιέχει το <strong>πεδίο Τμήμα</strong>: αποκρύψτε το όπου δεν χρησιμοποιούνται τμήματα και επιλέξτε το τμήμα στο οποίο ξεκινούν τα νέα αιτήματα, ανά εταιρεία. Η απόκρυψη δεν αφαιρεί ποτέ ένα τμήμα από ένα αίτημα ούτε την πρόσβαση κάποιου σε αυτό.',
            'card_mandatory_title' => 'Υποχρεωτικά πεδία',
            'card_mandatory_body' => 'Επιλέξτε τα πεδία που πρέπει να συμπληρωθούν πριν κλείσει ένα αίτημα - κατηγορία, κωδικός επίλυσης, υπεύθυνος κ.ο.κ. Στη συνέχεια επιλέξτε τι συμβαίνει όταν κάποιος κλείνει ένα αίτημα με κενό πεδίο: <strong>προειδοποίηση</strong>, <strong>προειδοποίηση και email</strong> σε κάποιον, όπως έναν υπεύθυνο παροχής υπηρεσιών, ή <strong>άρνηση</strong> του κλεισίματος. Ένας ξεχωριστός διακόπτης το καταγράφει στο αίτημα ως εσωτερική σημείωση. Ένα πεδίο που είναι απενεργοποιημένο για μια εταιρεία δεν απαιτείται ποτέ και η συγχώνευση αιτημάτων δεν το ενεργοποιεί ποτέ. Εφαρμόζεται παντού όπου μπορεί να κλείσει ένα αίτημα - συμπεριλαμβανομένων των μαζικών ενεργειών, του REST API και της αυτοματοποίησης ροών εργασιών',
            'card_cleanup_title' => 'Reply Cleanup AI',
            'card_cleanup_body' => 'Κλειδί Anthropic + μοντέλο + ύφος για το κουμπί ✨ Cleanup στον επεξεργαστή απαντήσεων. Ξεχωριστό κλειδί από τις άλλες λειτουργίες AI για αναλυτική χρέωση',
            'card_csat_title' => 'CSAT',
            'card_csat_body' => 'Τρόπος αποστολής (ανενεργή / αυτόματη / χειροκίνητη), καθυστέρηση, προστασία ενός ανά αίτημα, κλίμακα (αστέρια ή emoji). Δείτε την ενότητα 6 για την πλήρη ροή',
            'email_heading' => '<strong>Η εισαγωγή email αναλυτικά</strong>',
            'email_body' => 'Η λειτουργία εισαγωγής email συνδέεται με το κοινόχρηστο γραμματοκιβώτιό σας και εισάγει τα νέα μηνύματα ως αιτήματα. Όταν ένας τελικός χρήστης στέλνει email στη διεύθυνση υποστήριξής σας (π.χ. support@yourcompany.com), το FreeITSM δημιουργεί ένα αίτημα με το θέμα του email ως τίτλο και το σώμα του email ως περιγραφή. Αν ο αποστολέας απαντήσει σε ένα email ειδοποίησης, η απάντηση προστίθεται στο υπάρχον αίτημα αντί να δημιουργηθεί διπλότυπο.',
            'email_step1' => '<strong>Διαμορφώστε το γραμματοκιβώτιο</strong> &mdash; μεταβείτε στις Ρυθμίσεις &rarr; Γραμματοκιβώτια και προσθέστε ένα: Microsoft 365 ή Google, που συνδέονται με OAuth και δεν αποθηκεύουν κωδικό πρόσβασης, ή <strong>Basic IMAP / SMTP</strong> για οποιονδήποτε άλλο διακομιστή αλληλογραφίας, με όνομα χρήστη και κωδικό πρόσβασης και χωρίς τίποτα προς εγκατάσταση. Το <strong>Test</strong> σας στέλνει ένα σύντομο email μέσω του γραμματοκιβωτίου, με τον τρόπο που φεύγει μια απάντηση, και το <strong>Verify</strong> ελέγχει τον φάκελο.',
            'email_step2' => '<strong>Ορίστε το διάστημα ελέγχου</strong> &mdash; επιλέξτε πόσο συχνά ελέγχει το FreeITSM το γραμματοκιβώτιο για νέα μηνύματα. Τα μικρότερα διαστήματα σημαίνουν ταχύτερη δημιουργία αιτημάτων.',
            'email_step3' => '<strong>Ορίστε προεπιλογές</strong> &mdash; ορίστε το προεπιλεγμένο τμήμα, τύπο και προτεραιότητα για τα αιτήματα που δημιουργούνται από email. Οι τεχνικοί μπορούν να τα προσαρμόσουν μετά την εισαγωγή.',
            'email_thread_note' => '<strong>Μια απάντηση χωρίς αριθμό αιτήματος</strong> &mdash; κάθε email που στέλνει το FreeITSM φέρει τον αριθμό του αιτήματος, επομένως μια απάντηση σε αυτό βρίσκει πάντα το αίτημά της. Όταν κάποιος απαντά στο <em>δικό του</em> πρώτο email (για να προσθέσει, ας πούμε, ένα συνημμένο που ξέχασε), δεν υπάρχει αριθμός να βρεθεί και, από προεπιλογή, η απάντηση αυτή ανοίγει νέο αίτημα. Ορίστε το Αιτήματα &rarr; Ρυθμίσεις &rarr; Γενικά &rarr; <strong>Απάντηση χωρίς αριθμό αιτήματος</strong> σε <strong>Προστίθεται στο αίτημα στο οποίο ανήκει η συζήτηση</strong> και θα προστεθεί στο αίτημα που άνοιξε εκείνο το πρώτο email, ανοίγοντάς το ξανά αν ήταν κλειστό (όταν η επαναφορά είναι ενεργή). Αντιστοιχίζονται μόνο email του ίδιου γραμματοκιβωτίου.',
            'email_reply_to_note' => '<strong>Σε ποιον απευθύνεται η Απάντηση</strong> &mdash; από προεπιλογή, το πλαίσιο Απάντησης απευθύνεται στο άτομο του μηνύματος που διαβάζετε. Αν συνάδελφοι του αιτούντος μπαίνουν στη συζήτηση και προτιμάτε να απαντάτε πάντα στον αιτούντα, ορίστε το Αιτήματα &rarr; Ρυθμίσεις &rarr; Γενικά &rarr; <strong>Η απάντηση πηγαίνει σε</strong> σε <strong>Τον αιτούντα του αιτήματος</strong>. Μπορείτε πάντα να αλλάξετε τη διεύθυνση πριν από την αποστολή.',
            'email_sent_copy_note' => '<strong>Αντίγραφο των απεσταλμένων στον φάκελο Απεσταλμένα (Basic IMAP)</strong> - ένα γραμματοκιβώτιο Basic IMAP στέλνει μέσω SMTP, που δεν κρατά αντίγραφο, οπότε όποιος διαβάζει το ίδιο γραμματοκιβώτιο στο Thunderbird ή σε webmail δεν βλέπει τι έστειλε η υποστήριξη. Επεξεργαστείτε το γραμματοκιβώτιο και ενεργοποιήστε την <strong>Αποθήκευση αντιγράφου των απεσταλμένων</strong>, ακριβώς κάτω από τη <em>Χρήση της σύνδεσης IMAP για την αποστολή</em>: κάθε απάντηση, email προτύπου, email ροής εργασιών και email συστήματος που στέλνει μπαίνει τότε και στον φάκελο απεσταλμένων του, σημειωμένο ως αναγνωσμένο. Οι εσωτερικές ειδοποιήσεις προς τους τεχνικούς δεν αρχειοθετούνται ποτέ. Αφήστε κενό τον <strong>Φάκελο απεσταλμένων</strong> για να χρησιμοποιηθεί ο φάκελος που ο διακομιστής αλληλογραφίας σας ορίζει ως Απεσταλμένα, ή πληκτρολογήστε το όνομά του. Αφήστε τον διακόπτη απενεργοποιημένο αν ο διακομιστής σας ήδη αρχειοθετεί τα απεσταλμένα (το Gmail και το Microsoft 365 το κάνουν, όπως και ορισμένες εταιρείες φιλοξενίας) - θα είχατε δύο αντίγραφα. Η <strong>Δοκιμή</strong> δείχνει σε ποιον φάκελο πήγε το αντίγραφο. Αν ένα αντίγραφο δεν μπορεί να αποθηκευτεί, το email έχει σταλεί κανονικά, και ο λόγος εμφανίζεται στη <strong>Δραστηριότητα</strong> του γραμματοκιβωτίου &rarr; καρτέλα <strong>Εξερχόμενα</strong> ως <em>Copy to Sent folder</em>.',
            'tip' => 'Χρησιμοποιήστε τα πρότυπα email για να διατηρείτε επαγγελματικό και συνεπές ύφος σε όλες τις επικοινωνίες με τους τελικούς χρήστες. Τα πρότυπα υποστηρίζουν δυναμικούς δεσμευτές θέσης για την αναφορά αιτήματος, το όνομα του αιτούντος, το όνομα του τεχνικού και την κατάσταση.',
            'closemsg_heading' => '<strong>Ένα εφάπαξ μήνυμα όταν κλείνετε ένα αίτημα</strong>',
            'closemsg_body' => 'Τοποθετήστε το <code>[ticket_closed_message]</code> οπουδήποτε σε ένα ενεργό πρότυπο <strong>Ticket closed</strong> και, από τότε, όταν ένα αίτημα τίθεται σε κατάσταση κλεισίματος, ο τεχνικός θα ερωτάται για μία πρόταση - <em>&ldquo;ο εφεδρικός φορτιστής είναι στο γραφείο σας&rdquo;</em>, <em>&ldquo;κλείνει όπως συμφωνήθηκε τηλεφωνικά&rdquo;</em>. Ό,τι πληκτρολογήσει καταλήγει ακριβώς εκεί που βάλατε τον δεσμευτή θέσης, ώστε να ελέγχετε εσείς τη διατύπωση γύρω από αυτόν. Δεν είναι ρύθμιση και δεν το αποθηκεύει τίποτα: μία σημείωση, ένα αίτημα, ένα email. Αν δεν πληκτρολογηθεί τίποτα, η γραμμή απλώς δεν υπάρχει - χωρίς κενό, χωρίς περιττή στίξη.',
            'closemsg_note' => '<strong>Η προτροπή εμφανίζεται μόνο όταν ο δεσμευτής θέσης υπάρχει πράγματι στο πρότυπο.</strong> Χωρίς αυτόν, ό,τι πληκτρολογούσε ένας τεχνικός θα χανόταν αθόρυβα και κάθε ομάδα που δεν το θέλει θα έχανε ένα κλικ σε κάθε κλείσιμο. Έτσι ενεργοποιείται από μόνο του όταν το διαμορφώνετε και μένει στην άκρη όταν δεν το έχετε κάνει.',
            'cat_heading' => '<strong>Κατηγορίες και τα δύο πεδία δίπλα τους</strong>',
            'cat_body' => 'Ο <em>τύπος</em> ενός αιτήματος λέει τι είδους πράγμα είναι· η <em>κατηγορία</em> λέει για ποιο θέμα πρόκειται. Δημιουργήστε τη λίστα στις <strong>Ρυθμίσεις &rarr; Κατηγορίες</strong>, μαζί με τους διακόπτες που αποφασίζουν αν θα εμφανίζεται καθόλου κάτι από αυτά σε ένα αίτημα.',
            'cat_card_one_title' => 'Κατηγορία',
            'cat_card_one_body' => 'Ως τι αναφέρθηκε το αίτημα, επιλέγεται κατά τη δημιουργία του. Ένα αίτημα φέρει ακριβώς μία, ώστε μια αναφορά των κατηγοριών σας να αθροίζει πάντα στον αριθμό των αιτημάτων που είχατε πραγματικά.',
            'cat_card_close_title' => 'Κατηγορία κατά το κλείσιμο',
            'cat_card_close_body' => 'Η ίδια λίστα ζητείται ξανά όταν ολοκληρώνεται το αίτημα. Συνήθως ο τεχνικός απλώς την επιβεβαιώνει &mdash; αξίζει τον κόπο στα αιτήματα όπου η πρώτη εκτίμηση ήταν λάθος, κι έτσι ανακαλύπτετε ότι δώδεκα από τα τριάντα επτά «προβλήματα εκτυπωτή» ήταν στην πραγματικότητα το δίκτυο.',
            'cat_card_res_title' => 'Κωδικός επίλυσης',
            'cat_card_res_body' => 'Πώς τελείωσε το αίτημα και όχι για τι ήταν &mdash; «Επιδιορθώθηκε εξ αποστάσεως», «Δόθηκε εκπαίδευση», «Δεν βρέθηκε βλάβη». Δέκα λογικοί κωδικοί υπάρχουν εξαρχής και μπορείτε να τους αλλάξετε όλους.',
            'cat_rule_off' => '<strong>Και τα τρία ξεκινούν απενεργοποιημένα.</strong> Δημιουργήστε πρώτα τη λίστα σας και μετά ενεργοποιήστε όσα θέλετε. Καθένα μπορεί να οριστεί διαφορετικά για κάθε εταιρεία.',
            'cat_rule_levels' => 'Οι κατηγορίες μπορούν να έχουν υποκατηγορίες έως και τρία επίπεδα βάθος και κανένα επίπεδο δεν είναι υποχρεωτικό.',
            'cat_rule_type' => 'Μια κατηγορία μπορεί να συνδεθεί με έναν τύπο αιτήματος, ώστε π.χ. η «Ένταξη χρήστη» να προσφέρεται μόνο σε ένα αίτημα εξυπηρέτησης. Η σύνδεση ανήκει στην κατηγορία ανώτατου επιπέδου και οι υποκατηγορίες της την ακολουθούν.',
            'cat_rule_typechange' => '<strong>Η αλλαγή του τύπου ενός αιτήματος καθαρίζει μια κατηγορία που ανήκε στον παλιό τύπο</strong> και το αναφέρει στην οθόνη. Μια κατηγορία που δεν συνδέεται με κανέναν τύπο διατηρείται μετά την αλλαγή.',
            'cat_rule_portal' => 'Επιλέξτε <em>Οι πελάτες μπορούν να την επιλέξουν</em> για να προσφέρεται μια κατηγορία στην πύλη αυτοεξυπηρέτησης. Οι αιτούντες βλέπουν μια σύντομη λίστα σε απλά ελληνικά, ενώ οι τεχνικοί βλέπουν ολόκληρο το δέντρο.',
            'cat_rule_retire' => 'Απενεργοποιήστε μια κατηγορία για να την αποσύρετε &mdash; παραμένει στα αιτήματα που την έχουν ήδη και παύει να προσφέρεται στα νέα. Αυτό είναι σχεδόν πάντα καλύτερο από τη διαγραφή, η οποία απορρίπτεται όσο κάτι τη χρησιμοποιεί ακόμη.',
            'cat_rule_report' => 'Και τα τρία μπορούν να απεικονιστούν σε γράφημα στον πίνακα ελέγχου αιτημάτων. Τα δύο γραφήματα κατηγοριών συγκεντρώνονται στο ανώτατο επίπεδο και τα αιτήματα χωρίς καμία τιμή μετριούνται ως <em>Χωρίς κατηγορία</em> αντί να αποκρύπτονται.',
            'cat_tip' => 'Αν δεν είστε σίγουροι από πού να ξεκινήσετε, αφήστε τις κατηγορίες κενές και ενεργοποιήστε μόνο τον <strong>Κωδικό επίλυσης</strong>. Είναι το πεδίο που αλλάζει πιο γρήγορα αυτό που κάνετε &mdash; όταν ένα πέμπτο των αιτημάτων σας επιστρέφει ως «Δόθηκε εκπαίδευση», πρόκειται για πρόβλημα τεκμηρίωσης και όχι για πρόβλημα IT.',
        ],
        'tips' => [
            'heading' => 'Γρήγορες συμβουλές',
            'search_title' => 'Αναζήτηση σε όλα',
            'search_body' => 'Το παράθυρο αναζήτησης ελέγχει αναφορές αιτημάτων, θέματα, ονόματα αιτούντων και διευθύνσεις email. Χρησιμοποιήστε το για να βρείτε γρήγορα σχετικά αιτήματα όταν ένας χρήστης τηλεφωνεί για ένα υπάρχον ζήτημα.',
            'sla_title' => 'Παρακολουθήστε τα SLA σας',
            'sla_body' => 'Τα χρονόμετρα SLA φαίνονται σε κάθε αίτημα στο παράθυρο ανάγνωσης. Οι ενδείξεις με χρώμα γίνονται πορτοκαλί όταν πλησιάζει παραβίαση και κόκκινες όταν ο στόχος δεν επιτεύχθηκε, ώστε να ιεραρχήσετε ανάλογα.',
            'reply_title' => 'Απάντηση από τα εισερχόμενα',
            'reply_body' => 'Δεν χρειάζεται να ανοίξετε το πρόγραμμα email σας για να απαντήσετε σε έναν τελικό χρήστη. Χρησιμοποιήστε το κουμπί Απάντηση στο παράθυρο ανάγνωσης για να στείλετε μήνυμα απευθείας. Προστίθεται αυτόματα στο αίτημα.',
            'reply_to_title' => 'Σε ποιον πηγαίνει η Απάντηση',
            'reply_to_body' => 'Η Απάντηση απευθύνεται στο άτομο του μηνύματος που διαβάζετε. Αν προτιμάτε να πηγαίνει πάντα στον αιτούντα του αιτήματος, αλλάξτε το <strong>Η απάντηση πηγαίνει σε</strong> στο Αιτήματα &rarr; Ρυθμίσεις &rarr; Γενικά. Σε κάθε περίπτωση μπορείτε να αλλάξετε τη διεύθυνση ή να προσθέσετε άτομα στο Κοιν. πριν από την αποστολή.',
            'trail_title' => 'Χρησιμοποιήστε το ίχνος δραστηριότητας',
            'trail_body' => 'Πριν εργαστείτε σε ένα αίτημα, κάντε κύλιση στο ίχνος δραστηριότητάς του. Οι προηγούμενες σημειώσεις τεχνικών, τα email και οι αλλαγές πεδίων σάς δίνουν το πλήρες πλαίσιο, ώστε να μη ζητάτε από τον χρήστη να επαναλάβει πληροφορίες.',
            'dash_title' => 'Πίνακας ελέγχου για προϊσταμένους',
            'dash_body' => 'Δημιουργήστε έναν πίνακα ελέγχου με γραφικά στοιχεία για ποσοστά συμμόρφωσης SLA, μέσο χρόνο επίλυσης και αιτήματα ανά τμήμα. Μοιραστείτε τον στις συναντήσεις της ομάδας για να προωθήσετε τη διαρκή βελτίωση.',
            'rota_title' => 'Σχεδιάστε με το πρόγραμμα βαρδιών',
            'rota_body' => 'Συμπληρώστε το πρόγραμμα βαρδιών τουλάχιστον δύο εβδομάδες νωρίτερα. Σε συνδυασμό με την προβολή ημερολογίου, σας βοηθά να εντοπίζετε κενά κάλυψης πριν γίνουν πρόβλημα για τους χρόνους απόκρισης.',
            'drag_title' => 'Σύρετε για διαλογή',
            'drag_body' => 'Σύρετε αιτήματα από τη λίστα πάνω σε φακέλους για να τα ενημερώσετε χωρίς να τα ανοίξετε. Οι υποφάκελοι τμήματος + κατάστασης ενημερώνουν και τα δύο ταυτόχρονα. Η αυτόματη επέκταση φακέλων κάνει προσβάσιμες τις εμφωλευμένες καταστάσεις εν ώρα σύρσιμου.',
            'dbl_title' => 'Διπλό κλικ για πλήρη οθόνη',
            'dbl_body' => 'Το απλό κλικ δείχνει προεπισκόπηση ενός αιτήματος στο παράθυρο ανάγνωσης· το διπλό κλικ το ανοίγει σε λειτουργία πλήρους οθόνης για συγκεντρωμένη εργασία. Πατήστε το εικονίδιο μεγιστοποίησης δίπλα στο θέμα για να επιστρέψετε.',
            'rightclick_title' => 'Δεξί κλικ για γρήγορες ενέργειες',
            'rightclick_body' => 'Κάντε δεξί κλικ σε οποιοδήποτε αίτημα για αλλαγή κατάστασης, προτεραιότητας ή υπευθύνου με ένα κλικ, καθώς και για σύνδεση με CMDB και καταγραφή χρόνου, χωρίς να φύγετε από το αίτημα που διαβάζετε.',
            'ai_title' => 'Αφήστε το AI να καθαρίσει την απάντησή σας',
            'ai_body' => 'Πληκτρολογήστε ένα πρόχειρο (ή απλώς κουκκίδες) και πατήστε <strong>✨ Cleanup</strong> &mdash; το Claude το ξαναγράφει ως κανονικό email με χαιρετισμό, διορθώσεις γραμματικής και κατακλείδα. Ο σύνδεσμος Αναίρεση εμφανίζεται για 30 δευτερόλεπτα.',
            'feedback_title' => 'Ζητήστε ανατροφοδότηση',
            'feedback_body' => 'Ενεργοποιήστε το CSAT στις <strong>Ρυθμίσεις &rarr; CSAT</strong> για αυτόματη έρευνα προς τους αιτούντες όταν κλείνουν τα αιτήματά τους. Οι τάσεις ανά τεχνικό βρίσκονται στο <code>tickets/csat/</code> &mdash; χρυσός για συζητήσεις ανάπτυξης.',
            'precreate_title' => 'Δημιουργήστε εκ των προτέρων τελικούς χρήστες',
            'precreate_body' => 'Το κουμπί πλοήγησης <strong>Χρήστες</strong> σάς επιτρέπει να προσθέσετε έναν χρήστη πριν χρειαστεί να καταχωρίσει αίτημα &mdash; αφήστε τον κωδικό πρόσβασης κενό και μπορεί να διεκδικήσει μόνος του τον λογαριασμό μέσω της πύλης αυτοεξυπηρέτησης.',
        ],
        'companies' => [
            'heading' => 'Εταιρείες &amp; δρομολόγηση email',
            'intro' => 'Όταν η εγκατάστασή σας εξυπηρετεί περισσότερες από μία εταιρείες (για παράδειγμα ένας πάροχος IT που υποστηρίζει διάφορους πελάτες), τα αιτήματα κάθε εταιρείας διατηρούνται χωριστά. Αυτή η ενότητα εξηγεί πώς τα εισερχόμενα email βρίσκουν τη σωστή εταιρεία.',
            'switcher_body' => 'Ένας <strong>εναλλάκτης εταιρείας</strong> εμφανίζεται στην κεφαλίδα. Ορίζει την εταιρεία στην οποία εργάζεστε &mdash; η λίστα αιτημάτων, οι φάκελοι και οι μετρητές δείχνουν μόνο αυτήν, και κάθε αίτημα που δημιουργείτε καταχωρείται σε αυτήν. Το προσωπικό με πρόσβαση σε περισσότερες εταιρείες μπορεί να εναλλάσσεται μεταξύ τους· η τρέχουσα εμφανίζεται πάντα, ώστε να μην απαντήσετε σε λάθος πλαίσιο. Διαχειριστείτε τις ίδιες τις εταιρείες στο <strong>Σύστημα &rarr; Εταιρείες</strong>.',
            'mailboxes_heading' => 'Κάθε γραμματοκιβώτιο είναι ενός από δύο ειδών &mdash; αυτό καθορίζει τη δρομολόγηση:',
            'card_pinned_title' => 'Καρφιτσωμένο γραμματοκιβώτιο',
            'card_pinned_body' => 'Αφιερωμένο σε μία εταιρεία (π.χ. το δικό του <code>itsupport@</code> ενός πελάτη). <strong>Όλη</strong> η αλληλογραφία του καταχωρείται σε αυτήν την εταιρεία &mdash; ο αποστολέας αγνοείται &mdash; και οι απαντήσεις φεύγουν από αυτό, ώστε ο πελάτης να βλέπει το δικό του help desk από άκρο σε άκρο.',
            'card_shared_title' => 'Κοινόχρηστο γραμματοκιβώτιο υποδοχής',
            'card_shared_body' => 'Μία διεύθυνση που εξυπηρετεί πολλές εταιρείες (π.χ. το μοναδικό <code>support@theprovider.com</code> ενός παρόχου). Δεν μπορεί να γνωρίζει την εταιρεία μόνο από τη διεύθυνση, γι\' αυτό την εντοπίζει από <strong>τον αποστολέα του email</strong>. Η προτεινόμενη ρύθμιση για πάροχο με πολλούς πελάτες.',
            'routing_heading' => 'Πώς ένα κοινόχρηστο γραμματοκιβώτιο υποδοχής επιλέγει την εταιρεία',
            'routing_body' => 'Για κάθε εισερχόμενο email δοκιμάζει τα παρακάτω με τη σειρά και κερδίζει η πρώτη αντιστοίχιση:',
            'flow_reply' => 'Απάντηση σε αίτημα',
            'flow_sender' => 'Γνωστός αποστολέας',
            'flow_domain' => 'Γνωστό domain',
            'flow_triage' => 'Διαλογή',
            'rule_reply' => '<strong>1. Απάντηση σε υπάρχον αίτημα</strong> &mdash; αναγνωρίζεται από την αναφορά του, το email προστίθεται σε εκείνο το αίτημα και διατηρεί την εταιρεία του.',
            'rule_sender' => '<strong>2. Συγκεκριμένη διεύθυνση αποστολέα</strong> που αντιστοιχίζεται σε μια εταιρεία (π.χ. <code>jane@gmail.com</code> &rarr; Acme) &mdash; αυτή η εταιρεία. Ελέγχεται πριν από το domain, ώστε να λειτουργεί ακόμη και για προσωπικές διευθύνσεις/webmail.',
            'rule_domain' => '<strong>3. Το domain του αποστολέα</strong> που αντιστοιχίζεται σε μια εταιρεία (π.χ. οποιοσδήποτε <code>@acme.com</code> &rarr; Acme) &mdash; αυτή η εταιρεία.',
            'rule_triage' => '<strong>4. Καμία αντιστοίχιση</strong> &mdash; το email πηγαίνει στην ουρά <strong>διαλογής</strong> αντί να χαθεί (δείτε παρακάτω).',
            'keys_heading' => 'Domains &amp; συγκεκριμένοι αποστολείς (ορίζονται ανά εταιρεία στο Σύστημα &rarr; Εταιρείες)',
            'keys_body' => 'Αυτά είναι τα κλειδιά με τα οποία αντιστοιχίζει ένα κοινόχρηστο γραμματοκιβώτιο υποδοχής. Κάθε εταιρεία δηλώνει τα domain email που της ανήκουν και, προαιρετικά, μεμονωμένες διευθύνσεις αποστολέων.',
            'card_domains_title' => 'Domain email',
            'card_domains_body' => 'Τα domain που κατέχει μια εταιρεία (acme.com, acme.co.uk). Οποιοσδήποτε αποστολέας σε καταχωρισμένο domain δρομολογείται σε αυτήν την εταιρεία. Ένα domain ανήκει μόνο σε μία εταιρεία.',
            'card_senders_title' => 'Συγκεκριμένοι αποστολείς',
            'card_senders_body' => 'Μεμονωμένες διευθύνσεις που αντιστοιχίζονται σε μια εταιρεία και ελέγχονται πριν από το domain. Χρησιμοποιήστε το για έναν ελεύθερο επαγγελματία ή μικρό πελάτη που στέλνει email από προσωπική διεύθυνση.',
            'card_public_title' => 'Δημόσιοι πάροχοι',
            'card_public_body' => 'Το Gmail, το Outlook, το Yahoo και τα παρόμοια δεν μπορούν να αντιστοιχιστούν ως domain (πολλά άσχετα άτομα τα μοιράζονται) &mdash; αντιστοιχίστε αντί γι\' αυτό την ακριβή διεύθυνση ως συγκεκριμένο αποστολέα.',
            'triage_heading' => 'Η ουρά διαλογής &mdash; το δίχτυ ασφαλείας',
            'triage_body' => 'Όταν ένα email σε κοινόχρηστο γραμματοκιβώτιο υποδοχής δεν ταιριάζει με καμία εταιρεία, καταλήγει στη <strong>Διαλογή</strong> (προσβάσιμη από τον εναλλάκτη εταιρείας, με ζωντανό μετρητή) αντί να χαθεί. Κάθε στοιχείο δείχνει τον αποστολέα, το domain, το θέμα και σε ποιο γραμματοκιβώτιο έφτασε. Καταχωρήστε το σε μια εταιρεία με ένα βήμα:',
            'triage_create' => 'Επιλέξτε μια υπάρχουσα εταιρεία ή δημιουργήστε μια νέα επιτόπου.',
            'triage_assign' => 'Για ένα κανονικό domain, προαιρετικά <strong>δρομολογήστε αυτό το domain</strong> στην εταιρεία· για δημόσια/webmail διεύθυνση, προαιρετικά <strong>καταχωρείτε πάντα αυτόν τον αποστολέα</strong> εκεί.',
            'triage_sweep' => 'Και οι δύο επιλογές <em>σαρώνουν</em>: μετακινούν και όλα τα άλλα email στην ουρά από αυτό το domain ή τη διεύθυνση και δρομολογούν αυτόματα τη μελλοντική αλληλογραφία &mdash; έτσι ταξινομείτε έναν αποστολέα μόνο μία φορά.',
            'triage_tip' => 'Τίποτα δεν χάνεται ποτέ. Η αλληλογραφία χωρίς αντιστοίχιση περιμένει στη διαλογή μέχρι να την καταχωρήσει κάποιος· ένα μη καταχωρισμένο αίτημα εμφανίζεται στο μεταξύ στην προεπιλεγμένη εταιρεία.',
            'test_heading' => 'Δοκιμάστε τη δρομολόγησή σας πριν τεθεί σε λειτουργία',
            'test_body' => 'Στο <strong>Σύστημα &rarr; Δοκιμή δρομολόγησης email</strong> μπορείτε να προσομοιώσετε την άφιξη ενός email &mdash; επιλέξτε γραμματοκιβώτιο, πληκτρολογήστε διεύθυνση αποστολέα &mdash; και να δείτε ακριβώς σε ποια εταιρεία θα κατέληγε το νέο αίτημα (ή ότι θα πήγαινε στη διαλογή) και ποιος κανόνας το αποφάσισε. Δεν δημιουργεί τίποτα· απλώς διαβάζει τις ρυθμίσεις σας.',
            'settings_heading' => 'Ρυθμίσεις: κοινές από προεπιλογή, προσαρμοσμένες όπου έχει σημασία',
            'settings_body' => 'Ορισμένες από αυτές τις Ρυθμίσεις μπορούν να <strong>προσαρμοστούν ανά εταιρεία</strong>· άλλες μένουν κοινές σκόπιμα. Όπου μια ρύθμιση είναι απλή λίστα επιλογών &mdash; όπως οι <strong>τύποι αιτημάτων</strong> και οι <strong>προελεύσεις</strong> &mdash; μεταβείτε στο πλαίσιο μιας εταιρείας και θα δείτε τις κοινές προεπιλογές (καθεμία με εικονίδιο ματιού για να αποκρύψετε όσες δεν χρησιμοποιεί) συν όσες έχει προσθέσει μόνο για τον εαυτό της. Δεν μπορείτε να αποκρύψετε ή να διαγράψετε μια επιλογή όσο ανοιχτά αιτήματα τη χρησιμοποιούν και οι ίδιες οι κοινές προεπιλογές επεξεργάζονται από την εταιρεία MSP / προεπιλογής.',
            'settings_custom_title' => 'Προσαρμοσμένες ανά εταιρεία',
            'settings_custom_body' => 'Τύποι αιτημάτων &amp; προελεύσεις (τώρα), και κατηγορίες, SLA &amp; ώρες λειτουργίας (σύντομα) &mdash; πράγματα που πραγματικά διαφέρουν από πελάτη σε πελάτη.',
            'settings_global_title' => 'Κοινές για όλες τις εταιρείες',
            'settings_global_body' => 'Οι καταστάσεις και οι προτεραιότητες παραμένουν ίδιες παντού, ώστε οι αναφορές και τα SLA μεταξύ εταιρειών να παραμένουν συνεπή· το ίδιο ισχύει για τις ομάδες, το πρόγραμμα βαρδιών και τα γραμματοκιβώτιά σας &mdash; τη δική σας λειτουργία και όχι αυτή ενός πελάτη.',
            'allview_heading' => '<strong>Ένας πίνακας για όλες τις εταιρείες</strong>',
            'allview_body' => 'Ο εναλλάκτης εταιρείας στην κεφαλίδα έχει την επιλογή <strong>Όλες οι εταιρείες</strong>. Κάθε αίτημα που επιτρέπεται να δείτε εμφανίζεται σε μία λίστα, με κάθε γραμμή να φέρει την εταιρεία στην οποία ανήκει &mdash; χρήσιμο όταν υποστηρίζετε διάφορες οντότητες και θέλετε μία συνολική εικόνα της ημέρας χωρίς να χάνετε τον έλεγχο του τι ανήκει σε ποιον.',
            'allview_card_scope_title' => 'Δεν παραχωρεί τίποτα νέο',
            'allview_card_scope_body' => 'Το «Όλες» σημαίνει κάθε εταιρεία που ήδη μπορούσατε να προσεγγίσετε μία-μία. Ένας τεχνικός που υποστηρίζει δύο από τις τρεις οντότητές σας βλέπει ακριβώς αυτές τις δύο και ένας τεχνικός με μία εταιρεία βλέπει μια προβολή αυτής της μίας εταιρείας.',
            'allview_card_props_title' => 'Κάθε οντότητα παραμένει χωριστή',
            'allview_card_props_body' => 'Ανοίξτε ένα αίτημα και οι λίστες τύπου, προέλευσης, κατηγορίας και επίλυσής του είναι αυτές που ανήκουν σε <em>εκείνη</em> την εταιρεία &mdash; έτσι μια κατηγορία που έχει η μία οντότητα και η άλλη όχι δεν μπορεί ποτέ να εφαρμοστεί σε λάθος αίτημα.',
            'allview_card_new_title' => 'Τα νέα αιτήματα ρωτούν ποια εταιρεία',
            'allview_card_new_body' => 'Δεν υπάρχει μία ενεργή εταιρεία που να θεωρηθεί δεδομένη και η επιλογή καθορίζει τον αριθμό του αιτήματος, το γραμματοκιβώτιο από το οποίο φεύγουν οι απαντήσεις και το SLA που ισχύει. Η λίστα τύπων συμπληρώνεται μόλις κάνετε την επιλογή.',
            'allview_rule_chip' => 'Ένα αίτημα που έφτασε με email ή από την πύλη χωρίς να έχει ακόμη δρομολογηθεί επισημαίνεται ως <strong>Αδρομολόγητο</strong> αντί να εμφανίζεται κάτω από την Προεπιλογή, ώστε να ξεχωρίζει για διαλογή.',
            'allview_rule_reply' => 'Οι απαντήσεις εξακολουθούν να φεύγουν από το γραμματοκιβώτιο στο οποίο έφτασε το αίτημα &mdash; αυτό ακολουθεί το αίτημα και όχι την προβολή, ώστε ένας συνδυασμένος πίνακας να μην μπορεί να στείλει από λάθος διεύθυνση.',
            'allview_rule_knowledge' => 'Το <strong>Ask AI</strong> αναζητά σε κάθε εταιρεία που βλέπετε όσο είναι ενεργή η συνδυασμένη προβολή, αντί για μία μόνο. Τα άρθρα που μοιράζονται με όλες τις εταιρείες περιλαμβάνονται σε κάθε περίπτωση.',
            'allview_rule_trash' => '<strong>Το άδειασμα του κάδου δεν εκτείνεται ποτέ σε περισσότερες εταιρείες.</strong> Εφαρμόζεται πάντα στη μία εταιρεία που επιλέξατε τελευταία, επειδή το «διαγραφή όλων στον κάδο» σε πολλές οντότητες ταυτόχρονα δεν είναι αυτό που εννοεί κανείς.',
            'allview_rule_other' => 'Διευρύνεται μόνο η λίστα αιτημάτων. Τα πάγια, οι αλλαγές, οι εργασίες και το CMDB εξακολουθούν να εμφανίζουν μία εταιρεία κάθε φορά &mdash; μεταβείτε σε εκείνη την εταιρεία για να εργαστείτε σε αυτά.',
            'privacy_heading' => 'Τα αιτήματα κάθε εταιρείας παραμένουν ιδιωτικά',
            'privacy_body' => 'Όταν εργάζεστε στο πλαίσιο μιας εταιρείας βλέπετε πάντα μόνο τα αιτήματα <strong>εκείνης</strong> της εταιρείας &mdash; στη λίστα, στην αναζήτηση, στους πίνακες ελέγχου και σε κάθε αίτημα που ανοίγετε (συμπεριλαμβανομένων των email, των συνημμένων, των σημειώσεων και του ιστορικού του). Ένα μέλος του προσωπικού μπορεί να προσεγγίσει ένα αίτημα μόνο αν του έχει δοθεί πρόσβαση στην εταιρεία του (επιλέγετε τις εταιρείες κάθε τεχνικού στο Σύστημα &rarr; Τεχνικοί ή παραχωρείτε πρόσβαση σε ολόκληρη ομάδα στο Σύστημα &rarr; Ομάδες), επομένως δεν υπάρχει τρόπος να παρεκκλίνει κανείς στα δεδομένα άλλου πελάτη. Ο διαχωρισμός αυτός επιβάλλεται παντού στο παρασκήνιο και όχι απλώς αποκρύπτεται από την προβολή. Σε εγκατάσταση με μία εταιρεία είναι αυτόματος και αόρατος &mdash; υπάρχει μόνο μία εταιρεία, επομένως όλα απλώς ανήκουν σε αυτήν.',
            'tip' => 'Σε εγκατάσταση με μία εταιρεία τίποτα από αυτά δεν εμφανίζεται &mdash; υπάρχει μία εταιρεία, κάθε αίτημα ανήκει σε αυτήν και δεν υπάρχει εναλλάκτης ή διαλογή. Αυτές οι λειτουργίες ενεργοποιούνται μόνο όταν υπάρξει δεύτερη εταιρεία.',
        ],
    ],
    'help_sla' => [
        'page_title' => 'Διαχείριση SLA',
        'back_link' => '&larr; Πίσω στον οδηγό Αιτημάτων',
        'sidebar_title' => 'Οδηγός SLA',
        'hero_title' => 'Διαχείριση SLA',
        'hero_sub' => 'Στόχοι απόκρισης και επίλυσης που λαμβάνουν υπόψη τις ώρες εργασίας, με ειδοποιήσεις παραβίασης ανά τμήμα',
        'nav' => [
            'overview' => 'Επισκόπηση',
            'building_blocks' => 'Βασικά στοιχεία',
            'behaviour_settings' => 'Ρυθμίσεις συμπεριφοράς',
            'breach_notifications' => 'Ειδοποιήσεις παραβίασης',
            'cron_setup' => 'Ρύθμιση εργασίας cron',
            'worked_examples' => 'Παραδείγματα',
            'troubleshooting' => 'Αντιμετώπιση προβλημάτων',
        ],
        'overview' => [
            'heading' => 'Επισκόπηση',
            'sub' => 'Τι είναι τα SLA, γιατί έχουν σημασία και πώς λειτουργεί σε γενικές γραμμές η μηχανή SLA του FreeITSM.',
            'p1' => 'Μια Συμφωνία Επιπέδου Υπηρεσιών (SLA) είναι μια δέσμευση για το πόσο γρήγορα θα απαντήσει και θα επιλύσει η ομάδα σας ένα αίτημα. Το FreeITSM παρακολουθεί δύο χρονόμετρα ανά αίτημα: την <strong>απόκριση</strong> (χρόνος από τη δημιουργία του αιτήματος έως την πρώτη ενέργεια τεχνικού) και την <strong>επίλυση</strong> (χρόνος από τη δημιουργία του αιτήματος έως το κλείσιμό του). Και οι δύο στόχοι ορίζονται ανά προτεραιότητα &mdash; έτσι ένα P1 μπορεί να έχει 30 λεπτά για απόκριση και 4 ώρες για επίλυση, ενώ ένα P4 μπορεί να έχει 8 ώρες εργασίας και 5 εργάσιμες ημέρες.',
            'switch_note' => 'Δεν χρησιμοποιείτε SLA; Απενεργοποιήστε το SLA στο <strong>Σύστημα &rarr; Ενότητες &rarr; Διαθεσιμότητα &rarr; Λειτουργίες αιτημάτων</strong>: τα χρονόμετρα, οι προειδοποιήσεις παραβίασης και τα έναυσμα SLA των ροών εργασιών σταματούν, ενώ τα ημερολόγια εργασίας παραμένουν για τις ώρες λειτουργίας του web chat. Όταν το ενεργοποιήσετε ξανά, ερωτάστε αν θα σταλούν οι προειδοποιήσεις που χάθηκαν όσο ήταν απενεργοποιημένο ή αν θα παραλειφθούν.',
            'p2' => 'Η μηχανή SLA του FreeITSM βασίζεται σε τέσσερις σχεδιαστικές επιλογές που αξίζει να κατανοήσετε:',
            'choice_business' => '<strong>Ώρες εργασίας, όχι ώρα ρολογιού.</strong> Ένα P2 που δημιουργείται στις 4:30 μ.μ. με στόχο απόκρισης 1 ώρας δεν παραβιάζεται στις 5:30 μ.μ. αν το γραφείο κλείνει στις 5 μ.μ. Το χρονόμετρο συνεχίζεται στις 9 π.μ. της επόμενης εργάσιμης ημέρας. Αυτό είναι το πρότυπο του κλάδου και το μόνο δίκαιο μοντέλο όταν οι τεχνικοί φεύγουν το βράδυ.',
            'choice_pause' => '<strong>Δυνατότητα παύσης.</strong> Όταν ένα αίτημα βρίσκεται σε κατάσταση με την ένδειξη «Παύση SLA» (όπως <em>Αναμονή απάντησης</em> ή <em>Σε αναμονή</em>), το χρονόμετρο σταματά. Συνεχίζεται όταν το αίτημα επιστρέψει σε κατάσταση εργασίας.',
            'choice_compute' => '<strong>Υπολογισμός κατά την ανάγνωση, χωρίς αποθήκευση.</strong> Η μηχανή υπολογίζει ξανά την κατάσταση SLA από το αρχείο καταγραφής του αιτήματος κάθε φορά που το βλέπετε. Δεν υπάρχουν αποθηκευμένοι μετρητές που μπορούν να χάσουν τον συγχρονισμό τους. Αν αλλάξετε αργότερα τις ώρες ενός ημερολογίου εργασίας, το SLA κάθε παλαιού αιτήματος υπολογίζεται ξανά με τις νέες ώρες την επόμενη φορά που θα προβληθεί.',
            'choice_cutoff' => '<strong>Όριο εφαρμογής.</strong> Μια ημερομηνία «Εφαρμογή SLA από» που ελέγχεται από τον διαχειριστή εξασφαλίζει ότι τα υπάρχοντα αιτήματα του συστήματός σας δεν θα θεωρηθούν ξαφνικά παραβιασμένα αναδρομικά όταν ενεργοποιήσετε τα SLA. Παρακολουθούνται μόνο τα αιτήματα που δημιουργήθηκαν την ημερομηνία αυτή ή μετά.',
            'tip' => 'Αν είστε νέοι στο ITIL: ο χρόνος απόκρισης αφορά την αναγνώριση (κάποιος ανέλαβε το αίτημα)· ο χρόνος επίλυσης αφορά την ολοκλήρωση (το πρόβλημα του χρήστη διορθώθηκε). Τα δύο χρονόμετρα τρέχουν ανεξάρτητα και έχουν διαφορετικούς στόχους.',
        ],
        'blocks' => [
            'heading' => 'Τα τέσσερα βασικά στοιχεία',
            'sub' => 'Ρυθμίστε αυτά τα τέσσερα και η παρακολούθηση SLA λειτουργεί. Όλα τα υπόλοιπα είναι προαιρετικές βελτιώσεις.',
            'cal_heading' => '1. Ημερολόγια εργασίας',
            'cal_intro' => 'Ένα ημερολόγιο ορίζει πότε λειτουργεί το service desk σας. Κάθε ημερολόγιο έχει:',
            'cal_tz' => '<strong>Ζώνη ώρας</strong> &mdash; ένα αναγνωριστικό ζώνης ώρας IANA (π.χ. <code>Europe/London</code>, <code>America/New_York</code>, <code>Asia/Singapore</code>). Οι αλλαγές θερινής ώρας διαχειρίζονται αυτόματα.',
            'cal_hours' => '<strong>Εβδομαδιαίες ώρες εργασίας</strong> &mdash; μία γραμμή ανά ημέρα της εβδομάδας με πλαίσιο ελέγχου «Ανοιχτό» και ώρες έναρξης / λήξης. Τα νέα ημερολόγια έχουν από προεπιλογή Δευτέρα-Παρασκευή 09:00-17:00, με Σάββατο/Κυριακή κλειστά. Μια γραμμή χωρίς την ένδειξη «Ανοιχτό» σημαίνει ότι το γραφείο είναι κλειστό εκείνη την ημέρα.',
            'cal_holidays' => '<strong>Αργίες</strong> &mdash; ημερομηνία + προαιρετικό όνομα. Οι αργίες υπερισχύουν του εβδομαδιαίου προγράμματος (το γραφείο είναι κλειστό ακόμη κι αν η αργία πέφτει Δευτέρα).',
            'cal_default' => '<strong>Προεπιλεγμένο</strong> &mdash; ακριβώς ένα ημερολόγιο είναι το προεπιλεγμένο. Οι νέες προτεραιότητες το κληρονομούν, εκτός αν ορίσετε κάτι άλλο.',
            'cal_outro' => 'Μπορείτε να δημιουργήσετε όσα ημερολόγια χρειάζεστε &mdash; ένα ανά γραφείο, ένα ανά ομάδα, ένα για VIP πελάτες με εκτεταμένο ωράριο. Χρησιμοποιούνται από τους στόχους SLA και τη μηχανή ελέγχου παραβίασης.',
            'prio_heading' => '2. Προτεραιότητες με στόχους SLA',
            'prio_intro' => 'Στην καρτέλα Προτεραιότητες (ή μέσω του πίνακα Στόχοι SLA στην καρτέλα SLA), κάθε προτεραιότητα μπορεί να έχει:',
            'prio_response' => '<strong>Στόχος απόκρισης (λεπτά)</strong> &mdash; πόσος χρόνος μέχρι την πρώτη ενέργεια τεχνικού.',
            'prio_resolution' => '<strong>Στόχος επίλυσης (λεπτά)</strong> &mdash; πόσος χρόνος μέχρι το κλείσιμο του αιτήματος.',
            'prio_calendar' => '<strong>Ημερολόγιο</strong> &mdash; σε ποιο ημερολόγιο εργασίας βασίζεται το χρονόμετρο αυτής της προτεραιότητας. Αφήστε το κενό για να χρησιμοποιηθεί το προεπιλεγμένο ημερολόγιο.',
            'prio_outro' => 'Αν αφήσετε κενά και τα δύο πεδία στόχων, η παρακολούθηση SLA απενεργοποιείται εντελώς για αυτή την προτεραιότητα &mdash; χρήσιμο για μια προτεραιότητα «Ενημερωτική» ή «Εκκρεμότητες» όπου δεν υπάρχει χρονική πίεση.',
            'pause_heading' => '3. Καταστάσεις παύσης SLA',
            'pause_intro' => 'Στην καρτέλα Καταστάσεις υπάρχει ειδική στήλη «Παύση SLA». Σημειώστε κάθε κατάσταση που δείχνει ότι το αίτημα περιμένει κάτι εκτός ελέγχου της ομάδας. Οι συνήθεις υποψήφιες είναι:',
            'pause_awaiting' => '<strong>Αναμονή απάντησης</strong> &mdash; ο πελάτης οφείλει να μας δώσει πληροφορίες. Σχεδόν παντού αποδεκτή ως δίκαιη παύση.',
            'pause_vendor' => '<strong>Σε αναμονή (προμηθευτής)</strong> &mdash; αναμονή για την υποστήριξη της Microsoft / τρίτου.',
            'pause_change' => '<strong>Σε αναμονή (παράθυρο αλλαγής)</strong> &mdash; προγραμματισμένο για μελλοντικό παράθυρο συντήρησης.',
            'pause_parts' => '<strong>Σε αναμονή (ανταλλακτικά)</strong> &mdash; αναμονή για παράδοση υλικού.',
            'pause_warn' => 'Μια γενική κατάσταση «Σε αναμονή» μπορεί να καταχραστεί ως δικλείδα διαφυγής από το SLA όταν ένα αίτημα είναι δύσκολο ή ο τεχνικός είναι απασχολημένος. Αν η ομάδα σας έχει πειθαρχία, δεν υπάρχει πρόβλημα. Αν όχι, σκεφτείτε να την αντικαταστήσετε με τις πιο συγκεκριμένες παραλλαγές παραπάνω ή βασιστείτε στον πίνακα ελέγχου <strong>Watchtower</strong>, που επισημαίνει με πορτοκαλί ειδοποίηση τα αιτήματα σε παύση για πάνω από 24 ώρες.',
            'cutoff_heading' => '4. Όριο εφαρμογής (<code>Enforce SLAs from</code>)',
            'cutoff_p1' => 'Η πιο σημαντική καθολική ρύθμιση. Μέχρι να ορίσετε εδώ ημερομηνία και ώρα, η παρακολούθηση SLA είναι εντελώς απενεργοποιημένη &mdash; δεν τρέχουν χρονόμετρα, δεν εμφανίζονται ενδείξεις στα εισερχόμενα, δεν αποστέλλονται email παραβίασης. Αν την ορίσετε σε παρελθοντική ημερομηνία και ώρα, τα SLA ενεργοποιούνται αναδρομικά από εκείνο το σημείο. Αν την ορίσετε σε μελλοντική, προγραμματίζεται η ενεργοποίηση.',
            'cutoff_p2' => 'Οι περισσότερες ομάδες την ορίζουν σε «τώρα» όταν ενεργοποιούν για πρώτη φορά τα SLA &mdash; τα υπάρχοντα αιτήματα διατηρούν την κατάστασή τους πριν από το SLA και τα νέα αιτήματα από εκείνη τη στιγμή και μετά παρακολουθούνται.',
        ],
        'behaviour' => [
            'heading' => 'Ρυθμίσεις συμπεριφοράς',
            'sub' => 'Αυτές ελέγχουν πώς αντιδρά η μηχανή σε ειδικές περιπτώσεις. Οι προεπιλογές είναι λογικές &mdash; χρειάζεται να τις αναθεωρήσετε μόνο αν έχετε συγκεκριμένη προτίμηση.',
            'prio_heading' => 'Όταν αλλάζει η προτεραιότητα εν εξελίξει',
            'prio_intro' => 'Αν ένα αίτημα P3 αναβαθμιστεί σε P1 στα μισά του δρόμου (επειδή το πρόβλημα αποδεικνύεται μεγαλύτερο από ό,τι νομίζατε), υπάρχουν τρεις εύλογες συμπεριφορές:',
            'prio_forward' => '<strong>Προώθηση (προεπιλογή)</strong> &mdash; διατηρούνται τα συσσωρευμένα λεπτά εργασίας και απλώς αλλάζει ο στόχος. Αν το αίτημα είχε καταναλώσει 2 ώρες από τον στόχο των 8 ωρών του P3, τώρα έχει 2 ώρες που καταναλώθηκαν έναντι του στόχου 1 ώρας του P1 &mdash; άρα έχει ήδη παραβιαστεί. Αυτό θεωρείται σωστό: το πρόβλημα ήταν P1 από την αρχή, απλώς η ομάδα δεν το είχε καταλάβει.',
            'prio_recompute' => '<strong>Επανυπολογισμός</strong> &mdash; μηδενίζεται το χρονόμετρο και εφαρμόζεται ο νέος στόχος αναδρομικά από τη δημιουργία του αιτήματος. Ένας καθαρός επανυπολογισμός.',
            'prio_reset' => '<strong>Επαναφορά</strong> &mdash; ξεκινά νέο χρονόμετρο από τη στιγμή της αλλαγής προτεραιότητας. Η πιο επιεικής επιλογή για την ομάδα, αλλά οι πελάτες μπορεί να νιώσουν αδικημένοι αν ένα αίτημα υψηλής προτεραιότητας αποκτά ξαφνικά νέο, μεγάλο χρονόμετρο.',
            'reopen_heading' => 'Όταν ανοίγει ξανά ένα κλειστό αίτημα',
            'reopen_intro' => 'Αν ένα αίτημα ανοίξει ξανά (ο χρήστης απαντά μετά το κλείσιμο):',
            'reopen_reset' => '<strong>Επαναφορά (προεπιλογή)</strong> &mdash; ξεκινούν νέα χρονόμετρα απόκρισης και επίλυσης από τη στιγμή της επανεκκίνησης. Το άνοιγμα αντιμετωπίζεται ουσιαστικά ως νέο αίτημα.',
            'reopen_continue' => '<strong>Συνέχεια</strong> &mdash; συνεχίζεται από τον χρόνο που είχε παρέλθει κατά το κλείσιμο. Εξακολουθούν να ισχύουν οι αρχικοί στόχοι SLA.',
            'first_heading' => 'Ορισμός πρώτης απόκρισης',
            'first_intro' => 'Τι θεωρείται «πρώτη απόκριση» &mdash; η στιγμή που σταματά το χρονόμετρο απόκρισης;',
            'first_either' => '<strong>Οποιαδήποτε (προεπιλογή)</strong> &mdash; η πρώτη ενέργεια τεχνικού οποιουδήποτε είδους: εξερχόμενο email, αλλαγή κατάστασης, ανάθεση.',
            'first_status' => '<strong>Αλλαγή κατάστασης</strong> &mdash; μετράει μόνο η αλλαγή κατάστασης από την προεπιλεγμένη. Πιο αυστηρό &mdash; ο τεχνικός πρέπει να έχει πράγματι εργαστεί στο αίτημα, όχι απλώς να το έχει ανοίξει.',
            'first_email' => '<strong>Εξερχόμενο email</strong> &mdash; μετράει μόνο μια απάντηση με email προς τον αιτούντα. Το πιο αυστηρό &mdash; ο πελάτης πρέπει να έχει ακούσει νέα μας.',
            'warn_heading' => 'Ποσοστό ορίου προειδοποίησης',
            'warn_body' => 'Πόσο μέσα στον στόχο SLA πρέπει να βρίσκεται το αίτημα ώστε η ένδειξη να αλλάξει από πράσινη σε πορτοκαλί. Η προεπιλογή είναι 80% &mdash; έτσι ένας στόχος απόκρισης 60 λεπτών γίνεται πορτοκαλί στα 48 λεπτά. Καθορίζει επίσης τις ειδοποιήσεις παραβίασης τύπου προειδοποίησης.',
        ],
        'breach' => [
            'heading' => 'Ειδοποιήσεις παραβίασης',
            'sub' => 'Κανόνες email ανά τμήμα, που ενεργοποιούνται όταν τα SLA πλησιάζουν την παραβίαση (προειδοποίηση) ή παραβιάζονται πράγματι.',
            'intro' => 'Κάθε κανόνας έχει τέσσερις διαστάσεις, όλες ανεξάρτητες:',
            'scope_heading' => '1. Εύρος',
            'scope_body' => 'Είτε <strong>Προεπιλογή</strong> (ο κανόνας ισχύει για αιτήματα όλων των τμημάτων) είτε ένα <strong>συγκεκριμένο τμήμα</strong>. Επίλυση σύγκρουσης: ένας κανόνας συγκεκριμένου τμήματος υπερισχύει του προεπιλεγμένου για τα αιτήματα του τμήματος αυτού. Χωρίς προεπιλεγμένο κανόνα, τα τμήματα που δεν έχουν συγκεκριμένο κανόνα δεν λαμβάνουν ειδοποιήσεις.',
            'trigger_heading' => '2. Έναυσμα',
            'trigger_body' => 'Είτε <strong>Προειδοποίηση</strong> (το αίτημα έχει ξεπεράσει το όριο προειδοποίησης &mdash; πιθανή παραβίαση) είτε <strong>Παραβίαση</strong> (το αίτημα έχει ξεπεράσει τον στόχο του &mdash; πραγματική παραβίαση). Καθένα είναι ξεχωριστός κανόνας, ώστε να μπορείτε να ειδοποιείτε διαφορετικά άτομα για το καθένα.',
            'target_heading' => '3. Στόχος',
            'target_body' => 'Ποιο χρονόμετρο θα παρακολουθείται &mdash; <strong>Απόκριση</strong>, <strong>Επίλυση</strong> ή <strong>Και τα δύο</strong>.',
            'recip_heading' => '4. Παραλήπτες',
            'recip_intro' => 'Οποιοσδήποτε συνδυασμός από:',
            'recip_assignee' => '<strong>Ο ανατεθειμένος του αιτήματος</strong> &mdash; ο τεχνικός που έχει αυτή τη στιγμή το αίτημα. Παραλείπεται αν δεν έχει ανάθεση.',
            'recip_teams' => '<strong>Τα μέλη των ομάδων του τμήματος του αιτήματος</strong> &mdash; κάθε τεχνικός σε οποιαδήποτε ομάδα συσχετισμένη με το τμήμα του αιτήματος. Καλύπτει ολόκληρη την ουρά χωρίς να χρειάζεται λίστα διανομής.',
            'recip_specific' => '<strong>Συγκεκριμένος τεχνικός</strong> &mdash; το μοτίβο «υπεύθυνος SLA» / «υπεύθυνος υπηρεσιών», όπου πρόκειται για ονομαστικό πρόσωπο και όχι για ρόλο.',
            'recip_custom' => '<strong>Προσαρμοσμένες διευθύνσεις email</strong> &mdash; ελεύθερο κείμενο χωρισμένο με κόμματα. Χρήσιμο για κοινά γραμματοκιβώτια (<code>sla-alerts@company.com</code>), γέφυρες email προς Slack/Teams ή λίστες διανομής.',
            'tip' => 'Κάθε αίτημα στέλνει το πολύ ένα email ανά (στόχο, έναυσμα) &mdash; η εργασία cron καταγράφει τι έχει σταλεί στον πίνακα <code>sla_notifications_sent</code>. Έτσι μια προειδοποίηση στέλνεται μία φορά, μια παραβίαση στέλνεται μία φορά και τίποτε άλλο &mdash; χωρίς βρόχους ανεπιθύμητων μηνυμάτων.',
            'warn' => '<strong>Χωρίς κανόνες = χωρίς email.</strong> Ακόμη κι αν κάθε αίτημα του συστήματος παραβιαστεί, τίποτα δεν αποστέλλεται μέχρι να προσθέσετε τουλάχιστον έναν κανόνα. Ξεκινήστε με ένα ζεύγος Προειδοποίηση + Παραβίαση με εύρος Προεπιλογή, ώστε να καλύπτονται όλα.',
        ],
        'cron' => [
            'heading' => 'Ρύθμιση της εργασίας cron',
            'sub' => 'Το σενάριο ελέγχου παραβίασης πρέπει να εκτελείται με πρόγραμμα. Μία φορά κάθε 5 λεπτά είναι η ιδανική συχνότητα.',
            'p1' => 'Οι ενδείξεις SLA που φαίνονται στη διεπαφή (ενδείξεις στα εισερχόμενα, πάνελ στο παράθυρο ανάγνωσης) υπολογίζονται επί τόπου όταν φορτώνεται μια σελίδα. Όμως τα email παραβίασης μπορούν να σταλούν μόνο αν <em>κάτι</em> ελέγχει προληπτικά τα αιτήματα ακόμη και όταν κανείς δεν κοιτάζει. Αυτό το κάτι είναι μια προγραμματισμένη εργασία &mdash; στα Windows ο Προγραμματιστής εργασιών (Task Scheduler), στο Linux το cron.',
            'p2' => 'Το σενάριο είναι το <code>cron/sla_breach_check.php</code> στον φάκελο εγκατάστασης του FreeITSM. Μπορεί να κληθεί με δύο τρόπους:',
            'cli_heading' => 'Α. CLI (προτείνεται σε διακομιστή που ελέγχετε)',
            'cli_note' => 'Δεν απαιτείται έλεγχος ταυτότητας &mdash; τα δικαιώματα του συστήματος αρχείων ελέγχουν ήδη ποιος μπορεί να το εκτελέσει.',
            'http_heading' => 'Β. HTTP (για κοινόχρηστη φιλοξενία ή απομακρυσμένους προγραμματιστές)',
            'http_note' => 'Το διακριτικό (token) δημιουργείται αυτόματα κατά την πρώτη εγκατάσταση και αποθηκεύεται στο <code>system_settings</code> με το κλειδί <code>sla_cron_token</code> (32 δεκαεξαδικοί χαρακτήρες, ~128 bit εντροπίας). Είναι κρυπτογραφημένο κατά την αποθήκευση, οπότε αν διαβάσετε απευθείας τη γραμμή θα δείτε <code>ENC:…</code> και όχι το διακριτικό. Βρείτε το δικό σας με:',
            'win_heading' => 'Προγραμματιστής εργασιών των Windows',
            'win_intro' => 'Ανοίξτε τον Προγραμματιστή εργασιών (<code>taskschd.msc</code>) και δημιουργήστε μια νέα εργασία με αυτές τις ρυθμίσεις:',
            'tbl_field' => 'Πεδίο',
            'tbl_value' => 'Τιμή',
            'win_r1_k' => 'Όνομα',
            'win_r1_v' => 'FreeITSM &mdash; Έλεγχος παραβίασης SLA',
            'win_r2_k' => 'Εκτέλεση είτε είναι συνδεδεμένος ο χρήστης είτε όχι',
            'win_r2_v' => 'Επιλέξτε το',
            'win_r3_k' => 'Έναυσμα',
            'win_r3_v' => 'Καθημερινά, επανάληψη κάθε 1 ημέρα, επανάληψη κάθε 5 λεπτά για 1 ημέρα',
            'win_r4_k' => 'Ενέργεια',
            'win_r4_v' => 'Εκκίνηση προγράμματος',
            'win_r5_k' => 'Πρόγραμμα/σενάριο',
            'win_r5_v' => '<code>C:\\wamp64\\bin\\php\\php8.2.x\\php.exe</code>',
            'win_r6_k' => 'Προσθήκη ορισμάτων',
            'win_r6_v' => '<code>C:\\wamp64\\www\\freeitsm-app\\cron\\sla_breach_check.php</code>',
            'win_r7_k' => 'Έναρξη σε',
            'win_r7_v' => '<code>C:\\wamp64\\www\\freeitsm-app</code>',
            'linux_heading' => 'Linux cron',
            'linux_intro' => 'Προσθέστε μία γραμμή στο crontab σας (<code>crontab -e</code>):',
            'sec_heading' => 'Ασφάλεια &mdash; τι προστατεύει το σημείο πρόσβασης HTTP',
            'sec_intro' => 'Τρία επίπεδα, όλα εφαρμόζονται αυτόματα:',
            'sec_token' => '<strong>1. Διακριτικό κοινού μυστικού</strong> &mdash; τυχαίο 128 bit ανά εγκατάσταση, με σύγκριση σταθερού χρόνου για αποτροπή επιθέσεων χρονισμού.',
            'sec_lockout' => '<strong>2. Αποκλεισμός ανά IP μετά από αποτυχημένο έλεγχο ταυτότητας</strong> &mdash; περισσότερες από 10 προσπάθειες με λάθος διακριτικό από την ίδια IP μέσα στην τελευταία ώρα προκαλούν αποκλεισμό 429 διάρκειας 1 ώρας. Αποτρέπει την εξαντλητική δοκιμή χωρίς να χρειάζεται fail2ban.',
            'sec_interval' => '<strong>3. Ελάχιστο διάστημα μεταξύ επιτυχημένων εκτελέσεων</strong> &mdash; <code>sla_cron_min_interval_seconds</code> (προεπιλογή 30 δ). Ακόμη και ένα αίτημα με έγκυρο διακριτικό λαμβάνει 429 αν φτάσει νωρίτερα από αυτό το διάστημα μετά την τελευταία επιτυχημένη εκτέλεση. Αποτρέπει τον κατά λάθος διπλό προγραμματισμό και τους ανεξέλεγκτους βρόχους.',
            'log_heading' => 'Αρχείο δραστηριότητας',
            'log_body' => 'Κάθε κλήση (αποδεκτή ή απορριφθείσα) καταγράφεται στον πίνακα <code>sla_cron_runs</code> με χρονισμό, αποτέλεσμα, μετρητές και IP του πελάτη. Δείτε τις τελευταίες 20 εκτελέσεις στο πάνελ <strong>Δραστηριότητα cron</strong> στο κάτω μέρος της καρτέλας ρυθμίσεων SLA &mdash; χρήσιμο για να επαληθεύσετε ότι το πρόγραμμα εκτελείται και για να ελέγξετε τυχόν αποτυχημένες απόπειρες ελέγχου ταυτότητας. Οι γραμμές διαγράφονται αυτόματα μετά από <code>sla_cron_log_retention_days</code> (προεπιλογή 30), ώστε ο πίνακας να παραμένει μικρός.',
        ],
        'examples' => [
            'heading' => 'Παραδείγματα',
            'sub' => 'Από την απλή περίπτωση μίας ζώνης ώρας έως την πιο δύσκολη περίπτωση πολλών ζωνών ώρας, όπου πρέπει να οριστεί τι σημαίνει «δίκαιο».',
            'ex1_heading' => 'Παράδειγμα 1: Αίτημα από το Ηνωμένο Βασίλειο, service desk στο Ηνωμένο Βασίλειο',
            'ex1_title' => 'Η απλή περίπτωση',
            'ex1_tag' => 'μία ζώνη ώρας',
            'ex1_setup' => '<strong>Ρύθμιση:</strong> Ένα ημερολόγιο εργασίας με όνομα <em>Γραφείο ΗΒ</em> με ζώνη ώρας <code>Europe/London</code>, Δευτέρα-Παρασκευή 09:00-17:00, χωρίς αργίες. Η προτεραιότητα P2 έχει στόχο απόκρισης 1 ώρας και στόχο επίλυσης 4 ωρών, και τα δύο με βάση το ημερολόγιο <em>Γραφείο ΗΒ</em>.',
            'ex1_scenario' => '<strong>Σενάριο:</strong> Ο χρήστης δημιουργεί ένα αίτημα P2 στις <strong>16:30 ώρα ΗΒ την Τετάρτη</strong>.',
            'ex1_timeline' => 'Τετ 16:30 ΗΒ &mdash; <strong>δημιουργία αιτήματος</strong>, ξεκινά το χρονόμετρο απόκρισης.
Τετ 17:00 ΗΒ &mdash; το γραφείο κλείνει, το χρονόμετρο σταματά (καταναλώθηκαν 30 λεπτά από τον στόχο των 60).
Πεμ 09:00 ΗΒ &mdash; το γραφείο ανοίγει, το χρονόμετρο συνεχίζεται.
Πεμ 09:30 ΗΒ &mdash; ο τεχνικός απαντά. Το SLA απόκρισης τηρήθηκε την τελευταία στιγμή (καταναλώθηκαν 60 λεπτά, στόχος 60 λεπτά).',
            'ex1_outro' => 'Αν ο τεχνικός δεν είχε απαντήσει μέχρι την <strong>Πέμπτη 10:00 ώρα ΗΒ</strong>, η απόκριση θα είχε <strong>παραβιαστεί κατά 30 λεπτά</strong> (καταναλώθηκαν 90 λεπτά έναντι στόχου 60 λεπτών &mdash; 30 από το απόγευμα της Τετάρτης, 60 από το πρωί της Πέμπτης). Το χρονόμετρο της 1 ώρας μετράει μόνο στις ώρες εργασίας, αλλά ένα αίτημα που δημιουργείται στο τέλος της ημέρας καταναλώνει μεγάλο μέρος του χρόνου του όσο το γραφείο είναι κλειστό &mdash; είναι εύκολο για έναν τεχνικό που φτάνει στις 09:00 να υποθέσει ότι έχει ολόκληρη την ώρα, ενώ στην πραγματικότητα απομένουν μόνο 30 λεπτά.',
            'ex2_heading' => 'Παράδειγμα 2: Αίτημα από το Ηνωμένο Βασίλειο, service desk στην Εσθονία',
            'ex2_title' => 'Η περίπτωση πολλών ζωνών ώρας',
            'ex2_tag' => '3 τρόποι να οριστεί το «δίκαιο»',
            'ex2_setup' => '<strong>Ρύθμιση:</strong> Πελάτες στο Ηνωμένο Βασίλειο (<code>Europe/London</code>, GMT/BST), service desk στην Εσθονία (<code>Europe/Tallinn</code>, EET/EEST &mdash; <strong>2 ώρες μπροστά από το ΗΒ</strong>). Και τα δύο γραφεία δουλεύουν κανονικά 09:00-17:00 τοπική ώρα.',
            'ex2_scenario' => '<strong>Σενάριο:</strong> Ένας πελάτης από το ΗΒ δημιουργεί ένα αίτημα P2 στις <strong>16:30 ώρα ΗΒ την Παρασκευή</strong> (= 18:30 στην Εσθονία, μετά το κλείσιμο του γραφείου της Εσθονίας). Η επόμενη ευκαιρία για έναν τεχνικό της Εσθονίας να το χειριστεί είναι η Δευτέρα 09:00 ώρα Εσθονίας (= 07:00 ώρα ΗΒ). Ο στόχος απόκρισης είναι 1 ώρα.',
            'ex2_question' => 'Τι πρέπει να λέει το SLA; Υπάρχουν τρεις υποστηρίξιμες απαντήσεις, καθεμία δίκαιη με διαφορετικό τρόπο. Εσείς επιλέγετε ποιο ημερολόγιο θα αντιστοιχίσετε στην προτεραιότητα, ανάλογα με το τι υπόσχεται η σύμβαση υπηρεσιών σας.',
            'optA_label' => 'Επιλογή Α &mdash; Με επίκεντρο τον πελάτη',
            'optA_p1' => '<strong>Ορίστε την προτεραιότητα να χρησιμοποιεί ημερολόγιο με ώρες <em>ΗΒ</em>.</strong> Το χρονόμετρο τρέχει με βάση τις 09:00-17:00 ώρα ΗΒ, ανεξάρτητα από το πού βρίσκεται ο τεχνικός.',
            'optA_p2' => 'Στο παραπάνω σενάριο, με το αίτημα να δημιουργείται στις 16:30 ώρα ΗΒ την Παρασκευή: το χρονόμετρο τρέχει 16:30&ndash;17:00 ώρα ΗΒ την Παρασκευή (καταναλώθηκαν 30 λεπτά), σταματά το βράδυ και το Σαββατοκύριακο, και συνεχίζεται τη Δευτέρα 09:00 ώρα ΗΒ. Αν ένας τεχνικός της Εσθονίας απαντήσει στις 10:00 ώρα Εσθονίας τη Δευτέρα (= 08:00 ώρα ΗΒ), το ημερολόγιο ΗΒ είναι ακόμη σε παύση (το γραφείο του ΗΒ ανοίγει στις 09:00 ώρα ΗΒ), επομένως δεν μετράνε επιπλέον λεπτά &mdash; η κατανάλωση παραμένει στα 30 λεπτά. <strong>Το SLA τηρήθηκε με περιθώριο 30 λεπτών</strong>. Οποιαδήποτε απάντηση μετά τις 09:30 ώρα ΗΒ (= 11:30 ώρα Εσθονίας) θα το παραβίαζε.',
            'optA_p3' => '<em>Δίκαιο για:</em> τον πελάτη. Η εμπειρία του ταιριάζει με τη δική του εργάσιμη ημέρα.<br><em>Αντιστάθμισμα:</em> Οι τεχνικοί της Εσθονίας πρέπει να είναι διαθέσιμοι 09:00-17:00 ώρα ΗΒ (= 11:00-19:00 ώρα Εσθονίας), κάτι που επεκτείνει την εργάσιμη ημέρα τους κατά 2 ώρες.',
            'optB_label' => 'Επιλογή Β &mdash; Με επίκεντρο τον τεχνικό',
            'optB_p1' => '<strong>Ορίστε την προτεραιότητα να χρησιμοποιεί ημερολόγιο με ώρες <em>Εσθονίας</em>.</strong> Το χρονόμετρο τρέχει με βάση τις 09:00-17:00 ώρα Εσθονίας.',
            'optB_p2' => 'Ίδιο σενάριο: το αίτημα δημιουργείται στις 18:30 ώρα Εσθονίας την Παρασκευή (μετά το κλείσιμο), το χρονόμετρο μένει σε παύση όλο το Σαββατοκύριακο και ξεκινά τη Δευτέρα 09:00 ώρα Εσθονίας (= 07:00 ώρα ΗΒ). Αν ο τεχνικός απαντήσει στις 09:30 ώρα Εσθονίας τη Δευτέρα (= 07:30 ώρα ΗΒ), το SLA απόκρισης έχει καταναλώσει 30 λεπτά από τον στόχο των 60 &mdash; <strong>τηρήθηκε με περιθώριο 30 λεπτών</strong>. Ο πελάτης του ΗΒ δημιούργησε το αίτημα στις 16:30 ώρα ΗΒ την Παρασκευή και έλαβε απάντηση στις 07:30 ώρα ΗΒ τη Δευτέρα &mdash; ο πραγματικός χρόνος αναμονής του ήταν πολύ μεγαλύτερος από όσο υποδηλώνει το SLA.',
            'optB_p3' => '<em>Δίκαιο για:</em> τους τεχνικούς. Εργάζονται κανονικό ωράριο.<br><em>Αντιστάθμισμα:</em> Οι πελάτες στο ΗΒ μπορεί να νιώσουν ότι το SLA «λέει ψέματα» αν ένα αίτημα της Παρασκευής το απόγευμα δεν επιβεβαιωθεί μέχρι τη Δευτέρα το πρωί ώρα Εσθονίας, ενώ η αναφορά λέει ότι το SLA απόκρισης ήταν 1 ώρα. Φροντίστε η σύμβαση υπηρεσιών σας να διευκρινίζει ότι το SLA ισχύει με βάση τις ώρες λειτουργίας του service desk.',
            'optC_label' => 'Επιλογή Γ &mdash; Παράθυρο επικάλυψης (το πιο αυστηρό)',
            'optC_p1' => '<strong>Ορίστε την προτεραιότητα να χρησιμοποιεί ημερολόγιο που καλύπτει μόνο τις ώρες όπου και τα δύο γραφεία είναι ανοιχτά.</strong> Οι 09:00-17:00 ώρα ΗΒ επικαλύπτονται με τις 09:00-17:00 ώρα Εσθονίας (= 07:00-15:00 ώρα ΗΒ) στο <strong>παράθυρο 09:00-15:00 ώρα ΗΒ</strong> &mdash; 6 ώρες ανά εργάσιμη ημέρα.',
            'optC_p2' => 'Ίδιο σενάριο: το αίτημα δημιουργείται στις 16:30 ώρα ΗΒ την Παρασκευή (εκτός επικάλυψης, αφού η επικάλυψη κλείνει στις 15:00 ώρα ΗΒ), το χρονόμετρο μένει σε παύση το Σαββατοκύριακο και συνεχίζεται τη Δευτέρα 09:00 ώρα ΗΒ (= 11:00 ώρα Εσθονίας, τη στιγμή που ανοίγει ξανά η επικάλυψη). Αν ο τεχνικός της Εσθονίας απαντήσει στις 11:30 ώρα Εσθονίας (= 09:30 ώρα ΗΒ), το SLA απόκρισης έχει καταναλώσει 30 λεπτά από τον στόχο των 60 &mdash; <strong>τηρήθηκε με περιθώριο 30 λεπτών</strong>. Η απάντηση δόθηκε μέσα στο παράθυρο επικάλυψης, οπότε μετράει αμέσως.',
            'optC_p3' => '<em>Δίκαιο για:</em> και τις δύο πλευρές &mdash; το SLA μετράει μόνο τις ώρες που το γραφείο μπορεί πράγματι να προωθήσει το αίτημα ΚΑΙ ο πελάτης βρίσκεται στο γραφείο του για να λάβει απάντηση.<br><em>Αντιστάθμισμα:</em> Το μικρότερο ημερήσιο παράθυρο σημαίνει μεγαλύτερους πραγματικούς χρόνους για την επίτευξη φιλόδοξων στόχων. Ένας στόχος επίλυσης 4 ωρών καλύπτει 1,5 ημέρα επικάλυψης, ενώ με ένα κανονικό ημερολόγιο 8 ωρών θα ολοκληρωνόταν μέσα σε μία ημέρα.',
            'choose_tip' => '<strong>Πώς να επιλέξετε:</strong> Δείτε τη σύμβαση υπηρεσιών σας. Αν λέει «απόκριση εντός 1 ώρας από την παραλαβή» &mdash; αυτή είναι η Επιλογή Α (το χρονόμετρο του πελάτη). Αν λέει «απόκριση εντός 1 εργάσιμης ώρας» &mdash; συνήθως αυτή είναι η Επιλογή Β (όποιο γραφείο εργάζεται). Αν λέει «εντός 1 ώρας κοινής διαθεσιμότητας» &mdash; αυτή είναι η Επιλογή Γ. Αν δεν υπάρχει σύμβαση, ρωτήστε την ομάδα: θέλετε να νιώθετε πίεση εκτός ωρών Εσθονίας (Επιλογή Α) ή θέλετε οι πελάτες του ΗΒ να νιώθουν περιστασιακά ότι αγνοούνται (Επιλογή Β);',
            'ex3_heading' => 'Παράδειγμα 3: Παύση χρονομέτρου κατά την αναμονή προμηθευτή',
            'ex3_title' => 'Πώς λειτουργούν στην πράξη οι καταστάσεις παύσης',
            'ex3_tag' => 'παύση χρονομέτρου',
            'ex3_setup' => '<strong>Ρύθμιση:</strong> Προτεραιότητα P3 με στόχο επίλυσης 8 ωρών εργασίας, ημερολόγιο ΗΒ, κατάσταση «Αναμονή προμηθευτή» με την ένδειξη <em>Παύση SLA</em>.',
            'ex3_scenario' => '<strong>Σενάριο:</strong> Το αίτημα δημιουργείται τη Δευτέρα 09:00 ώρα ΗΒ. Ο τεχνικός το κλιμακώνει στη Microsoft τη Δευτέρα 11:00 ώρα ΗΒ και το μεταφέρει στην κατάσταση «Αναμονή προμηθευτή». Η Microsoft απαντά την Τετάρτη 14:00 ώρα ΗΒ. Ο τεχνικός εφαρμόζει τη διόρθωση και κλείνει το αίτημα την Πέμπτη 10:00 ώρα ΗΒ.',
            'ex3_timeline' => 'Δευ 09:00 &mdash; δημιουργία αιτήματος, το χρονόμετρο επίλυσης τρέχει.
Δευ 11:00 &mdash; μεταφορά σε «Αναμονή προμηθευτή», <strong>το χρονόμετρο σταματά</strong> (καταναλώθηκαν 2 ώρες).
Τετ 14:00 &mdash; μεταφορά πίσω σε «Σε εξέλιξη», <strong>το χρονόμετρο συνεχίζεται</strong>.
Τετ 17:00 &mdash; το γραφείο κλείνει (καταναλώθηκαν 5 ώρες συνολικά).
Πεμ 09:00 &mdash; το γραφείο ανοίγει.
Πεμ 10:00 &mdash; το αίτημα κλείνει (καταναλώθηκαν 6 ώρες συνολικά). <strong>Το SLA τηρήθηκε</strong> έναντι στόχου 8 ωρών.',
            'ex3_outro' => 'Πραγματικός χρόνος που πέρασε: ~3 ημέρες. Χρόνος SLA που πέρασε: 6 ώρες εργασίας. Χωρίς την ένδειξη κατάστασης παύσης, το SLA θα είχε μετρήσει και τις 2 ημέρες αναμονής προμηθευτή + τις ώρες εργασίας, συνολικά ~18 ώρες εργασίας &mdash; πολύ πάνω από το όριο παραβίασης.',
        ],
