            'r2_c' => 'Ελέγξτε το ιστορικό αλλαγών προτεραιότητας &mdash; αν η προτεραιότητα αναβαθμίστηκε εν εξελίξει και η συμπεριφορά έχει οριστεί σε «Προώθηση» (προεπιλογή), ο συσσωρευμένος χρόνος μεταφέρεται.',
