            'r5_s' => 'Το Watchtower εμφανίζει «N αιτήματα σε παύση για πάνω από 24 ώρες»',
            'r5_c' => 'Τα αιτήματα βρίσκονται σε κατάσταση παύσης SLA. Είτε κάποιος τα έβαλε εκεί επίτηδες και το ξέχασε, είτε κάποιος χρησιμοποιεί το «Σε αναμονή» ως δικλείδα διαφυγής από το SLA. Ανοίξτε το καθένα και είτε προχωρήστε το είτε αφαιρέστε την κατάσταση παύσης.',
